        fecha:        String(lineaAnulada[LX.fecha]    || ''),
        hora:         String(lineaAnulada[LX.hora]     || ''),
        staff:        String(lineaAnulada[LX.staff]    || ''),
        area:         String(lineaAnulada[LX.area]     || ''),
        servicio:     cambios.servicio     !== undefined ? String(cambios.servicio)      : String(lineaAnulada[LX.servicio]     || ''),
