// ── GANCHOS DE CICLO — tomar / finalizar (paso 2a: Lineas refleja todo el ciclo) ──
// Match PRINCIPAL por ID DE TICKET (promoRef) → único por línea, no colisiona aunque
// dos servicios compartan la misma área (ej. dos depilaciones). Respaldo: código+área,
// luego código+servicio, luego la primera activa (para líneas viejas sin id).
// Todo en try/catch: si falla, NO afecta la operación real (solo no espeja).
function _marcarLineaEstadoPorCodigo(codigo, ticketId, area, servicio, nuevoEstado, opts) {
  try {
    opts = opts || {};
    var ws = _hojaLineas();
    var d = ws.getDataRange().getValues();
    var activos = ['esperando', 'en_servicio', 'completado'];
    var matchTicket = -1, matchArea = -1, matchServ = -1, primera = -1;
    for (var i = 1; i < d.length; i++) {
      if (!_esHoy(d[i][LX.fecha])) continue;
      if (activos.indexOf(String(d[i][LX.estado])) === -1) continue;
      // id de ticket es único → match exacto, sin depender del código ni del área.
      // CASO E: no depender SOLO de promo_ref. Las líneas nacidas de la cola
      // (lineaDesdeListaEspera) tienen promo_ref vacío y se atan por ticket_ref
      // al asignarse. Antes, para un ticket LE- el match exacto nunca disparaba
      // y caíamos al respaldo difuso por área/servicio.
      if (ticketId && matchTicket === -1
          && (String(d[i][LX.promoRef])  === String(ticketId)
           || String(d[i][LX.ticketRef]) === String(ticketId))) matchTicket = i;
      // el resto de los respaldos sí requieren mismo código
      if (String(d[i][LX.codigo]) !== String(codigo)) continue;
      if (primera === -1) primera = i;
      if (area && matchArea === -1 && String(d[i][LX.area]) === String(area)) matchArea = i;
      if (servicio && matchServ === -1 && String(d[i][LX.servicio]) === String(servicio)) matchServ = i;
    }
    var fila = (matchTicket !== -1) ? matchTicket
             : (matchArea !== -1) ? matchArea
             : (matchServ !== -1) ? matchServ
             : primera;
    if (fila === -1) return { ok: false, motivo: 'sin linea activa para ' + (ticketId || codigo) };
    // dryRun: confirmar que la línea existe sin escribir nada. Permite validar
    // LINEAS antes de mutar el legacy (paso C antes del paso D).
    if (opts.dryRun === true) {
      return { ok: true, dryRun: true, id: d[fila][LX.id], estadoActual: String(d[fila][LX.estado]) };
    }
    var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');
    ws.getRange(fila + 1, LX.estado + 1).setValue(nuevoEstado);
    if (opts.staff) ws.getRange(fila + 1, LX.staff + 1).setValue(opts.staff);
    // Sello de ciclo (solo la primera vez de cada hito → mide el servicio sin pisarse):
    //   en_servicio → hora_toma (la staff la toma) · completado → hora_devuelta (vuelve a Mikaela)
    if (nuevoEstado === 'en_servicio' && !String(d[fila][LX.horaToma] || '').trim()) {
      ws.getRange(fila + 1, LX.horaToma + 1).setValue(stamp);
    }
    if (nuevoEstado === 'completado' && !String(d[fila][LX.horaDevuelta] || '').trim()) {
      ws.getRange(fila + 1, LX.horaDevuelta + 1).setValue(stamp);
    }
    ws.getRange(fila + 1, LX.actualizada + 1).setValue(stamp);

    // ── FIX regresión "clienta pegada en Atendiendo ahora" ──────────────────
    // Al COMPLETAR un servicio, cerrar también cualquier línea DUPLICADA activa
    // (mismo código + mismo servicio) que haya quedado colgada — típico de una
    // línea huérfana/duplicada. Si no, esa copia queda en 'en_servicio' y
    // getAtenciones sigue mostrando a la clienta aunque el servicio ya terminó.
    if (nuevoEstado === 'completado') {
      // Al terminar, la staff cierra TODO lo que tiene de esta clienta: sus otras
      // lineas (mismo staff = su servicio base + el extra), las del mismo ticket
      // (los extras heredan el promo_ref), y los duplicados del mismo servicio.
      // NO toca lineas de OTRA staff ni de OTRO ticket → los combos multi-staff
      // quedan intactos (cada staff cierra lo suyo).
      var _codRef = String(d[fila][LX.codigo]   || '');
      var _srvRef = String(d[fila][LX.servicio] || '');
      var _prRef  = String(d[fila][LX.promoRef] || '').trim();
      var _stRef  = String(d[fila][LX.staff]    || '').trim().toLowerCase();
      for (var j = 1; j < d.length; j++) {
        if (j === fila) continue;
        if (!_esHoy(d[j][LX.fecha])) continue;
        var _estJ = String(d[j][LX.estado]);
        if (_estJ !== 'en_servicio' && _estJ !== 'esperando') continue;
        if (String(d[j][LX.codigo]) !== _codRef) continue;
        var _prJ = String(d[j][LX.promoRef] || '').trim();
        var _stJ = String(d[j][LX.staff]    || '').trim().toLowerCase();
        var _sameStaff  = _stRef && _stJ === _stRef;                      // otra linea de la misma staff (el extra)
        var _sameTicket = _prJ && _prRef && _prJ === _prRef;             // misma referencia de ticket
        var _sameServ   = String(d[j][LX.servicio]) === _srvRef && (!_prJ || _prJ === _prRef); // duplicado exacto
        if (!_sameStaff && !_sameTicket && !_sameServ) continue;
        ws.getRange(j + 1, LX.estado + 1).setValue('completado');
        if (!String(d[j][LX.horaDevuelta] || '').trim()) ws.getRange(j + 1, LX.horaDevuelta + 1).setValue(stamp);
        ws.getRange(j + 1, LX.obs + 1).setValue(String(d[j][LX.obs] || '') + ' · [cerrado al completar]');
        ws.getRange(j + 1, LX.actualizada + 1).setValue(stamp);
      }
    }

    return { ok: true, id: d[fila][LX.id], estado: nuevoEstado };
  } catch (e) {
    return { ok: false, motivo: String(e) };
  }
}

// Tomar: la chica toma el servicio → la línea pasa a 'en_servicio' (y fija staff).
function marcarLineaEnServicioPorCodigo(codigo, ticketId, area, servicio, staff) {
  return _marcarLineaEstadoPorCodigo(codigo, ticketId, area, servicio, 'en_servicio', { staff: staff || '' });
}

// Finalizar: la chica termina el servicio → la línea pasa a 'completado' (= por cobrar).
function marcarLineaCompletadaPorCodigo(codigo, ticketId, area, servicio, staff) {
  return _marcarLineaEstadoPorCodigo(codigo, ticketId, area, servicio, 'completado', staff ? { staff: staff } : {});
}

// Marca COMPLETADO todas las líneas ACTIVAS del área N de un TM, incluyendo los sub-slots
// :N.k (servicio cambiado a promo + extras). Sin esto, al finalizar un área cuyo servicio
// se cambió, el slot base :N (anulado) se marcaba pero los :N.k quedaban 'en_servicio' → el
// área nunca se completaba y el ticket de Mikaela no se actualizaba (caso C-SYNA-TEST facial).
function marcarAreaTMCompletada(codigo, idTM, N, staff) {
  try {
    var ws = _hojaLineas(); var d = ws.getDataRange().getValues();
    var pref = String(idTM) + ':' + N;
    var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');
    var cod = String(codigo || '').trim();
    var n = 0;
    for (var i = 1; i < d.length; i++) {
      if (!_esHoy(d[i][LX.fecha])) continue;
      if (cod && String(d[i][LX.codigo] || '').trim() !== cod) continue;
      var ref = String(d[i][LX.promoRef] || '');
      if (ref !== pref && ref.indexOf(pref + '.') !== 0) continue;   // :N exacto o :N.k
      var est = String(d[i][LX.estado]);
      if (est !== 'en_servicio' && est !== 'esperando') continue;    // no tocar anulado/cobrado/completado
      ws.getRange(i + 1, LX.estado + 1).setValue('completado');
      if (staff && !String(d[i][LX.staff] || '').trim()) ws.getRange(i + 1, LX.staff + 1).setValue(staff);
      ws.getRange(i + 1, LX.actualizada + 1).setValue(stamp);
      n++;
    }
    return n;
  } catch (e) { Logger.log('[marcarAreaTMCompletada] ' + e); return 0; }
}

// ── MODELO "Espera por staff": la staff toma + confirma → inicia el servicio ──
// Pasa a 'en_servicio' TODAS las líneas de HOY de esta clienta asignadas a esta
// staff que estén en 'esperando' (= "Espera por staff"). Un solo toque inicia
// todos los servicios que la staff tiene con esa clienta (ej. las 2 áreas de un
// combo). Idempotente: si ya están en servicio, no hace nada.
function iniciarServicioStaff(codigo, staff) {
  try {
    codigo = String(codigo || '').trim();
    staff  = String(staff  || '').trim();
    if (!codigo || !staff) return { ok: false, motivo: 'faltan codigo/staff' };
    var ws = _hojaLineas();
    var d  = ws.getDataRange().getValues();
    var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');
    var iniciadas = 0, yaEstaban = 0, detalle = [];
    for (var i = 1; i < d.length; i++) {
      if (!_esHoy(d[i][LX.fecha])) continue;
      if (String(d[i][LX.codigo] || '').trim() !== codigo) continue;
      if (String(d[i][LX.staff]  || '').trim().toLowerCase() !== staff.toLowerCase()) continue;
      var est = String(d[i][LX.estado]);
      if (est === 'en_servicio') { yaEstaban++; continue; }
      if (est !== 'esperando') continue;   // no tocar completado/cobrado/anulado
      ws.getRange(i + 1, LX.estado + 1).setValue('en_servicio');
      if (!String(d[i][LX.horaToma] || '').trim()) ws.getRange(i + 1, LX.horaToma + 1).setValue(stamp);
      ws.getRange(i + 1, LX.actualizada + 1).setValue(stamp);
      iniciadas++;
      detalle.push({ id: String(d[i][LX.id]), servicio: String(d[i][LX.servicio]), ref: String(d[i][LX.promoRef] || d[i][LX.ticketRef] || '') });
    }
    Logger.log('[iniciarServicioStaff] ' + codigo + ' · ' + staff + ' → iniciadas=' + iniciadas + ' yaEstaban=' + yaEstaban);
    if (iniciadas + yaEstaban === 0) return { ok: false, motivo: 'sin_lineas_para_iniciar', codigo: codigo, staff: staff };
    return { ok: true, iniciadas: iniciadas, yaEstaban: yaEstaban, detalle: detalle };
  } catch (e) {
    Logger.log('[iniciarServicioStaff] ⛔ ' + e);
    return { ok: false, motivo: String(e) };
  }
}

// ── BLOQUE 2N — toma nativa por ticket_ref (no por código+staff) ───────────
// A diferencia de iniciarServicioStaff(codigo, staff) — que inicia TODAS las
// líneas de HOY de ese código+staff, sin distinguir a qué ticket pertenecen,
// y por lo tanto SÍ puede arrastrar líneas de otro ticket activo de la misma
// clienta — esta función solo toca las líneas de UN ticket_ref puntual.
// Match exacto: (ticket_ref === ref O promo_ref === ref) Y estado==='esperando'
// Y staff===staff. Sin fallback, sin cascada a "cola sin asignar".
function iniciarTicketNativoPorRef_(ticketRef, staff) {
  try {
    var ref   = String(ticketRef || '').trim();
    var staffN = String(staff || '').trim();
    if (!ref)    return { success: false, message: 'ticket_ref requerido', error: 'TICKET_REF_VACIO' };
    if (!staffN) return { success: false, message: 'staff requerido', error: 'STAFF_VACIO' };

    // Re-verificación defensiva: esta función puede llamarse directamente
    // (no solo desde el router de tomarClienta), así que no confía en que el
    // caller ya haya validado la fuente.
    var fuenteInfo = fuenteDelTicket(ref);
    if (!fuenteInfo || fuenteInfo.ok !== true) {
      return { success: false, message: 'No se pudo resolver la fuente del ticket',
               error: (fuenteInfo && fuenteInfo.error) || 'TICKET_SOURCE_NOT_FOUND', ticket_ref: ref };
    }
    if (fuenteInfo.fuente !== 'LINEAS') {
      return { success: false, message: 'Ticket no es nativo LINEAS (fuente=' + fuenteInfo.fuente + ')',
               error: 'TICKET_SOURCE_MISMATCH', ticket_ref: ref };
    }

    var ws = _hojaLineas();
    var d  = ws.getDataRange().getValues();
    var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');

    var filasAIniciar = [], filasYaEnServicio = [];
    for (var i = 1; i < d.length; i++) {
      var trFila = String(d[i][LX.ticketRef] || '').trim();
      var prFila = String(d[i][LX.promoRef]  || '').trim();
      if (trFila !== ref && prFila !== ref) continue;              // no es este ticket
      var staffFila = String(d[i][LX.staff] || '').trim();
      if (staffFila.toLowerCase() !== staffN.toLowerCase()) continue; // no es esta staff
      var estadoFila = String(d[i][LX.estado] || '');
      if (estadoFila === 'esperando') filasAIniciar.push(i);
      else if (estadoFila === 'en_servicio') filasYaEnServicio.push(i);
      // completado/por_verificar/cobrado/anulado: no se tocan, no cuentan.
    }

    if (!filasAIniciar.length) {
      if (filasYaEnServicio.length) {
        // Idempotencia (Prueba E): segunda llamada no duplica ni vuelve a
        // escribir líneas ya iniciadas — respuesta explícita, no error.
        return {
          success: true, ya_iniciado: true, ticket_ref: ref, fuente: 'LINEAS',
          message: 'Ya estaba iniciado para ' + staffN,
          lineas: filasYaEnServicio.map(function (f) { return String(d[f][LX.id]); })
        };
      }
      return {
        success: false, ticket_ref: ref,
        message: 'No hay líneas en espera de "' + staffN + '" para este ticket',
        error: 'SIN_LINEAS_ESPERANDO_PARA_STAFF'
      };
    }

    // Ambas (o más) líneas de la misma promo y misma staff inician JUNTAS,
    // en el mismo request — nunca una sí y otra en una llamada posterior.
    var idsIniciados = [];
    filasAIniciar.forEach(function (fila) {
      ws.getRange(fila + 1, LX.estado + 1).setValue('en_servicio');
      ws.getRange(fila + 1, LX.horaToma + 1).setValue(stamp);
      ws.getRange(fila + 1, LX.actualizada + 1).setValue(stamp);
      idsIniciados.push(String(d[fila][LX.id]));
    });

    Logger.log('[iniciarTicketNativoPorRef_] ' + ref + ' · ' + staffN + ' → iniciadas=' + idsIniciados.length);
    return { success: true, ticket_ref: ref, fuente: 'LINEAS', lineas: idsIniciados };
  } catch (e) {
    Logger.log('[iniciarTicketNativoPorRef_] ⛔ ' + e);
    return { success: false, message: String(e), error: 'EXCEPTION' };
  }
}

// ── BLOQUE 2N-2B Parte B — selección independiente de componentes al iniciar ──
// Generaliza iniciarTicketNativoPorRef_: si el caller entrega
// componentesSeleccionados (array de {id} o de ids), SOLO esas líneas pasan
// de esperando→en_servicio — el resto del ticket (misma staff u otra) queda
// intacto. iniciarTicketNativoPorRef_ NO se borra ni se modifica — sigue
// existiendo tal cual para quien la use directamente.
//
// MIGRACIÓN "Tomar clienta" (autorizada) — contrato de componentesSeleccionados:
//   AUSENTE (undefined/null, el caller no mandó la clave)
//     → autoseleccionar TODAS las candidatas elegibles del motor (esperando,
//       de esta staff, de este ticket) — 1, 2 o N, sin exigir selección.
//       Antes: 1 elegible autoseleccionaba, 2+ rechazaba con
//       COMPONENT_SELECTION_REQUIRED. Ahora el rechazo desaparece: el motor
//       ya calculaba ese conjunto de elegibles para decidir si rechazar —
//       el cambio es usarlo como resultado en vez de bloquear.
//   ARRAY EXPLÍCITO, length===0 ([])
//     → error SELECCION_VACIA. Un array vacío NUNCA se interpreta como
//       "tomar todo" — la única forma de autoseleccionar todo es omitir la
//       clave por completo. Esto preserva a los callers que sí requieren
//       selección explícita (ej. selector histórico de depilación corporal):
//       si mandan [] a propósito (nada tildado), deben ver un error, no un
//       "tomar todo" silencioso.
//   ARRAY EXPLÍCITO con elementos
//     → selección respetada tal cual, sin ampliar a otras candidatas
//       (comportamiento sin cambios).
function iniciarComponentesTicketNativoPorRef_(ticketRef, staff, componentesSeleccionados, opts) {
  opts = opts || {};   // BLOQUE B — 4º parámetro OPCIONAL, retrocompatible (los 2
                       // callers existentes pasan 3 args). Solo transporta los hooks
                       // de modoTest hacia _lnActualizarEstadoTicketNativoInterno_,
                       // que además exige ticketRef con prefijo T-TEST- para
                       // activarlos. Nunca altera el comportamiento productivo.
  try {
    var ref    = String(ticketRef || '').trim();
    var staffN = String(staff || '').trim();
    if (!ref)    return { success: false, message: 'ticket_ref requerido', error: 'TICKET_REF_VACIO' };
    if (!staffN) return { success: false, message: 'staff requerido', error: 'STAFF_VACIO' };

    var fuenteInfo = fuenteDelTicket(ref);
    if (!fuenteInfo || fuenteInfo.ok !== true) {
      return { success: false, message: 'No se pudo resolver la fuente del ticket',
               error: (fuenteInfo && fuenteInfo.error) || 'TICKET_SOURCE_NOT_FOUND', ticket_ref: ref };
    }
    if (fuenteInfo.fuente !== 'LINEAS') {
      return { success: false, message: 'Ticket no es nativo LINEAS (fuente=' + fuenteInfo.fuente + ')',
               error: 'TICKET_SOURCE_MISMATCH', ticket_ref: ref };
    }

    // Distinción obligatoria: ausente (autoselecciona) vs [] explícito
    // (SELECCION_VACIA) — nunca colapsar ambos casos al mismo camino.
    var _componentesAusente = (typeof componentesSeleccionados === 'undefined' || componentesSeleccionados === null);
    var idsSeleccionados = null; // null = autoseleccionar TODAS las elegibles (solo si ausente)
    if (!_componentesAusente) {
      if (!Array.isArray(componentesSeleccionados)) {
        return {
          success: false, ticket_ref: ref, error: 'COMPONENTES_FORMATO_INVALIDO',
          message: 'componentesSeleccionados debe ser un array.'
        };
      }
      if (componentesSeleccionados.length === 0) {
        Logger.log('[iniciarComponentesTicketNativoPorRef_] ⛔ SELECCION_VACIA · ' + ref + ' · ' + staffN
          + ' · componentesSeleccionados=[] explícito');
        return {
          success: false, ticket_ref: ref, error: 'SELECCION_VACIA',
          message: 'La selección de servicios está vacía.'
        };
      }
      idsSeleccionados = {};
      componentesSeleccionados.forEach(function (c) {
        var idc = typeof c === 'string' ? c : (c && c.id);
        if (idc) idsSeleccionados[String(idc).trim()] = true;
      });
      if (!Object.keys(idsSeleccionados).length) {
        Logger.log('[iniciarComponentesTicketNativoPorRef_] ⛔ SELECCION_VACIA · ' + ref + ' · ' + staffN
          + ' · componentesSeleccionados sin ningún id válido');
        return {
          success: false, ticket_ref: ref, error: 'SELECCION_VACIA',
          message: 'La selección de servicios no tiene identidad válida.'
        };
      }
    }

    var ws = _hojaLineas();
    var d  = ws.getDataRange().getValues();
    var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');

    var filasCandidatas = []; // esperando, de esta staff, de este ticket
    var filasYaEnServicio = [];
    // ── PLAN A · A7 — quién puede tomar qué ──────────────────────────────────
    // CASO A: la línea YA está asignada a esta staff (es su ejecutora).
    // CASO B: la línea NO tiene staff y el ticket está OFRECIDO a esta staff
    //         vía TicketsFuente.destinataria.
    // NUNCA por familia/área: una línea sin staff no es de dominio público.
    // Sin esta separación, cualquier staff compatible podría apropiarse de un
    // componente que Central reservó para otra.
    var _destinatariaTF = _tfDestinatariaDe_(ref);
    var _reclamables = Object.create(null);   // índice de fila → entró por Caso B
    var _excluidasPorOferta = 0;              // líneas sin staff ofrecidas a OTRA
    for (var i = 1; i < d.length; i++) {
      var trFila = String(d[i][LX.ticketRef] || '').trim();
      var prFila = String(d[i][LX.promoRef]  || '').trim();
      var esDeEsteTicket = (trFila === ref) || (prFila === ref) || (prFila.indexOf(ref + ':') === 0);
      if (!esDeEsteTicket) continue;
      var staffFila = String(d[i][LX.staff] || '').trim();
      var _casoA = !!staffFila && staffFila.toLowerCase() === staffN.toLowerCase();
      var _casoB = !staffFila && !!_destinatariaTF
                   && _destinatariaTF.toLowerCase() === staffN.toLowerCase();
      if (!_casoA && !_casoB) {
        if (!staffFila) _excluidasPorOferta++;
        continue;                                   // no es de esta staff
      }
      if (_casoB) _reclamables[i] = true;
      var estadoFila = String(d[i][LX.estado] || '');
      if (estadoFila === 'esperando') filasCandidatas.push(i);
      else if (estadoFila === 'en_servicio') filasYaEnServicio.push(i);
      // completado/por_verificar/cobrado/anulado: fuera de alcance de "iniciar".
    }

    // Protección operativa: una staff que NO es la destinataria no puede
    // reclamar líneas sin staff, aunque su familia coincida con el área.
    // Fail-closed ANTES de cualquier escritura.
    if (!filasCandidatas.length && !filasYaEnServicio.length && _excluidasPorOferta > 0) {
      return { success: false, ticket_ref: ref, staff: staffN,
               error: 'COMPONENTE_NO_OFRECIDO_A_STAFF',
               componentes_no_ofrecidos: _excluidasPorOferta,
               message: 'Estos servicios no están ofrecidos a ' + staffN + '.' };
    }

    // ── MIGRACIÓN "Tomar clienta" (autorizada) ───────────────────────────────
    // Antes: 2+ candidatas elegibles sin selección explícita → rechazo
    // COMPONENT_SELECTION_REQUIRED. Ahora: sin selección explícita
    // (idsSeleccionados === null), se autoseleccionan TODAS las candidatas
    // elegibles — el filtro de abajo (if (idsSeleccionados) {...}) no se
    // aplica cuando es null, así que filasAIniciar queda naturalmente como
    // filasCandidatas completo. 1 elegible → inicia 1. N elegibles → inicia
    // N. 0 elegibles → cae en el bloque de "sin líneas" más abajo, sin
    // escritura. La definición de "elegible" (esperando + esta staff + este
    // ticket) no cambió — sigue siendo exactamente el cálculo de arriba.

    // Filtrar por selección explícita, si vino.
    var filasAIniciar = filasCandidatas;
    var idsEncontradosSeleccion = {};
    if (idsSeleccionados) {
      filasAIniciar = filasCandidatas.filter(function (fila) {
        var idFila = String(d[fila][LX.id]);
        var match = !!idsSeleccionados[idFila];
        if (match) idsEncontradosSeleccion[idFila] = true;
        return match;
      });
    }

    // no_encontradas: ids pedidos que no aparecieron entre las candidatas
    // esperando de esta staff/ticket (pueden pertenecer a otra staff, no
    // existir, o ya estar en otro estado — se reportan, nunca se inventan).
    var noEncontradas = [];
    if (idsSeleccionados) {
      Object.keys(idsSeleccionados).forEach(function (idPedido) {
        if (!idsEncontradosSeleccion[idPedido]) noEncontradas.push(idPedido);
      });
    }

    if (!filasAIniciar.length) {
      // Idempotencia: si lo pedido (o, sin selección, todo el ticket) ya
      // estaba en_servicio para esta staff, no es un error.
      var yaTodosLosSeleccionados = idsSeleccionados
        ? Object.keys(idsSeleccionados).every(function (idPedido) {
            return filasYaEnServicio.some(function (f) { return String(d[f][LX.id]) === idPedido; });
          })
        : filasYaEnServicio.length > 0;
      if (yaTodosLosSeleccionados) {
        // BLOQUE B — sincronización TF también en el camino idempotente. Si una
        // ejecución previa inició las líneas pero su transición de TF falló, esta
        // relectura converge el ticket en vez de dejarlo colgado en 'abierto'
        // para siempre. _lnActualizarEstadoTicketNativoInterno_ es idempotente:
        // si TF ya está en 'en_atencion', no reescribe.
        var rTFIdemB = _lnActualizarEstadoTicketNativoInterno_(_tfHoja(), ref, 'en_atencion', opts);
        if (!rTFIdemB.ok) {
          return {
            success: false, ticket_ref: ref, error: 'TF_ACTUALIZACION_FALLIDA',
            error_tf: rTFIdemB.error, detalle_tf: rTFIdemB,
            lineas_ya_en_servicio: filasYaEnServicio.map(function (f) { return String(d[f][LX.id]); })
          };
        }
        return {
          success: true, ticket_ref: ref, staff: staffN,
          iniciadas: [], ya_en_servicio: filasYaEnServicio.map(function (f) { return String(d[f][LX.id]); }),
          no_encontradas: noEncontradas, componentes_procesados: filasYaEnServicio.length,
          tf_estado: rTFIdemB.estado_nuevo, tf_escritura: rTFIdemB.escritura
        };
      }
      if (!idsSeleccionados) {
        // B5: 0 candidatas elegibles, sin selección (nunca "sin coincidencias
        // con la selección" — no hubo selección). Cero escrituras.
        return {
          success: false, ticket_ref: ref,
          message: 'No hay líneas en espera de "' + staffN + '" para este ticket',
          error: 'SIN_LINEAS_ESPERANDO_PARA_STAFF'
        };
      }
      return {
        success: false, ticket_ref: ref,
        message: 'No hay líneas esperando de "' + staffN + '" que coincidan con la selección',
        error: 'SIN_LINEAS_ESPERANDO_PARA_SELECCION', no_encontradas: noEncontradas
      };
    }

    // ── INC-PUESTO-TRABAJO-INICIO-COMPONENTES (ALT-1) ─────────────────────
    // ANTES DEL FIX: esta vía escribía 3 celdas sueltas (estado/horaToma/
    // actualizada) SIN pasar por la autoridad de puestos, dejando líneas
    // en_servicio con puesto_trabajo VACÍO — luego imposibles de finalizar
    // (PUESTO_TRABAJO_VACIO_AL_FINALIZAR).
    //
    // POR QUÉ NO SE LLAMA A _iniciarLineaNativaInterno_ DESDE AQUÍ:
    // esa primitiva sincroniza TicketsFuente internamente y, si TF falla,
    // COMPENSA la línea. Usarla por componente hacía que un fallo TF ocurriera
    // dentro del loop y revirtiera las líneas — destruyendo el contrato
    // histórico de ESTA función (demostrado por el test B4): ante fallo TF las
    // líneas deben PERMANECER en_servicio y reportarse en
    // `lineas_iniciadas_sin_tf`, sin compensación. La sincronización TF vive
    // exclusivamente en el punto histórico, UNA sola vez, después del loop.
    //
    // Se replica el patrón transaccional ya certificado de
    // _asignarYIniciarLineaNativaInterno_ (que tampoco toca TF), reutilizando
    // los MISMOS helpers canónicos: _lnResolverCapacidadStaffInterno_ para la
    // capacidad (siempre vía Comisiones, nunca inferida del área del servicio)
    // y _lnAsignarPuestoTrabajoInterno_ para decidir el puesto. No se inventa
    // un número, no se usa valor fijo, no viene del frontend, y no se duplica
    // la lógica de puestos: solo se repite el patrón de commit por línea.
    //
    // ATOMICIDAD (A) — fase LINEAS: si el commit de una de N falla, se
    // compensan los commits previos de ESTE intento con
    // _lnCompensarInicioAgrupadoInterno_ (mismo compensador que usa
    // _iniciarLineasNativasAgrupadasInterno_). Esto es DISTINTO de (B), la
    // política de la rama TF de más abajo, que deliberadamente NO compensa.
    var comisionesDataIC = opts.comisionesData;
    if (!Array.isArray(comisionesDataIC)) {
      try { comisionesDataIC = getSheet('Comisiones').getDataRange().getValues(); }
      catch (eComIC) {
        return { success: false, ticket_ref: ref, staff: staffN,
                 error: 'NO_SE_PUDO_LEER_COMISIONES', message: String(eComIC) };
      }
    }

    var resCapIC = _lnResolverCapacidadStaffInterno_(comisionesDataIC, staffN);
    if (!resCapIC.ok) {
      // Fail closed ANTES de escribir una sola celda.
      return { success: false, ticket_ref: ref, staff: staffN,
               error: resCapIC.error, detalle: resCapIC.detalle,
               fase: 'resolver_capacidad_staff' };
    }

    var idsIniciados  = [];
    var commitsIC     = [];   // commits de ESTE intento, para compensar
    var tfPorTicketIC = Object.create(null);   // sin entradas: TF no se toca en el loop

    for (var iIC = 0; iIC < filasAIniciar.length; iIC++) {
      var filaIC         = filasAIniciar[iIC];
      var rowNumberIC    = filaIC + 1;
      var lineaIdIC      = String(d[filaIC][LX.id]);
      var filaOriginalIC = d[filaIC].slice(0, 32);

      function _fallaIC_(errorIC, extraIC) {
        var compIC = _lnCompensarInicioAgrupadoInterno_(ws, _tfHoja(), commitsIC, tfPorTicketIC, opts);
        Logger.log('[iniciarComponentesTicketNativoPorRef_] ⛔ ' + errorIC + ' en ' + lineaIdIC +
                   ' · commits compensados=' + commitsIC.length);
        var outIC = {
          success: false, ticket_ref: ref, staff: staffN,
          error: compIC.ok ? errorIC : 'COMPENSACION_INCOMPLETA',
          error_original: errorIC, linea_id: lineaIdIC,
          compensacion: compIC,
          iniciadas: compIC.ok ? [] : idsIniciados.slice(),
          ya_en_servicio: filasYaEnServicio.map(function (f) { return String(d[f][LX.id]); }),
          no_encontradas: noEncontradas
        };
        for (var kX in (extraIC || {})) outIC[kX] = extraIC[kX];
        return outIC;
      }

      // Snapshot fresco: refleja los puestos ya ocupados por los commits
      // anteriores de este mismo intento, para que la autoridad canónica
      // decida correctamente (herencia por ticketRef+staff incluida).
      var lineasSnapshotIC = ws.getDataRange().getValues();
      var asigIC = _lnAsignarPuestoTrabajoInterno_(
        lineasSnapshotIC, ref, lineaIdIC, staffN, resCapIC.capacidad, undefined);
      if (!asigIC.ok) {
        // INV-C: fail closed por capacidad/puesto ANTES de la fase TF.
        return _fallaIC_(asigIC.error, { detalle: asigIC.detalle, fase: 'asignacion_puesto' });
      }

      var _tIC      = _ahora();
      var filaNuevaIC = filaOriginalIC.slice(0, 32);
      filaNuevaIC[LX.estado]        = 'en_servicio';
      filaNuevaIC[LX.puestoTrabajo] = asigIC.puesto;
      // PLAN A · A7 — CASO B: la línea se RECLAMA aquí, en la MISMA escritura
      // atómica que la pone en servicio. Nunca en dos pasos: no puede existir un
      // instante con staff escrita y estado sin cambiar, ni al revés. La
      // verificación por relectura y la compensación de abajo cubren ambas.
      if (_reclamables[rowNumberIC - 1]) filaNuevaIC[LX.staff] = staffN;
      if (!String(filaOriginalIC[LX.horaToma] || '').trim())
        filaNuevaIC[LX.horaToma] = _tIC.stamp;
      filaNuevaIC[LX.actualizada] = _tIC.stamp;
      // No se toca: servicio, monto, montoRegular, origen, promoRef,
      // ticketRef, esPromo, slot, grupoPromoId, lineaPadre.
      // staff: SOLO en Caso B (línea reclamada). En Caso A ya era de esta staff.

      var fallosMkIC = _lnVerificarMarcadoresFilaInterno_(String(filaNuevaIC[LX.obs] || ''));
      if (fallosMkIC.length > 0) {
        return _fallaIC_('LINE_NATIVE_MARKERS_INVALID',
                         { fase: 'pre-escritura', fallos_marcadores: fallosMkIC });
      }

      // Escritura ÚNICA A–AF (nunca celdas sueltas).
      try {
        ws.getRange(rowNumberIC, 1, 1, 32).setValues([filaNuevaIC]);
      } catch (eWIC) {
        var restWIC = _lnRestaurarFilaLineaInterno_(ws, rowNumberIC, filaOriginalIC, {});
        if (!restWIC.ok) {
          return _fallaIC_('LINE_WRITE_EXCEPTION',
                           { excepcion: String(eWIC), compensacion_linea_ok: false,
                             detalle_compensacion: restWIC });
        }
        return _fallaIC_('LINE_WRITE_EXCEPTION', { excepcion: String(eWIC) });
      }

      // Verificación física por relectura.
      var postIC;
      try { postIC = ws.getRange(rowNumberIC, 1, 1, 32).getValues()[0]; }
      catch (eRIC) {
        _lnRestaurarFilaLineaInterno_(ws, rowNumberIC, filaOriginalIC, {});
        return _fallaIC_('EXCEPCION_VERIFICACION_LINEA', { excepcion: String(eRIC) });
      }
      var difsIC = _lnDiferenciasFila_(filaNuevaIC, postIC, 32);
      if (difsIC.length > 0) {
        _lnRestaurarFilaLineaInterno_(ws, rowNumberIC, filaOriginalIC, {});
        return _fallaIC_('LINE_WRITE_NOT_VERIFIED', { diferencias: difsIC });
      }

      idsIniciados.push(lineaIdIC);
      commitsIC.push({ rowNumber: rowNumberIC, ticketRef: ref, lineaId: lineaIdIC,
                       filaOriginalLinea: filaOriginalIC });
    }

    Logger.log('[iniciarComponentesTicketNativoPorRef_] ' + ref + ' · ' + staffN
      + ' → iniciadas=' + idsIniciados.length
      + (idsSeleccionados ? ' (selección explícita)' : ' (todas, sin selección)'));

    // ── BLOQUE B — sincronizar TicketsFuente → 'en_atencion' ────────────────
    // Las N líneas ya quedaron verificadas en_servicio arriba. Ésta es la MISMA
    // transición canónica que usa _iniciarLineaNativaInterno_ (variante _Interno_,
    // sin lock propio: doPost ya sostiene el ScriptLock exterior). Nunca se
    // escribe el estado de TF a mano.
    //
    // Se llama UNA sola vez por invocación, no una por línea: para un SP
    // multi-componente como el de Carolina (2 líneas iniciadas juntas) TF
    // transiciona 'abierto' → 'en_atencion' exactamente una vez.
    //
    // No hay chequeo redundante de fuente===LINEAS a propósito: esta función es
    // contractualmente exclusiva de LINEAS, y si el ticket no existe en
    // TicketsFuente la propia transición devuelve TICKET_SOURCE_NOT_FOUND y esta
    // rama corta con éxito=false. Un chequeo previo sería código muerto.
    //
    // LIMITACIÓN CONOCIDA (no hay compensación autorizada en este bloque): si TF
    // falla, las líneas YA quedaron en_servicio y NO se revierten — a diferencia
    // de _iniciarLineaNativaInterno_, que sí compensa. Lo que este bloque
    // garantiza es que NO se declara éxito silencioso: se devuelve success:false
    // con el detalle y la lista explícita de las líneas que sí se iniciaron, para
    // que el estado parcial sea visible en vez de quedar oculto tras un ok.
    var rTFB = _lnActualizarEstadoTicketNativoInterno_(_tfHoja(), ref, 'en_atencion', opts);
    if (!rTFB.ok) {
      Logger.log('[iniciarComponentesTicketNativoPorRef_] ⚠ TF no sincronizado: ' + rTFB.error
        + ' · líneas ya iniciadas: ' + idsIniciados.join(','));
      return {
        success: false, ticket_ref: ref, staff: staffN,
        error: 'TF_ACTUALIZACION_FALLIDA', error_tf: rTFB.error, detalle_tf: rTFB,
        lineas_iniciadas_sin_tf: idsIniciados
      };
    }

    // ── PLAN A · A8 (v2) — la oferta NO se cierra al confirmar ───────────────
    // Antes se limpiaba destinataria aquí (_tfSetDestinatariaInterno_(ref, '')).
    // El contrato vigente establece que la staff conserva el CONTROL OPERATIVO
    // del ticket mientras ejecuta su parte: tras confirmar K/N, la destinataria
    // sigue siendo ella. Eso es lo que habilita "Yo sigo: <siguiente>" sin
    // fabricar una oferta nueva, y mantiene vivo el guard
    // COMPONENTE_NO_OFRECIDO_A_STAFF sobre los N-K que ella no seleccionó.
    // La cesión de control ocurre en los botones post-parte, NO aquí:
    //   · Yo sigo            -> conserva destinataria
    //   · Pasar a otra staff -> cederPendientesACentralNativo_ la limpia
    //   · Terminé todo       -> terminarYCancelarPendientesNativo_ la limpia
    //   · Devolver a central -> la limpia

    return {
      success: true, ticket_ref: ref, staff: staffN,
      iniciadas: idsIniciados,
      ya_en_servicio: filasYaEnServicio.map(function (f) { return String(d[f][LX.id]); }),
      no_encontradas: noEncontradas,
      componentes_procesados: idsIniciados.length + filasYaEnServicio.length,
      tf_estado: rTFB.estado_nuevo, tf_escritura: rTFB.escritura
    };
  } catch (e) {
    Logger.log('[iniciarComponentesTicketNativoPorRef_] ⛔ ' + e);
    return { success: false, message: String(e), error: 'EXCEPTION' };
  }
}

// ════════════════════════════════════════════════════════════════════════════
// BLOQUE A+B — TESTS: auth_estado en creación nativa + sincronización TF
// ════════════════════════════════════════════════════════════════════════════
// Origen: 09/08/2026 · incidente Carolina Baque C-0874 / SP-0296.
//   BLOQUE A — las 4 rutas de alta ordinaria creaban líneas con auth_estado=''
//     → el motor nativo de finalización (LN3_AUTH_OPERATIVOS) las rechazaba con
//     LINE_AUTH_NOT_OPERATIVE. Corregido pasando authEstado:'no_requiere'.
//   BLOQUE B — iniciarComponentesTicketNativoPorRef_ ponía líneas en_servicio
//     sin sincronizar TicketsFuente → TF quedaba 'abierto' con líneas activas.
//     Corregido con la transición canónica _lnActualizarEstadoTicketNativoInterno_.
function _test_bloque_ab_auth_y_tf() {
  var lock = LockService.getScriptLock();
  try { lock.waitLock(20000); }
  catch (eLock) { return { ok:false, errores:['LOCK_TIMEOUT: ' + eLock] }; }
  try { return _tfTestBloqueABInterno_(); }
  finally { lock.releaseLock(); }
}

function _tfTestBloqueABInterno_() {
  var wsLineas = _hojaLineas(), wsTF = _tfHoja();
  var fallos = 0;
  var refsCreadas = [];
  var idsSueltos  = [];

  function _chk(n, c, d) {
    if (c) { Logger.log('  ✅ ' + n); } else { fallos++; Logger.log('  ❌ ' + n + (d ? ' — ' + d : '')); }
  }
  function _authDe(id) { var h = getLineaPorId(id); return h ? String(h.linea.authEstado || '') : '(no existe)'; }
  function _estadoDe(id) { var h = getLineaPorId(id); return h ? String(h.linea.estado || '') : '(no existe)'; }
  function _estadoTF(ref) {
    // Índice CONTRACTUAL TFX.estadoTicket — nunca un número hardcodeado. La
    // versión anterior de este helper leía data[i][3], que es estadoRegistro
    // ('activo'), no estadoTicket ('abierto'/'en_atencion'): por eso los asserts
    // B1/B2/B4 daban 'activo' y parecían fallos de producto cuando el log real
    // ya mostraba la transición correcta.
    var data = wsTF.getDataRange().getValues();
    for (var i = 1; i < data.length; i++) {
      if (String(data[i][TFX.ticketRef] || '').trim() === ref) return String(data[i][TFX.estadoTicket] || '');
    }
    return '(sin fila TF)';
  }

  Logger.log('════════════════════════════════════════════════');
  Logger.log('  TEST BLOQUE A+B — auth_estado en alta + sincronización TicketsFuente');
  Logger.log('════════════════════════════════════════════════');

  try {
    // ══════════ BLOQUE A ══════════
    Logger.log('-- BLOQUE A: las 4 rutas de alta ordinaria --');

    // A1 — promo nativa (crearTicketPromoNativo_ → indirecto vía crearLinea con
    // los MISMOS argumentos que usa esa ruta; no se invoca la ruta completa para
    // no depender del catálogo Paquetes real ni de _nuevoTicketRefSPNativo_).
    var refA1 = 'T-TEST-AB-PROMO-' + Date.now();
    var rTkA1 = _crearTicketNativoInterno_({
      codigo:'C-TEST-AB', cliente:'Test AB promo', origen:'NEXSERV', requestId:'RQ-AB-1-' + refA1,
      primeraLinea:{ area:'cejas', servicio:'Base promo', monto:1, montoRegular:1 }
    }, wsLineas, wsTF, { modoTest:true, ticketRefPrueba:refA1 });
    _chk('A1 setup. ticket creado', rTkA1.ok === true, JSON.stringify(rTkA1));
    if (rTkA1.ok) refsCreadas.push(refA1);

    var rA1 = crearLinea({
      codigo:'C-TEST-AB', cliente:'Test AB promo', staff:'', area:'cejas',
      servicio:'Combo (componente)', esPromo:true, promoRef:refA1, ticketRef:refA1, slot:'',
      monto:27, montoRegular:30, estado:'esperando', origen:'NEXSERV', grupoPromoId:refA1,
      authEstado:'no_requiere', obs:'[test AB promo]'
    });
    _chk('A1. promo nativa → auth_estado="no_requiere"',
         !!rA1.id && _authDe(rA1.id) === 'no_requiere', 'auth=' + (rA1.id ? _authDe(rA1.id) : JSON.stringify(rA1)));

    // A2 — servicio normal nativo
    var rA2 = crearLinea({
      visita:refA1, codigo:'C-TEST-AB', cliente:'Test AB normal', staff:'', area:'cejas',
      servicio:'Servicio normal test', esPromo:false, promoRef:refA1, ticketRef:refA1, slot:'',
      monto:15, montoRegular:15, estado:'esperando', origen:'NEXSERV',
      authEstado:'no_requiere', obs:'[test AB normal]'
    });
    _chk('A2. normal nativo → auth_estado="no_requiere"',
         !!rA2.id && _authDe(rA2.id) === 'no_requiere', 'auth=' + (rA2.id ? _authDe(rA2.id) : JSON.stringify(rA2)));

    // A3 — lineaDesdeListaEspera (ruta real, con su firma real: lee data.total,
    // NO data.precio — verificado en la definición de la función).
    var rA3 = lineaDesdeListaEspera({
      codigo:'C-TEST-AB', nombre:'Test AB LE', asignadaA:'', area:'cejas',
      servicio:'Servicio LE test ' + Date.now(), total:12, observaciones:'[test AB LE]'
    }, 'LE');
    var idA3 = rA3 && rA3.id;
    if (idA3) idsSueltos.push(idA3);
    _chk('A3. lineaDesdeListaEspera → auth_estado="no_requiere"',
         !!idA3 && _authDe(idA3) === 'no_requiere', JSON.stringify(rA3));

    // A4 — lineaDesdeAsignacion (rowValues A..R de ListaEspera)
    var filaLE = [];
    for (var z = 0; z < 18; z++) filaLE.push('');
    filaLE[0] = 'LE-TEST-AB-' + Date.now();
    filaLE[3] = 'C-TEST-AB'; filaLE[4] = 'Test AB ASIG';
    filaLE[5] = 'Servicio ASIG test ' + Date.now(); filaLE[6] = 'cejas';
    filaLE[9] = ''; filaLE[12] = 20;
    var rA4 = lineaDesdeAsignacion(filaLE, 'ASIG');
    var idA4 = rA4 && (rA4.id || rA4.actualizada);
    if (rA4 && rA4.id) idsSueltos.push(rA4.id);
    _chk('A4. lineaDesdeAsignacion → auth_estado="no_requiere"',
         !!idA4 && _authDe(idA4) === 'no_requiere', JSON.stringify(rA4));

    // A5 — contrato propuesta+pendiente INTACTO (no se rompió con el cambio)
    var rA5ok = crearLinea({
      visita:refA1, codigo:'C-TEST-AB', cliente:'Test AB propuesta', staff:'', area:'cejas',
      servicio:'Propuesta test', esPromo:false, ticketRef:refA1, monto:9, montoRegular:9,
      estado:'propuesta', origen:'NEXSERV', authEstado:'pendiente', obs:'[test AB propuesta]'
    });
    if (rA5ok && rA5ok.id) idsSueltos.push(rA5ok.id);
    _chk('A5a. propuesta + authEstado="pendiente" SIGUE siendo válida',
         !!rA5ok.id && _authDe(rA5ok.id) === 'pendiente' && _estadoDe(rA5ok.id) === 'propuesta',
         JSON.stringify(rA5ok));

    var rA5bad = crearLinea({
      visita:refA1, codigo:'C-TEST-AB', cliente:'Test AB propuesta mala', staff:'', area:'cejas',
      servicio:'Propuesta invalida', esPromo:false, ticketRef:refA1, monto:9, montoRegular:9,
      estado:'propuesta', origen:'NEXSERV', authEstado:'no_requiere', obs:'[test AB propuesta mala]'
    });
    _chk('A5b. propuesta con authEstado≠"pendiente" SIGUE rechazándose',
         rA5bad.success === false && rA5bad.error === 'PROPUESTA_AUTH_ESTADO_INCORRECTO',
         JSON.stringify(rA5bad));

    // ══════════ BLOQUE B ══════════
    Logger.log('-- BLOQUE B: sincronización TicketsFuente --');

    // B1 — SP multi-componente como Carolina: 2 líneas, ambas de la misma staff,
    // ticket en 'abierto'. Iniciar AMBAS en una sola llamada.
    var refB1 = 'T-TEST-AB-SP-' + Date.now();
    var staffB1 = _lnStaffAisladaTest_(refB1, 'Cejas');
    var rTkB1 = _crearTicketNativoInterno_({
      codigo:'C-TEST-AB', cliente:'Test AB Carolina-like', origen:'NEXSERV', requestId:'RQ-AB-B1-' + refB1,
      primeraLinea:{ area:'cejas', servicio:'Combo (comp 1)', monto:27, montoRegular:30, staff:staffB1 }
    }, wsLineas, wsTF, { modoTest:true, ticketRefPrueba:refB1 });
    _chk('B1 setup. ticket SP-like creado', rTkB1.ok === true, JSON.stringify(rTkB1));
    if (!rTkB1.ok) throw new Error('setup B1: ' + rTkB1.error);
    refsCreadas.push(refB1);

    // La línea 1 nace 'esperando' con staff asignada; crear la línea 2 igual.
    var rB1L2 = crearLinea({
      visita:refB1, codigo:'C-TEST-AB', cliente:'Test AB Carolina-like', staff:staffB1,
      area:'cejas', servicio:'Combo (comp 2)', esPromo:true, promoRef:refB1, ticketRef:refB1,
      monto:2, montoRegular:2, estado:'esperando', origen:'NEXSERV', grupoPromoId:refB1,
      authEstado:'no_requiere', obs:'[test AB comp2]'
    });
    _chk('B1 setup. segunda línea creada', !!rB1L2.id, JSON.stringify(rB1L2));
    _chk('B1. TF arranca en "abierto"', _estadoTF(refB1) === 'abierto', 'TF=' + _estadoTF(refB1));

    var rB1 = iniciarComponentesTicketNativoPorRef_(refB1, staffB1, null);
    _chk('B1. iniciar 2 componentes → success', rB1.success === true, JSON.stringify(rB1));
    _chk('B1. AMBAS líneas quedan en_servicio',
         rB1.iniciadas && rB1.iniciadas.length === 2
         && _estadoDe(rTkB1.linea_id) === 'en_servicio' && _estadoDe(rB1L2.id) === 'en_servicio',
         'iniciadas=' + JSON.stringify(rB1.iniciadas));
    _chk('B1. TicketsFuente pasó "abierto" → "en_atencion"', _estadoTF(refB1) === 'en_atencion', 'TF=' + _estadoTF(refB1));
    _chk('B1. transición ejecutada UNA sola vez para las 2 líneas (una escritura de TF)',
         rB1.tf_estado === 'en_atencion' && rB1.tf_escritura === true, JSON.stringify(rB1));

    // B2 — idempotencia: repetir la toma no rompe nada
    var rB2 = iniciarComponentesTicketNativoPorRef_(refB1, staffB1, null);
    _chk('B2. reintento → success (camino idempotente)', rB2.success === true, JSON.stringify(rB2));
    _chk('B2. no duplica inicios (iniciadas vacío, ya_en_servicio=2)',
         (rB2.iniciadas || []).length === 0 && (rB2.ya_en_servicio || []).length === 2, JSON.stringify(rB2));
    _chk('B2. líneas intactas en_servicio',
         _estadoDe(rTkB1.linea_id) === 'en_servicio' && _estadoDe(rB1L2.id) === 'en_servicio', '');
    _chk('B2. TF permanece "en_atencion" y NO se reescribe',
         _estadoTF(refB1) === 'en_atencion' && rB2.tf_escritura === false,
         'TF=' + _estadoTF(refB1) + ' escritura=' + rB2.tf_escritura);

    // B3 — ticket SIN fila en TicketsFuente. La función corre fuenteDelTicket(ref)
    // en su PREVALIDACIÓN, antes de tocar LINEAS: el comportamiento correcto es
    // fail-fast con TICKET_SOURCE_NOT_FOUND y CERO escrituras — no un fallo de
    // sincronización posterior. (La expectativa anterior de este assert
    // —TF_ACTUALIZACION_FALLIDA con estado parcial— era imposible: describía el
    // caso B4, que sí supera la prevalidación.)
    // Sigue demostrando lo mismo que se quería demostrar: un chequeo previo
    // fuente===LINEAS dentro de la función sería código muerto, porque la
    // prevalidación existente ya corta este caso.
    var refB3 = 'T-TEST-AB-NOTF-' + Date.now();
    var staffB3 = _lnStaffAisladaTest_(refB3, 'Cejas');
    var rB3L = crearLinea({
      visita:refB3, codigo:'C-TEST-AB', cliente:'Test AB sin TF', staff:staffB3, area:'cejas',
      servicio:'Linea sin ticket TF', esPromo:false, promoRef:refB3, ticketRef:refB3,
      monto:5, montoRegular:5, estado:'esperando', origen:'NEXSERV',
      authEstado:'no_requiere', obs:'[test AB sin TF]'
    });
    if (rB3L && rB3L.id) idsSueltos.push(rB3L.id);
    _chk('B3 setup. línea creada sin fila en TicketsFuente', !!rB3L.id, JSON.stringify(rB3L));
    _chk('B3 setup. efectivamente no hay fila TF', _estadoTF(refB3) === '(sin fila TF)', _estadoTF(refB3));

    var rB3 = iniciarComponentesTicketNativoPorRef_(refB3, staffB3, null);
    _chk('B3. fail-fast en prevalidación → success:false con TICKET_SOURCE_NOT_FOUND',
         rB3.success === false && rB3.error === 'TICKET_SOURCE_NOT_FOUND', JSON.stringify(rB3));
    _chk('B3. CERO escrituras de inicio: la línea permanece "esperando"',
         _estadoDe(rB3L.id) === 'esperando', 'estado=' + _estadoDe(rB3L.id));
    _chk('B3. no existe estado parcial (ninguna línea reportada como iniciada)',
         !rB3.lineas_iniciadas_sin_tf && !(rB3.iniciadas && rB3.iniciadas.length),
         JSON.stringify(rB3));

    // B4 — fallo de TF DESPUÉS de superar la prevalidación (ticket TF válido) e
    // iniciar las líneas: éste sí es el caso de "estado parcial visible", que B3
    // no puede ejercitar porque nunca llega a escribir.
    var refB4 = 'T-TEST-AB-HOOK-' + Date.now();
    var staffB4 = _lnStaffAisladaTest_(refB4, 'Cejas');
    var rTkB4 = _crearTicketNativoInterno_({
      codigo:'C-TEST-AB', cliente:'Test AB hook', origen:'NEXSERV', requestId:'RQ-AB-B4-' + refB4,
      primeraLinea:{ area:'cejas', servicio:'Linea hook', monto:5, montoRegular:5, staff:staffB4 }
    }, wsLineas, wsTF, { modoTest:true, ticketRefPrueba:refB4 });
    if (rTkB4.ok) refsCreadas.push(refB4);
    _chk('B4 setup. ticket creado', rTkB4.ok === true, JSON.stringify(rTkB4));

    var rB4 = iniciarComponentesTicketNativoPorRef_(refB4, staffB4, null,
      { modoTest:true, hookFallarActualizacionTF:true });
    _chk('B4. fallo inyectado de TF → success:false, sin éxito silencioso',
         rB4.success === false && rB4.error === 'TF_ACTUALIZACION_FALLIDA', JSON.stringify(rB4));
    _chk('B4. reporta explícitamente las líneas que SÍ se iniciaron (estado parcial visible)',
         Array.isArray(rB4.lineas_iniciadas_sin_tf) && rB4.lineas_iniciadas_sin_tf.length === 1,
         JSON.stringify(rB4.lineas_iniciadas_sin_tf));
    _chk('B4. la línea quedó efectivamente en_servicio (el fallo es posterior al inicio)',
         _estadoDe(rTkB4.linea_id) === 'en_servicio', 'estado=' + _estadoDe(rTkB4.linea_id));
    _chk('B4. TF permanece "abierto" (no se escribió)', _estadoTF(refB4) === 'abierto', 'TF=' + _estadoTF(refB4));

  } catch (eFatal) {
    fallos++;
    Logger.log('  ❌ EXCEPCIÓN NO CONTROLADA: ' + eFatal);
  } finally {
    // Limpieza: anular (no borrar — evita reciclado de IDs) todo lo creado.
    idsSueltos.forEach(function (id) {
      try { actualizarLinea(id, { estado:'anulado', motivoAnulacion:'limpieza test bloque A+B' }); }
      catch (e) { Logger.log('[cleanup AB] ' + id + ' → ' + e); }
    });
    refsCreadas.forEach(function (ref) {
      try { anularTicketNativoPorRef_(ref, 'limpieza test bloque A+B', 'test'); }
      catch (e) { Logger.log('[cleanup AB] ' + ref + ' → ' + e); }
    });
    Logger.log('Limpieza: ' + idsSueltos.length + ' línea(s) suelta(s) + ' + refsCreadas.length + ' ticket(s) anulados');
  }

  Logger.log(fallos === 0
    ? '✅ RESULTADO FINAL: bloque A+B OK (0 fallos)'
    : '❌ RESULTADO FINAL: ' + fallos + ' fallo(s)');
  return { ok: fallos === 0, fallos: fallos };
}

// ── D7.1 P6-B FASE 1 — capacidad staff↔servicio (fuente propia) ────────────// NO reutiliza _famAreaLineas_ (arriba, informativo/no autoritativo),
// esMismaAreaM3 (nexserv-main-2.js, family 'retiro_lifting' separada) ni
// _famAreaTM (NexServ_AppsScript.js, misma limitación que _famAreaLineas_).
// Las tres agrupan retiro/lifting como familia propia y NINGUNA implementa
// la regla real y asimétrica del salón: cejas SÍ hace lifting/retiro de
// pestañas; pestañas NO hace depilación/cejas. Esa regla real solo existe
// hoy como AREA_CAPS, inline dentro de updateFinishButtons() en
// nexserv-main-1.js — client-side, no autoritativo. Esta tabla es la
// implementación propia de backend del MISMO contrato operativo (no una
// copia literal del objeto JS del frontend — su propio bloque, sus propios
// tests, ver _test_bloque_p6b_capacidad). NO usa puesto_trabajo (Bloque
// 2N-3B no está aprobado como autoridad de área para P6 — instrucción
// explícita D7.1).
var LN_CAPACIDAD_STAFF = {
  cejas:    ['cejas', 'depilacion', 'depilación', 'bigote', 'ceja', 'pigment', 'brow', 'lifting', 'retiro'],
  pestanas: ['pestanas', 'pestañas', 'pestaña', 'lifting', 'retiro', 'volumen', 'pelo a pelo',
             'efecto aura', 'efecto muñeca', 'clasicas', 'clásicas', 'natural', 'extension', 'extensión'],
  facial:   ['facial', 'hidra', 'limpieza']
};

// Normaliza minúsculas + sin tildes + sin símbolos/emojis (mismo criterio
// que el frontend usa para 'division.area' en el check puedeTodo de
// updateFinishButtons: '👁 Pestañas' → 'pestanas' limpio, no 'pestañas' con
// basura de emoji pegada).
function _lnNormTextoCap_(s) {
  s = String(s || '').toLowerCase();
  try { s = s.normalize('NFD').replace(/[\u0300-\u036f]/g, ''); } catch (e) {}
  s = s.replace(/[^\w\s]/gi, ' ');
  return s;
}

// Área base de una staff — Comisiones col A(0)=nombre, col B(1)=área. Mismo
// contrato que _areaStaffTM_ (NexServ_AppsScript.js:10309), implementado acá
// mismo (no se llama a ese archivo) para que este módulo y sus tests no
// dependan de que ese otro archivo esté presente/desplegado. Recibe
// comisionesData ya cargado por el caller — mismo patrón que
// finalizarComponentesTicketNativoPorRef_ (evita releer la hoja por llamada).
function _lnAreaBaseStaffInterno_(staff, comisionesData) {
  var staffN = String(staff || '').trim().toLowerCase();
  if (!staffN || !Array.isArray(comisionesData)) return '';
  for (var i = 0; i < comisionesData.length; i++) {
    var fila = comisionesData[i];
    if (String(fila[0] || '').trim().toLowerCase() === staffN) {
      return String(fila[1] || '').trim();
    }
  }
  return '';
}

/**
 * _lnStaffPuedeTomarLineaInterno_(staff, linea, comisionesData)
 *   linea: { area, servicio } — texto crudo de la fila LINEAS (LX.area/LX.servicio).
 * Devuelve:
 *   { ok:true,  puede:boolean, staffArea, familia }
 *   { ok:false, error:'STAFF_AREA_NO_RESUELTA'|'STAFF_FAMILIA_NO_RECONOCIDA', puede:false }
 * FAIL CLOSED: si no se puede determinar el área/familia de la staff,
 * ok:false y puede:false — nunca se asume capacidad por defecto.
 */
function _lnStaffPuedeTomarLineaInterno_(staff, linea, comisionesData) {
  var staffArea = _lnAreaBaseStaffInterno_(staff, comisionesData);
  if (!staffArea) return { ok: false, error: 'STAFF_AREA_NO_RESUELTA', puede: false };

  var staffAreaNorm = _lnNormTextoCap_(staffArea);
  var familia = null;
  for (var fam in LN_CAPACIDAD_STAFF) {
    if (staffAreaNorm.indexOf(fam) >= 0) { familia = fam; break; }
  }
  if (!familia) return { ok: false, error: 'STAFF_FAMILIA_NO_RECONOCIDA', puede: false, staffArea: staffArea };

  var tokens = LN_CAPACIDAD_STAFF[familia];
  var textoLinea = _lnNormTextoCap_((linea && linea.area) || '') + ' ' + _lnNormTextoCap_((linea && linea.servicio) || '');
  var puede = tokens.some(function (tok) { return textoLinea.indexOf(_lnNormTextoCap_(tok)) >= 0; });
  return { ok: true, puede: puede, staffArea: staffArea, familia: familia };
}

// ── D7.1 P6-B FASE 1 — primitivo nuevo: reclamar una línea huérfana ────────
// Único caso de uso: una línea 'esperando' SIN staff asignada (staff === '')
// dentro de un ticket LINEAS operativo. Transición ÚNICA:
//   esperando(staff='') → en_servicio(staff=staffN)
// Deliberadamente NO modifica iniciarComponentesTicketNativoPorRef_ (arriba)
// — ese contrato sigue intacto para su caso de uso real (líneas YA
// pre-asignadas a la staff que las llama). Si la línea ya tiene staff
// (asignada a ella o a otra), este primitivo se niega — ver
// LINE_ALREADY_ASSIGNED_USE_INICIAR / LINE_STAFF_CONFLICT abajo.
//
// Variante SIN lock (para el router, que ya sostiene ScriptLock exterior
// vía doPost — _esEscritura_('asignarYIniciarLineaNativa') es true al no
// empezar con 'get'). El wrapper público asignarYIniciarLineaNativa(data)
// SÍ toma su propio lock, para llamadas directas/tests.
function _asignarYIniciarLineaNativaInterno_(ticketRef, lineaId, staff, opts) {
  opts = opts || {};
  var ref    = String(ticketRef || '').trim();
  var lid    = String(lineaId   || '').trim();
  var staffN = String(staff     || '').trim();
  if (!ref)    return { success: false, error: 'TICKET_REF_REQUERIDO' };
  if (!lid)    return { success: false, error: 'LINEA_ID_REQUERIDO', ticket_ref: ref };
  if (!staffN) return { success: false, error: 'STAFF_REQUERIDO', ticket_ref: ref, linea_id: lid };

  var fuenteInfo = fuenteDelTicket(ref);
  if (!fuenteInfo || fuenteInfo.ok !== true) {
    return { success: false, error: (fuenteInfo && fuenteInfo.error) || 'TICKET_SOURCE_NOT_FOUND', ticket_ref: ref, linea_id: lid };
  }
  if (fuenteInfo.fuente !== 'LINEAS') {
    return { success: false, error: 'TICKET_SOURCE_MISMATCH', ticket_ref: ref, linea_id: lid };
  }

  var wsTF = _tfHoja();
  var valTk = _lnValidarTicketOperativoInterno_(wsTF, ref);
  if (!valTk.ok) return { success: false, error: valTk.error, ticket_ref: ref, linea_id: lid, detalle: valTk };

  var wsLineas = _hojaLineas();
  var busq = _lnBuscarLineaExactaInterno_(wsLineas, ref, lid);
  if (!busq.ok) return { success: false, error: busq.error, ticket_ref: ref, linea_id: lid, detalle: busq };

  var fila       = busq.fila;
  var staffFila  = String(fila[LX.staff]  || '').trim();
  var estadoFila = String(fila[LX.estado] || '').trim();

  // comisionesData se resuelve ACÁ (antes se leía más abajo): la verificación
  // de idempotencia ahora necesita la capacidad real para poder validar el
  // puesto_trabajo ya escrito. opts.comisionesData permite inyección para
  // tests (mismo patrón que _iniciarLineaNativaInterno_/_lnOptsPuestosTest_);
  // en producción el caller nunca la manda y se lee la hoja real.
  var comisionesData = opts.comisionesData;
  if (!Array.isArray(comisionesData)) {
    try { comisionesData = getSheet('Comisiones').getDataRange().getValues(); }
    catch (eCom) { return { success: false, error: 'NO_SE_PUDO_LEER_COMISIONES', ticket_ref: ref, linea_id: lid, message: String(eCom) }; }
  }

  // C7 — idempotencia: mismo staff, ya en_servicio por este mismo primitivo.
  // INC-PUESTO-TRABAJO-INICIO-LINEA — la idempotencia ahora es ESTRICTA: solo
  // se declara éxito si la línea ya cumple el contrato operativo COMPLETO,
  // incluido un puesto_trabajo VÁLIDO. Antes bastaba con estado+staff, así que
  // un estado parcial histórico (en_servicio + AF vacío, producido por la
  // versión anterior de este mismo primitivo) se reportaba como éxito y
  // quedaba atascado: _finalizarLineaNativaInterno_ lo rechaza después con
  // PUESTO_TRABAJO_VACIO_AL_FINALIZAR. Ese estado parcial NO se reconcilia en
  // silencio acá (no existe patrón certificado para hacerlo) — se bloquea con
  // error explícito para que se resuelva por la vía administrativa que
  // corresponda.
  if (estadoFila === 'en_servicio' && staffFila && staffFila.toLowerCase() === staffN.toLowerCase()) {
    var resCapIdem = _lnResolverCapacidadStaffInterno_(comisionesData, staffFila);
    if (!resCapIdem.ok) {
      return { success: false, error: resCapIdem.error, detalle: resCapIdem.detalle,
               ticket_ref: ref, linea_id: lid, fase: 'resolver_capacidad_staff_idempotencia' };
    }
    var normAFIdem = _lnNormalizarPuestoTrabajoInterno_(fila[LX.puestoTrabajo], resCapIdem.capacidad);
    if (normAFIdem.tipo !== 'valido') {
      return { success: false, error: 'LINE_STATE_INCONSISTENTE',
               motivo: normAFIdem.tipo === 'vacio'
                 ? 'linea en_servicio sin puesto_trabajo asignado'
                 : 'linea en_servicio con puesto_trabajo invalido',
               puesto_trabajo: fila[LX.puestoTrabajo],
               detalle: normAFIdem, ticket_ref: ref, linea_id: lid };
    }
    // Contrato completo ya cumplido → idempotente real, sin reescribir ni
    // consumir capacidad adicional (conserva EXACTAMENTE el mismo puesto).
    return { success: true, ticket_ref: ref, linea_id: lid, staff: staffN,
             ya_en_servicio: true, idempotente: true, puesto_trabajo: normAFIdem.puesto };
  }

  // C4/C8 — no está en 'esperando'. Si hay una staff distinta identificable
  // en la fila, LINE_STAFF_CONFLICT es más informativo que "estado
  // inválido" (permite al caller mostrar "ya la tiene Keyla"). Sin staff
  // identificable (dato/estado anómalo), LINE_STATE_NOT_ALLOWED genérico.
  if (estadoFila !== 'esperando') {
    if (staffFila && staffFila.toLowerCase() !== staffN.toLowerCase()) {
      return { success: false, error: 'LINE_STAFF_CONFLICT', staff_actual: staffFila,
               estado_actual: estadoFila, ticket_ref: ref, linea_id: lid };
    }
    return { success: false, error: 'LINE_STATE_NOT_ALLOWED', estado_actual: estadoFila, ticket_ref: ref, linea_id: lid };
  }

  // estado === 'esperando' desde acá.
  // C3 — ya tiene dueña (pre-asignada, esperando a que ELLA la tome —
  // contrato de iniciarComponentesTicketNativoPorRef_, no de este primitivo).
  if (staffFila) {
    if (staffFila.toLowerCase() !== staffN.toLowerCase()) {
      return { success: false, error: 'LINE_STAFF_CONFLICT', staff_actual: staffFila, ticket_ref: ref, linea_id: lid };
    }
    return { success: false, error: 'LINE_ALREADY_ASSIGNED_USE_INICIAR', ticket_ref: ref, linea_id: lid };
  }

  // ── único caso operable: staff === '' && estado === 'esperando' ────────
  // Capacidad de ÁREA — OBLIGATORIA en backend, fail-closed. No confiar en
  // que el frontend ocultó el botón (instrucción explícita D7.1). Esta es la
  // capacidad "¿esta staff sabe hacer este servicio?", distinta de la
  // capacidad de PUESTOS ("¿cuántas atenciones simultáneas admite?"), que se
  // resuelve más abajo vía _lnResolverCapacidadStaffInterno_.
  var cap = _lnStaffPuedeTomarLineaInterno_(staffN, { area: fila[LX.area], servicio: fila[LX.servicio] }, comisionesData);
  if (!cap.ok) {
    return { success: false, error: cap.error, ticket_ref: ref, linea_id: lid };
  }
  if (!cap.puede) {
    return { success: false, error: 'STAFF_SIN_CAPACIDAD', ticket_ref: ref, linea_id: lid,
             staff_area: cap.staffArea, linea_area: String(fila[LX.area] || ''), linea_servicio: String(fila[LX.servicio] || '') };
  }

  // ── auth_estado — mismo gate que _iniciarLineaNativaInterno_ (sección 5).
  // Sin esto, una línea con autorización pendiente/denegada podía iniciarse
  // por esta vía y quedar en_servicio con auth no operativa.
  var authFila = String(fila[LX.authEstado] || '').trim();
  if (LN3_AUTH_OPERATIVOS.indexOf(authFila) < 0) {
    return { success: false, error: 'LINE_AUTH_NOT_OPERATIVE',
             auth_estado: authFila, ticket_ref: ref, linea_id: lid };
  }

  // ── PUESTO DE TRABAJO (INC-PUESTO-TRABAJO-INICIO-LINEA) ─────────────────
  // Contrato replicado de _iniciarLineaNativaInterno_ sección 5b: la
  // capacidad de puestos SIEMPRE se resuelve vía Comisiones
  // (_lnResolverCapacidadStaffInterno_) — nunca se infiere del área del
  // servicio — y el puesto lo decide la autoridad canónica
  // _lnAsignarPuestoTrabajoInterno_ (NexServ_PuestosTrabajo.gs). No se
  // inventa un número, no se usa un valor fijo, no viene del frontend.
  // TODO se decide ANTES de tocar una sola celda.
  var lineasSnapshot = wsLineas.getDataRange().getValues();

  var resCapPuesto = _lnResolverCapacidadStaffInterno_(comisionesData, staffN);
  if (!resCapPuesto.ok) {
    return { success: false, error: resCapPuesto.error, detalle: resCapPuesto.detalle,
             ticket_ref: ref, linea_id: lid, fase: 'resolver_capacidad_staff' };
  }
  var asigPuesto = _lnAsignarPuestoTrabajoInterno_(
    lineasSnapshot, ref, lid, staffN, resCapPuesto.capacidad, undefined);
  if (!asigPuesto.ok) {
    // Sin puesto disponible / corrupción → FAIL CLOSED. La línea permanece
    // EXACTAMENTE como estaba: hasta aquí no se escribió ninguna celda.
    return { success: false, error: asigPuesto.error, detalle: asigPuesto.detalle,
             ticket_ref: ref, linea_id: lid, fase: 'asignacion_puesto' };
  }

  // ── Construir la fila nueva (A–AF completa) ─────────────────────────────
  var filaOriginal = fila.slice(0, 32);
  var _tIni = _ahora();
  var filaNueva = filaOriginal.slice(0, 32);
  filaNueva[LX.staff]         = staffN;
  filaNueva[LX.estado]        = 'en_servicio';
  filaNueva[LX.puestoTrabajo] = asigPuesto.puesto;
  if (!String(filaOriginal[LX.horaToma] || '').trim())
    filaNueva[LX.horaToma] = _tIni.stamp;
  filaNueva[LX.actualizada] = _tIni.stamp;
  // No se toca: servicio, monto, montoRegular, origen, promoRef, ticketRef,
  // esPromo, slot, grupoPromoId, lineaPadre.

  var fallosMk = _lnVerificarMarcadoresFilaInterno_(String(filaNueva[LX.obs] || ''));
  if (fallosMk.length > 0) {
    return { success: false, error: 'LINE_NATIVE_MARKERS_INVALID', fase: 'pre-escritura',
             ticket_ref: ref, linea_id: lid, fallos_marcadores: fallosMk };
  }

  // ── Escritura ÚNICA A–AF (antes: 4 setValue sueltos, que podían dejar
  // escritura parcial ante excepción a mitad de camino). ──────────────────
  try {
    wsLineas.getRange(busq.rowIndex, 1, 1, 32).setValues([filaNueva]);
  } catch (eW) {
    var restW = _lnRestaurarFilaLineaInterno_(wsLineas, busq.rowIndex, filaOriginal, {});
    return { success: false,
             error: restW.ok ? 'LINE_WRITE_EXCEPTION' : 'COMPENSACION_INCOMPLETA',
             error_original: 'LINE_WRITE_EXCEPTION', excepcion: String(eW),
             compensacion_linea_ok: restW.ok, detalle_compensacion: restW,
             ticket_ref: ref, linea_id: lid };
  }

  // ── Verificación física por relectura (antes inexistente en este
  // primitivo). Si no coincide → restaurar la fila completa. ─────────────
  var postIni;
  try { postIni = wsLineas.getRange(busq.rowIndex, 1, 1, 32).getValues()[0]; }
  catch (eR) {
    var restR = _lnRestaurarFilaLineaInterno_(wsLineas, busq.rowIndex, filaOriginal, {});
    return { success: false,
             error: restR.ok ? 'EXCEPCION_VERIFICACION_LINEA' : 'COMPENSACION_INCOMPLETA',
             error_original: 'EXCEPCION_VERIFICACION_LINEA', excepcion: String(eR),
             compensacion_linea_ok: restR.ok, detalle_compensacion: restR,
             ticket_ref: ref, linea_id: lid };
  }
  var difsIni = _lnDiferenciasFila_(filaNueva, postIni, 32);
  if (difsIni.length > 0) {
    var restV = _lnRestaurarFilaLineaInterno_(wsLineas, busq.rowIndex, filaOriginal, {});
    return { success: false,
             error: restV.ok ? 'LINE_WRITE_NOT_VERIFIED' : 'COMPENSACION_INCOMPLETA',
             error_original: 'LINE_WRITE_NOT_VERIFIED', diferencias: difsIni,
             compensacion_linea_ok: restV.ok, detalle_compensacion: restV,
             ticket_ref: ref, linea_id: lid };
  }

  Logger.log('[asignarYIniciarLineaNativa_] ' + ref + ' · ' + lid + ' → ' + staffN +
             ' · puesto=' + asigPuesto.puesto);
  return { success: true, ticket_ref: ref, linea_id: lid, staff: staffN,
           puesto_trabajo: asigPuesto.puesto, puesto_heredado: !!asigPuesto.heredado };
}

// Wrapper público — SOLO para llamadas directas/tests (toma su propio
// lock). El router de doPost llama SIEMPRE a _asignarYIniciarLineaNativaInterno_
// directamente (doPost ya sostiene ScriptLock exterior para esta acción —
// _esEscritura_ es true al no empezar con 'get' — llamar a este wrapper
// desde el router produciría LOCK_TIMEOUT garantizado, ScriptLock no es
// reentrant; mismo criterio ya documentado para
// sustituirServicioPorPromoStaffNativa).
function asignarYIniciarLineaNativa(data) {
  var lock = LockService.getScriptLock();
  try { lock.waitLock(20000); }
  catch (eLock) { return { success: false, error: 'LOCK_TIMEOUT', message: String(eLock) }; }
  try {
    data = data || {};
    return _asignarYIniciarLineaNativaInterno_(data.ticketRef, data.lineaId, data.staff, data._opts);
  } finally { lock.releaseLock(); }
}

// ════════════════════════════════════════════════════════════════════════════
// D7.1 P6-B FASE 1 — TESTS: capacidad (puro) + primitivo asignarYIniciarLinea (C1-C9)
// ════════════════════════════════════════════════════════════════════════════
//
// NOTA DE EJECUCIÓN: estos arneses están escritos para correr DENTRO del editor
// de Apps Script (usan SpreadsheetApp/LockService/Utilities reales). No hay
// forma de ejecutarlos fuera de ese entorno para certificarlos en verde — la
// matriz de capacidad (_test_bloque_p6b_capacidad, sin I/O de hoja) SÍ se
// validó de forma aislada en Node antes de escribir este archivo (12/12
// casos, incluye los 2 casos borde con emoji que no estaban en la tabla
// original de D7.1). C1-C9 quedan listos para correr en DEV — no certificados
// todavía.

function _test_bloque_p6b_capacidad() {
  Logger.log('════════════════════════════════════════════════');
  Logger.log('  TEST P6-B — CAPACIDAD STAFF↔LINEA (puro, sin hoja)');
  Logger.log('════════════════════════════════════════════════');
  var fallos = 0;
  function _chk(nombre, cond, detalle) {
    if (cond) { Logger.log('  ✅ ' + nombre); }
    else { fallos++; Logger.log('  ❌ ' + nombre + (detalle ? ' — ' + detalle : '')); }
  }
  var com = _lnComisionesFixtureHistoricaTest_(); // María/Keyla/Lesly/Rosa=Cejas, Yadira/Diana=Pestañas, Laura=Facial

  var casos = [
    ['María',  { servicio: 'Depilación de cejas' },            true,  'Cejas + depilación'],
    ['María',  { servicio: 'Pigmentación', area: 'brow' },      true,  'Cejas + brow/pigmento'],
    ['María',  { servicio: 'Lifting de pestañas' },             true,  'Cejas + lifting'],
    ['María',  { servicio: 'Retiro de pestañas' },              true,  'Cejas + retiro pestañas'],
    ['María',  { servicio: 'Volumen ruso (extensión)' },        false, 'Cejas + volumen/extensión'],
    ['Yadira', { servicio: 'Volumen clásico' },                 true,  'Pestañas + volumen'],
    ['Yadira', { servicio: 'Lifting de pestañas' },             true,  'Pestañas + lifting'],
    ['Yadira', { servicio: 'Depilación de cejas' },             false, 'Pestañas + depilación'],
    ['Laura',  { servicio: 'Limpieza facial' },                 true,  'Facial + facial'],
    ['Laura',  { servicio: 'Pestañas clásicas' },                false, 'Facial + pestañas'],
    // Bordes agregados en la auditoría (área con emoji, como llega desde
    // promo.division en el frontend real — ver puedeTodo en updateFinishButtons).
    ['María',  { area: '👁 Pestañas', servicio: 'Volumen' },     false, 'Cejas + área con emoji, incompatible'],
    ['Yadira', { area: '✂️ Retiro', servicio: 'Lifting' },       true,  'Pestañas + área con emoji, compatible']
  ];
  casos.forEach(function (c) {
    var r = _lnStaffPuedeTomarLineaInterno_(c[0], c[1], com);
    _chk(c[3], r.ok === true && r.puede === c[2], JSON.stringify(r));
  });

  // Staff sin fila en Comisiones → fail closed, nunca asume capacidad.
  var rFantasma = _lnStaffPuedeTomarLineaInterno_('Staff-Que-No-Existe-XYZ', { servicio: 'Cejas' }, com);
  _chk('staff sin Comisiones → fail closed (ok:false, puede:false)',
       rFantasma.ok === false && rFantasma.puede === false && rFantasma.error === 'STAFF_AREA_NO_RESUELTA',
       JSON.stringify(rFantasma));

  Logger.log(fallos === 0 ? '✅ RESULTADO: capacidad OK (0 fallos)' : '❌ RESULTADO: ' + fallos + ' fallo(s)');
  return { ok: fallos === 0, fallos: fallos };
}

function _test_bloque_p6b_asignarYIniciarLinea() {
  Logger.log('════════════════════════════════════════════════');
  Logger.log('  TEST P6-B — asignarYIniciarLineaNativa (C1-C9)');
  Logger.log('════════════════════════════════════════════════');
  var lock = LockService.getScriptLock();
  try { lock.waitLock(20000); }
  catch (eLock) { return { ok: false, errores: ['LOCK_TIMEOUT: ' + eLock] }; }
  try { return _tfTestP6bAsignarInterno_(); }
  finally { lock.releaseLock(); }
}

function _tfTestP6bAsignarInterno_() {
  var wsLineas = _hojaLineas(), wsTF = _tfHoja();
  var fallos = 0;
  var refsCreadas = [];
  var comTest = _lnComisionesFixtureHistoricaTest_(); // se repuebla tras cada _lnStaffAisladaTest_

  function _chk(nombre, cond, detalle) {
    if (cond) { Logger.log('  ✅ ' + nombre); }
    else { fallos++; Logger.log('  ❌ ' + nombre + (detalle ? ' — ' + detalle : '')); }
  }
  function _filaLineaPorId(id) {
    var h = getLineaPorId(id);
    return h ? h.linea : null;
  }

  // Ticket base con UNA línea iniciada (requisito para que TicketsFuente
  // llegue a 'en_atencion' — mismo patrón certificado que
  // _setupTicketConLineaOrigen, Bloque 8C.3) + una línea EXTRA huérfana
  // (staff='', esperando) creada directo con crearLinea() — el objetivo real
  // bajo prueba.
  function _setup(sufijo, familiaStaffDueña, servicioHuerfana, areaHuerfana, staffHuerfanaInicial) {
    var ref = 'T-TEST-P6B-' + sufijo + '-' + Date.now() + '-' + Math.floor(Math.random() * 100000);
    var staffDueña = _lnStaffAisladaTest_(ref, familiaStaffDueña || 'Cejas');
    comTest = _lnComisionesFixtureHistoricaTest_(); // recoge la staff sintética recién registrada

    var rTk = _crearTicketNativoInterno_({
      codigo: 'C-TEST-P6B', cliente: 'Test P6B ' + sufijo, origen: 'NEXSERV', requestId: 'RQ-P6B-' + ref,
      primeraLinea: { area: familiaStaffDueña || 'cejas', servicio: 'Linea base ' + sufijo, monto: 1, montoRegular: 1 }
    }, wsLineas, wsTF, { modoTest: true, ticketRefPrueba: ref });
    if (!rTk.ok) return { ok: false, ref: ref, error: 'setup ticket: ' + rTk.error };
    refsCreadas.push(ref);

    var rIniBase = _iniciarLineaNativaInterno_({ ticketRef: ref, lineaId: rTk.linea_id, staff: staffDueña },
      wsLineas, wsTF, _lnOptsPuestosTest_());
    if (!rIniBase.ok) return { ok: false, ref: ref, error: 'setup iniciar base: ' + rIniBase.error };

    var rHuerfana = crearLinea({
      visita: ref, ticketRef: ref, codigo: 'C-TEST-P6B', cliente: 'Test P6B ' + sufijo,
      staff: staffHuerfanaInicial === undefined ? '' : staffHuerfanaInicial,
      area: areaHuerfana, servicio: servicioHuerfana, esPromo: true,
      monto: 5, montoRegular: 8, estado: 'esperando', authEstado: 'no_requiere', origen: 'NEXSERV',
      obs: '[NATIVE_LINE_REQUEST_ID:RQ-P6B-HUERF-' + ref + '] [NATIVE_LINE_REQUEST_FP:FP-P6B-HUERF-' + ref + ']'
    });
    if (!rHuerfana || !rHuerfana.id) return { ok: false, ref: ref, error: 'no se pudo crear línea huérfana' };

    return { ok: true, ref: ref, staffDueña: staffDueña, lineaHuerfanaId: rHuerfana.id, lineaBaseId: rTk.linea_id };
  }

  try {
    // ── C1 — esperando, staff='', compatible → asigna, en_servicio ────────
    var s1 = _setup('C1', 'Cejas', 'Depilación de cejas', 'cejas');
    _chk('C1 setup', s1.ok, s1.error);
    if (s1.ok) {
      var r1 = _asignarYIniciarLineaNativaInterno_(s1.ref, s1.lineaHuerfanaId, s1.staffDueña, { comisionesData: comTest });
      _chk('C1. success:true', r1.success === true, JSON.stringify(r1));
      var f1 = _filaLineaPorId(s1.lineaHuerfanaId);
      _chk('C1. línea queda en_servicio con la staff correcta',
           f1 && f1.estado === 'en_servicio' && String(f1.staff) === s1.staffDueña, JSON.stringify(f1));
      _chk('C1. hora_toma sellada', f1 && !!String(f1.horaToma || '').trim(), JSON.stringify(f1));

      // ── C7 — doble toque mismo request, misma staff → idempotente, sin reescribir ──
      var horaTomaTrasC1 = f1 && f1.horaToma;
      var r7 = _asignarYIniciarLineaNativaInterno_(s1.ref, s1.lineaHuerfanaId, s1.staffDueña, { comisionesData: comTest });
      var f7 = _filaLineaPorId(s1.lineaHuerfanaId);
      _chk('C7. segunda llamada misma staff → success idempotente',
           r7.success === true && r7.ya_en_servicio === true, JSON.stringify(r7));
      _chk('C7. no reescribe hora_toma', f7 && String(f7.horaToma) === String(horaTomaTrasC1),
           'antes=' + horaTomaTrasC1 + ' despues=' + (f7 && f7.horaToma));

      // ── C8 — otra staff intenta después → conflicto, cero escritura ───────
      var staffOtra8 = _lnStaffAisladaTest_(s1.ref + '-C8', 'Cejas'); comTest = _lnComisionesFixtureHistoricaTest_();
      var r8 = _asignarYIniciarLineaNativaInterno_(s1.ref, s1.lineaHuerfanaId, staffOtra8, { comisionesData: comTest });
      var f8 = _filaLineaPorId(s1.lineaHuerfanaId);
      _chk('C8. otra staff después → LINE_STAFF_CONFLICT',
           r8.success === false && r8.error === 'LINE_STAFF_CONFLICT' && r8.staff_actual === s1.staffDueña, JSON.stringify(r8));
      _chk('C8. línea sigue con la staff original, sin cambios', f8 && String(f8.staff) === s1.staffDueña, JSON.stringify(f8));
    }

    // ── C2 — esperando, staff='', servicio INcompatible → fail closed, cero escritura ──
    var s2 = _setup('C2', 'Facial', 'Volumen ruso extensión', 'pestanas');
    _chk('C2 setup', s2.ok, s2.error);
    if (s2.ok) {
      var r2 = _asignarYIniciarLineaNativaInterno_(s2.ref, s2.lineaHuerfanaId, s2.staffDueña, { comisionesData: comTest });
      _chk('C2. fail closed por capacidad', r2.success === false && r2.error === 'STAFF_SIN_CAPACIDAD', JSON.stringify(r2));
      var f2 = _filaLineaPorId(s2.lineaHuerfanaId);
      _chk('C2. línea sigue esperando/sin staff (cero escritura)',
           f2 && f2.estado === 'esperando' && String(f2.staff || '') === '', JSON.stringify(f2));
    }

    // ── C3 — esperando pero YA tiene otra staff asignada (pre-asignada, no huérfana) ──
    var s3 = _setup('C3', 'Cejas', 'Depilación de cejas', 'cejas');
    _chk('C3 setup', s3.ok, s3.error);
    if (s3.ok) {
      var staffKeylaC3 = _lnStaffAisladaTest_(s3.ref + '-keyla', 'Cejas'); comTest = _lnComisionesFixtureHistoricaTest_();
      // Reasignar manualmente la línea huérfana a "Keyla" ANTES de probar
      // (simula una línea pre-asignada que el motor de reasignación real
      // no cubre — la fuente de este estado no es objeto de este test).
      var filaIdx3 = getLineaPorId(s3.lineaHuerfanaId).fila;
      wsLineas.getRange(filaIdx3, LX.staff + 1).setValue(staffKeylaC3);

      var r3 = _asignarYIniciarLineaNativaInterno_(s3.ref, s3.lineaHuerfanaId, s3.staffDueña, { comisionesData: comTest });
      _chk('C3. María intenta línea de Keyla → LINE_STAFF_CONFLICT',
           r3.success === false && r3.error === 'LINE_STAFF_CONFLICT' && r3.staff_actual === staffKeylaC3, JSON.stringify(r3));
    }

    // ── C4 — línea ya en_servicio (no esperando) → estado inválido ────────
    var s4 = _setup('C4', 'Cejas', 'Depilación de cejas', 'cejas');
    _chk('C4 setup', s4.ok, s4.error);
    if (s4.ok) {
      // La propia staff dueña la inicia primero (vía el flujo ya certificado
      // iniciarComponentesTicketNativoPorRef_, que SÍ puede iniciar una línea
      // ya pre-asignada a ella y esperando).
      var filaIdx4 = getLineaPorId(s4.lineaHuerfanaId).fila;
      wsLineas.getRange(filaIdx4, LX.staff + 1).setValue(s4.staffDueña); // pre-asignar
      var rIni4 = iniciarComponentesTicketNativoPorRef_(s4.ref, s4.staffDueña, [s4.lineaHuerfanaId]);
      _chk('C4 setup. línea puesta en_servicio', rIni4.success === true, JSON.stringify(rIni4));

      var staffOtra4 = _lnStaffAisladaTest_(s4.ref + '-otra', 'Cejas'); comTest = _lnComisionesFixtureHistoricaTest_();
      // Forzamos un intento desde una staff SIN relación con la fila (para
      // aislar el caso de "estado ya no es esperando" del caso de conflicto
      // de propiedad ya cubierto en C8) escribiendo staff='' manualmente
      // encima de una línea en_servicio — dato anómalo deliberado, es
      // exactamente lo que LINE_STATE_NOT_ALLOWED debe capturar.
      wsLineas.getRange(filaIdx4, LX.staff + 1).setValue('');
      var r4 = _asignarYIniciarLineaNativaInterno_(s4.ref, s4.lineaHuerfanaId, staffOtra4, { comisionesData: comTest });
      _chk('C4. estado en_servicio sin dueña identificable → LINE_STATE_NOT_ALLOWED',
           r4.success === false && r4.error === 'LINE_STATE_NOT_ALLOWED', JSON.stringify(r4));
    }

    // ── C5 — lineaId real pero de OTRO ticket → LINE_NOT_IN_TICKET ────────
    var s5a = _setup('C5a', 'Cejas', 'Depilación de cejas', 'cejas');
    var s5b = _setup('C5b', 'Cejas', 'Depilación de cejas', 'cejas');
    _chk('C5 setup', s5a.ok && s5b.ok, (s5a.error || '') + ' ' + (s5b.error || ''));
    if (s5a.ok && s5b.ok) {
      var r5 = _asignarYIniciarLineaNativaInterno_(s5a.ref, s5b.lineaHuerfanaId, s5a.staffDueña, { comisionesData: comTest });
      _chk('C5. línea de otro ticket → LINE_NOT_IN_TICKET', r5.success === false && r5.error === 'LINE_NOT_IN_TICKET', JSON.stringify(r5));
    }

    // ── C6 — identidad: el core opera con CUALQUIER staff que reciba; la
    // protección real está en el router (exigirSesionFirmada_ inyecta,
    // nunca lee data.staff) — ver FASE 2. Esto prueba que el core, dado un
    // staff arbitrario coherente con Comisiones, no confía en nada más que
    // ese parámetro (no hay canal alterno de identidad dentro del primitivo).
    var s6 = _setup('C6', 'Pestañas', 'Volumen clásico', 'pestanas');
    _chk('C6 setup', s6.ok, s6.error);
    if (s6.ok) {
      var r6 = _asignarYIniciarLineaNativaInterno_(s6.ref, s6.lineaHuerfanaId, s6.staffDueña, { comisionesData: comTest });
      _chk('C6. opera exactamente con el staff recibido como parámetro (sin canal alterno)',
           r6.success === true && r6.staff === s6.staffDueña, JSON.stringify(r6));
    }

    // ── C9 — lock: la variante _Interno_ NO toma lock propio (verificable
    // por inspección: no hay LockService.getScriptLock() dentro de
    // _asignarYIniciarLineaNativaInterno_) — el wrapper público SÍ lo toma.
    // Prueba indirecta: llamar 2 veces seguidas al wrapper público
    // (asignarYIniciarLineaNativa, CON su propio lock) no debe colgarse
    // (LOCK_TIMEOUT) en una ejecución secuencial normal.
    var s9 = _setup('C9', 'Cejas', 'Depilación de cejas', 'cejas');
    _chk('C9 setup', s9.ok, s9.error);
    if (s9.ok) {
      var r9 = asignarYIniciarLineaNativa({ ticketRef: s9.ref, lineaId: s9.lineaHuerfanaId, staff: s9.staffDueña, _opts: { comisionesData: comTest } });
      _chk('C9. wrapper público con su propio lock, sin timeout', r9 && r9.success === true, JSON.stringify(r9));
    }

  } finally {
    // ── Limpieza: anular todas las líneas de los tickets de prueba ────────
    refsCreadas.forEach(function (ref) {
      try { anularTicketNativoPorRef_(ref, 'limpieza test P6-B', 'test'); } catch (eClean) {
        Logger.log('[cleanup P6-B] ' + ref + ' → ' + eClean);
      }
    });
  }

  Logger.log(fallos === 0 ? '✅ RESULTADO FINAL: asignarYIniciarLineaNativa OK (0 fallos)' : '❌ RESULTADO FINAL: ' + fallos + ' fallo(s)');
  return { ok: fallos === 0, fallos: fallos, refs: refsCreadas };
}

// ── BLOQUE 2N Parte B — finalización nativa por ticket_ref (no por código+staff) ──
// Simétrica a iniciarTicketNativoPorRef_ (esperando→en_servicio), pero para el
// paso siguiente: en_servicio → por_verificar. Match exacto: (ticket_ref===ref
// O promo_ref===ref O promo_ref empieza con ref+':') Y staff===staff. Nunca
// toca líneas 'esperando' (quedan tal cual, un ticket no puede "adelantarse"
// a finalizar algo que ni siquiera se tomó) ni las de otro ticket/staff.
function finalizarTicketNativoPorRef_(ticketRef, staff) {
  try {
    var ref    = String(ticketRef || '').trim();
    var staffN = String(staff || '').trim();
    if (!ref)    return { success: false, message: 'ticket_ref requerido', error: 'TICKET_REF_VACIO' };
    if (!staffN) return { success: false, message: 'staff requerido', error: 'STAFF_VACIO' };

    // Re-verificación defensiva (igual criterio que iniciarTicketNativoPorRef_):
    // esta función puede llamarse directamente, no confía en que el caller ya
    // haya validado la fuente.
    var fuenteInfo = fuenteDelTicket(ref);
    if (!fuenteInfo || fuenteInfo.ok !== true) {
      return { success: false, message: 'No se pudo resolver la fuente del ticket',
               error: (fuenteInfo && fuenteInfo.error) || 'TICKET_SOURCE_NOT_FOUND', ticket_ref: ref };
    }
    if (fuenteInfo.fuente !== 'LINEAS') {
      return { success: false, message: 'Ticket no es nativo LINEAS (fuente=' + fuenteInfo.fuente + ')',
               error: 'TICKET_SOURCE_NOT_LINEAS', ticket_ref: ref };
    }

    var ws = _hojaLineas();
    var d  = ws.getDataRange().getValues();
    var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');

    var filasAFinalizar = [], filasYaFinalizadas = [];
    for (var i = 1; i < d.length; i++) {
      var trFila = String(d[i][LX.ticketRef] || '').trim();
      var prFila = String(d[i][LX.promoRef]  || '').trim();
      var esDeEsteTicket = (trFila === ref) || (prFila === ref) || (prFila.indexOf(ref + ':') === 0);
      if (!esDeEsteTicket) continue;
      var staffFila = String(d[i][LX.staff] || '').trim();
      if (staffFila.toLowerCase() !== staffN.toLowerCase()) continue; // no es esta staff
      var estadoFila = String(d[i][LX.estado] || '');
      if (estadoFila === 'anulado' || estadoFila === 'cobrado') continue; // se ignoran, nunca se tocan
      if (estadoFila === 'en_servicio') filasAFinalizar.push(i);
      else if (estadoFila === 'por_verificar') filasYaFinalizadas.push(i);
      // 'esperando'/'completado': no se tocan, no cuentan para este paso.
    }

    if (!filasAFinalizar.length) {
      if (filasYaFinalizadas.length) {
        // Idempotencia: segunda llamada no vuelve a escribir nada.
        return {
          success: true, ticket_ref: ref, staff: staffN,
          finalizadas: 0, ya_finalizado: true,
          lineas: filasYaFinalizadas.map(function (f) { return String(d[f][LX.id]); })
        };
      }
      return {
        success: false, ticket_ref: ref,
        message: 'No hay líneas en_servicio de "' + staffN + '" para este ticket',
        error: 'SIN_LINEAS_EN_SERVICIO_PARA_STAFF'
      };
    }

    var idsFinalizados = [];
    filasAFinalizar.forEach(function (fila) {
      ws.getRange(fila + 1, LX.estado + 1).setValue('por_verificar');
      // hora_devuelta: solo si está vacía (no pisar un valor ya registrado).
      if (!String(d[fila][LX.horaDevuelta] || '').trim()) {
        ws.getRange(fila + 1, LX.horaDevuelta + 1).setValue(stamp);
      }
      ws.getRange(fila + 1, LX.actualizada + 1).setValue(stamp);
      idsFinalizados.push(String(d[fila][LX.id]));
      // No se toca: servicio, monto, montoRegular, staff, origen, promoRef,
      // ticketRef, esPromo — solo estado/horaDevuelta/actualizada.
    });

    Logger.log('[finalizarTicketNativoPorRef_] ' + ref + ' · ' + staffN + ' → finalizadas=' + idsFinalizados.length);
    return { success: true, ticket_ref: ref, staff: staffN, finalizadas: idsFinalizados.length, ya_finalizado: false, lineas: idsFinalizados };
  } catch (e) {
    Logger.log('[finalizarTicketNativoPorRef_] ⛔ ' + e);
    return { success: false, message: String(e), error: 'EXCEPTION' };
  }
}

// ── BLOQUE 2N-2B Parte D — mandar a cobro nativo por ticket_ref ────────────
// A diferencia de iniciar/finalizar (que filtran también por staff, porque
// son acciones de la staff), esta es una acción de Mikaela sobre el TICKET
// completo: no filtra por staff — abarca TODAS las líneas del ticket, sin
// importar cuál staff las atendió. Cambia únicamente por_verificar→completado.
// Si queda algo esperando o en_servicio, el ticket NO está listo — error
// explícito, nunca se manda parcialmente.
function mandarTicketNativoACobroPorRef_(ticketRef) {
  try {
    var ref = String(ticketRef || '').trim();
    if (!ref) return { success: false, message: 'ticket_ref requerido', error: 'TICKET_REF_VACIO' };

    var fuenteInfo = fuenteDelTicket(ref);
    if (!fuenteInfo || fuenteInfo.ok !== true) {
      return { success: false, message: 'No se pudo resolver la fuente del ticket',
               error: (fuenteInfo && fuenteInfo.error) || 'TICKET_SOURCE_NOT_FOUND', ticket_ref: ref };
    }
    if (fuenteInfo.fuente !== 'LINEAS') {
      return { success: false, message: 'Ticket no es nativo LINEAS (fuente=' + fuenteInfo.fuente + ')',
               error: 'TICKET_SOURCE_MISMATCH', ticket_ref: ref };
    }

    var ws = _hojaLineas();
    var d  = ws.getDataRange().getValues();
    var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');

    // Mismo contrato de pertenencia al ticket que usa
    // getTicketPromoNativoParaEspera_ (vía getTicketLineas): ticket_ref===ref
    // O promo_ref===ref O promo_ref empieza con ref+':'. Se ignoran
    // anulado/cobrado (ya fuera del ciclo de vida operativo).
    var filasPorVerificar = [], filasEsperandoOEnServicio = [], filasCompletado = [], huboAlgunaFilaDelTicket = false;
    for (var i = 1; i < d.length; i++) {
      var trFila = String(d[i][LX.ticketRef] || '').trim();
      var prFila = String(d[i][LX.promoRef]  || '').trim();
      var esDeEsteTicket = (trFila === ref) || (prFila === ref) || (prFila.indexOf(ref + ':') === 0);
      if (!esDeEsteTicket) continue;
      var estadoFila = String(d[i][LX.estado] || '');
      if (estadoFila === 'anulado' || estadoFila === 'cobrado') continue;
      huboAlgunaFilaDelTicket = true;
      if (estadoFila === 'esperando' || estadoFila === 'en_servicio') filasEsperandoOEnServicio.push(i);
      else if (estadoFila === 'por_verificar') filasPorVerificar.push(i);
      else if (estadoFila === 'completado') filasCompletado.push(i);
    }

    if (!huboAlgunaFilaDelTicket) {
      return { success: false, ticket_ref: ref, message: 'No se encontró ninguna línea activa de este ticket', error: 'TICKET_NO_ENCONTRADO' };
    }

    if (filasEsperandoOEnServicio.length) {
      return {
        success: false, ticket_ref: ref,
        message: 'El ticket todavía tiene componentes esperando o en servicio',
        error: 'TICKET_COMPONENTES_PENDIENTES',
        pendientes: filasEsperandoOEnServicio.length
      };
    }

    if (!filasPorVerificar.length) {
      if (filasCompletado.length) {
        // CENTRAL HANDOFF FIX 01 — `completado` en LINEAS ya NO implica "mandado a
        // cobro": desde este fix la autoridad del lifecycle del ticket madre es
        // TicketsFuente. Cuando la staff termina su última parte, las líneas quedan
        // en `completado` y TF en 'esperando_decision_mikaela' — el ticket está en
        // CENTRAL, todavía no cobrable. Antes esta rama devolvía ya_mandado:true sin
        // mirar TF, así que "Mandar a cobro" era un no-op silencioso y el ticket
        // jamás llegaba a Por cobrar.
        var _tfActualMC = '';
        try {
          var _encMC = _tfBuscarFilaInterno(ref, _lnTfData_(_tfHoja()));
          if (_encMC && !_encMC.duplicado) _tfActualMC = String(_encMC.fila.estadoTicket || '').trim();
        } catch (eMC) { _tfActualMC = ''; }
        var _idsYa = filasCompletado.map(function (f) { return String(d[f][LX.id]); });
        if (_tfActualMC === 'enviado_a_cobro') {
          // Idempotencia REAL: líneas cobrables Y ticket ya enviado a cobro.
          return { success: true, ticket_ref: ref, ya_mandado: true, completadas: 0,
                   lineas: _idsYa, estado_ticket: _tfActualMC };
        }
        // Líneas ya cobrables pero TF aún en Central → completar la transición
        // pendiente. No se reescribe ninguna línea.
        var _rTFYa = _lnActualizarEstadoTicketNativoInterno_(_tfHoja(), ref, 'enviado_a_cobro', {});
        if (!_rTFYa.ok) {
          return { success: false, ticket_ref: ref, error: _rTFYa.error || 'TF_ACTUALIZACION_FALLIDA',
                   message: 'Las líneas ya estaban listas pero no se pudo mover el ticket a cobro.',
                   lineas_completadas_sin_tf: _idsYa, detalle: _rTFYa };
        }
        return { success: true, ticket_ref: ref, ya_mandado: false, completadas: 0,
                 lineas: _idsYa, estado_ticket: _rTFYa.estado_nuevo };
      }
      // No hay por_verificar ni completado ni pendientes — estado inesperado.
      return { success: false, ticket_ref: ref, message: 'El ticket no tiene líneas por_verificar para mandar a cobro', error: 'TICKET_NO_ENCONTRADO' };
    }

    var idsCompletados = [];
    filasPorVerificar.forEach(function (fila) {
      ws.getRange(fila + 1, LX.estado + 1).setValue('completado');
      ws.getRange(fila + 1, LX.actualizada + 1).setValue(stamp);
      idsCompletados.push(String(d[fila][LX.id]));
      // No se toca: servicio, monto, montoRegular, staff, origen, promoRef,
      // ticketRef, esPromo, metodoPago, comisión — solo estado/actualizada.
      // No se escribe en HistorialOwner ni CierresPagos: eso es el paso de
      // COBRO, que esta función explícitamente no ejecuta.
    });

    Logger.log('[mandarTicketNativoACobroPorRef_] ' + ref + ' → completadas=' + idsCompletados.length);
    // ── CENTRAL HANDOFF FIX 01 · sincronizar TicketsFuente ────────────────
    // Antes esta función solo movía las LÍNEAS a la condición cobrable; TF
    // quedaba en 'esperando_decision_mikaela'. Con el bucket ahora gobernado
    // por TF, sin esta transición el ticket nunca llegaría a "Por cobrar".
    // Se usa el helper TF existente — no se duplica lógica. La transición
    // 'esperando_decision_mikaela' → 'enviado_a_cobro' está soportada por
    // TF_TRANSICIONES.
    var _rTFCobro = _lnActualizarEstadoTicketNativoInterno_(_tfHoja(), ref, 'enviado_a_cobro', {});
    if (!_rTFCobro.ok) {
      return { success: false, ticket_ref: ref, error: _rTFCobro.error || 'TF_ACTUALIZACION_FALLIDA',
               message: 'Las líneas quedaron listas pero no se pudo mover el ticket a cobro.',
               lineas_completadas_sin_tf: idsCompletados, detalle: _rTFCobro };
    }
    return { success: true, ticket_ref: ref, ya_mandado: false, completadas: idsCompletados.length,
             lineas: idsCompletados, estado_ticket: _rTFCobro.estado_nuevo };
  } catch (e) {
    Logger.log('[mandarTicketNativoACobroPorRef_] ⛔ ' + e);
    return { success: false, message: String(e), error: 'EXCEPTION' };
  }
}

// ── BLOQUE 2N-2C.3 Parte A — cobro nativo por ticket_ref (no por código) ───
// Simétrica a mandarTicketNativoACobroPorRef_ (mismo contrato de pertenencia
// al ticket), pero es el paso de COBRO REAL: liquida con el MISMO motor
// liquidarCobro_ que usan ejecutarCobrarLineas_ (piloto, por código) y
// handleConfirmarCobroNormal (legacy SN) — no se reinventa la fórmula de
// porcentajes — y escribe HistorialOwner + CierresPagos + comisión + visita.
// Solo al final, si todas las escrituras económicas terminaron, marca las
// líneas 'cobrado' en LINEAS. No toca ServicioNormal/Atenciones/ListaEspera.
//
// Orden de escrituras (documentado para CN07 — Sheets no tiene transacciones
// reales): updateComision + HistorialOwner (por línea) → CierresPagos (1 fila)
// → updateVisitaClienta (1 vez) → marcar LINEAS 'cobrado' (último paso). Si
// una excepción ocurre A MITAD del bucle de HistorialOwner, algunas filas
// pueden quedar escritas sin que LINEAS llegue a marcarse 'cobrado' — igual
// límite que ya tiene ejecutarCobrarLineas_/handleConfirmarCobroNormal hoy.
// Reconciliación: si se reintenta un ticket que falló a mitad, revisar
// HistorialOwner por ticket_ref (col E) antes de reintentar, para no duplicar
// filas — este mismo ticket_ref real en col E (en vez de la etiqueta genérica
// 'LINEAS') es lo que hace posible esa reconciliación.
function cobrarTicketNativoPorRef_(ticketRef, data) {
  try {
    var ref = String(ticketRef || '').trim();
    if (!ref) return { success: false, message: 'ticket_ref requerido', error: 'TICKET_REF_VACIO' };

    var fuenteInfo = fuenteDelTicket(ref);
    if (!fuenteInfo || fuenteInfo.ok !== true) {
      return { success: false, message: 'No se pudo resolver la fuente del ticket',
               error: (fuenteInfo && fuenteInfo.error) || 'TICKET_SOURCE_NOT_FOUND', ticket_ref: ref };
    }
    if (fuenteInfo.fuente !== 'LINEAS') {
      return { success: false, message: 'Ticket no es nativo LINEAS (fuente=' + fuenteInfo.fuente + ')',
               error: 'TICKET_SOURCE_MISMATCH', ticket_ref: ref };
    }

    var metodoPago = String((data && data.metodoPago) || 'Efectivo');

    var ws = _hojaLineas();
    var d  = ws.getDataRange().getValues();

    // Mismo contrato de pertenencia al ticket que finalizarTicketNativoPorRef_ /
    // mandarTicketNativoACobroPorRef_: ticket_ref===ref O promo_ref===ref O
    // promo_ref empieza con ref+':'. Se ignoran 'anulado' (fuera del ciclo).
    var filasCobrables = [], filasPendientes = [], filasYaCobradas = [], huboAlgunaFilaDelTicket = false;
    for (var i = 1; i < d.length; i++) {
      var trFila = String(d[i][LX.ticketRef] || '').trim();
      var prFila = String(d[i][LX.promoRef]  || '').trim();
      var esDeEsteTicket = (trFila === ref) || (prFila === ref) || (prFila.indexOf(ref + ':') === 0);
      if (!esDeEsteTicket) continue;
      var estadoFila = String(d[i][LX.estado] || '');
      if (estadoFila === 'anulado') continue;
      huboAlgunaFilaDelTicket = true;
      // A3: 'completado' es el estado canónico para cobrar; 'por_verificar' se
      // acepta defensivamente (mismo criterio ya usado por ejecutarCobrarLineas_,
      // que acepta ['completado','por_verificar']) SOLO si no hay componentes
      // esperando/en_servicio/propuesta del mismo ticket (chequeado abajo).
      // FIX BLOQUE G1: 'propuesta' (auth pendiente) también bloquea — ya lo
      // trata así _lnEvaluarEstadoAgregadoTicketInterno_ (propuestas++,
      // bloqueado=true) y LN5_ESTADOS_LINEA_PROHIBIDOS del Bloque 2N-5B;
      // esta función era la única que lo dejaba pasar sin cobrar dueño.
      if (estadoFila === 'propuesta' || estadoFila === 'esperando' || estadoFila === 'en_servicio') filasPendientes.push(i);
      else if (estadoFila === 'completado' || estadoFila === 'por_verificar') filasCobrables.push(i);
      else if (estadoFila === 'cobrado') filasYaCobradas.push(i);
    }

    if (!huboAlgunaFilaDelTicket) {
      return { success: false, ticket_ref: ref, message: 'No se encontró ninguna línea activa de este ticket', error: 'TICKET_NO_ENCONTRADO' };
    }

    if (filasPendientes.length) {
      return {
        success: false, ticket_ref: ref,
        message: 'El ticket todavía tiene componentes esperando o en servicio',
        error: 'TICKET_COMPONENTES_PENDIENTES',
        pendientes: filasPendientes.length
      };
    }

    if (!filasCobrables.length) {
      if (filasYaCobradas.length) {
        // A4: idempotencia — todo el ticket ya estaba cobrado. Cero escrituras nuevas.
        return { success: true, ticket_ref: ref, ya_cobrado: true };
      }
      return { success: false, ticket_ref: ref, message: 'El ticket no tiene líneas completado/por_verificar para cobrar', error: 'TICKET_NO_ENCONTRADO' };
    }

    // ── A5: armar líneas para el motor único (hechos, igual que piloto/legacy) ──
    var codigo = String(d[filasCobrables[0]][LX.codigo]  || '').trim();
    var nombre = String(d[filasCobrables[0]][LX.cliente] || '');
    var lineasCobro = filasCobrables.map(function (fila) {
      return {
        staff:         String(d[fila][LX.staff] || ''),
        area:          String(d[fila][LX.area]  || ''),
        servicio:      String(d[fila][LX.servicio] || ''),
        precioRegular: Number(d[fila][LX.montoRegular] || d[fila][LX.monto] || 0),
        precioPromo:   Number(d[fila][LX.monto] || 0)
      };
    });
    var regularTotal = lineasCobro.reduce(function (s, l) { return s + Number(l.precioRegular || 0); }, 0);

    // MISMO motor que ejecutarCobrarLineas_/handleConfirmarCobroNormal
    // (tarjeta=regular / efectivo=promo, comisión por área). No se duplica el %.
    var liq = liquidarCobro_(lineasCobro, metodoPago, regularTotal);
    var totalCobrado = liq.total;

    var now      = new Date();
    var fechaStr = Utilities.formatDate(now, LINEAS_TZ, 'dd/MM/yyyy');
    var horaStr  = Utilities.formatDate(now, LINEAS_TZ, 'HH:mm');
    var nota     = (data && data.notaAjuste ? String(data.notaAjuste) + ' · ' : '') + 'ticket_ref:' + ref;

    // ── A6: HistorialOwner — una fila por línea liquidada. Col E = ticket_ref
    // REAL (ej. SN-9000), no la etiqueta genérica 'LINEAS' — se necesita
    // trazabilidad e idempotencia por ticket. ────────────────────────────────
    var wsH = getSheet('HistorialOwner');
    liq.lineas.forEach(function (l) {
      // A7: comisión — una sola vez por línea liquidada con staff y monto positivo.
      if (l.staff && l.monto > 0) {
        try { updateComision(l.staff, l.monto); }
        catch (eC) { Logger.log('[cobrarTicketNativoPorRef_] updateComision falló para ' + ref + '/' + l.staff + ': ' + eC); }
      }
      wsH.appendRow([fechaStr, horaStr, codigo, nombre, ref, l.servicio, l.area, l.staff, l.monto, l.comision, metodoPago, nota]);
    });

    // ── A8: CierresPagos — una sola fila de cierre para el ticket completo.
    // ticket_ref se conserva dentro de `nota` (no se agrega columna nueva, para
    // no romper lectores existentes de esta hoja — mismo criterio conservador
    // que el resto del bloque 2N). ───────────────────────────────────────────
    var wsPagos  = getSheet('CierresPagos');
    var desglose = JSON.stringify(liq.lineas.map(function (l) {
      return { staff: l.staff, servicio: l.servicio, area: l.area, monto: l.monto, comision: l.comision };
    }));
    var staff0 = (liq.lineas[0] && liq.lineas[0].staff) || '';
    var svcTxt = lineasCobro.map(function (l) { return l.servicio; }).join(' + ');
    wsPagos.appendRow([now, horaStr, nombre, staff0, svcTxt, totalCobrado, metodoPago, desglose, nota]);

    // ── A9: visita — una sola vez para el ticket completo, nunca por componente. ─
    try { updateVisitaClienta(codigo); }
    catch (eV) { Logger.log('[cobrarTicketNativoPorRef_] updateVisitaClienta falló para ' + ref + ': ' + eV); }

    // ── A10: LINEAS — SOLO después de que las escrituras económicas terminaron. ──
    var stamp = Utilities.formatDate(now, LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');
    filasCobrables.forEach(function (fila) {
      ws.getRange(fila + 1, LX.estado + 1).setValue('cobrado');
      ws.getRange(fila + 1, LX.metodoPago + 1).setValue(metodoPago);
      if (!String(d[fila][LX.horaDevuelta] || '').trim()) {
        ws.getRange(fila + 1, LX.horaDevuelta + 1).setValue(stamp);
      }
      ws.getRange(fila + 1, LX.actualizada + 1).setValue(stamp);
      // No se toca: monto, montoRegular, staff, servicio, area, promoRef,
      // ticketRef, origen, esPromo.
    });

    Logger.log('[cobrarTicketNativoPorRef_] ' + ref + ' → cobradas=' + filasCobrables.length +
      ' · total=' + totalCobrado + ' · metodo=' + metodoPago);

    // A11: resultado mínimo requerido.
    return {
      success: true, ticket_ref: ref, metodoPago: metodoPago,
      total: totalCobrado, lineas_cobradas: filasCobrables.length,
      liquidacion: liq.lineas
    };
  } catch (e) {
    Logger.log('[cobrarTicketNativoPorRef_] ⛔ ' + e);
    return { success: false, message: String(e), error: 'EXCEPTION', ticket_ref: String(ticketRef || '') };
  }
}

// ── BLOQUE 2N-2C.2 (RETIRADA del flujo operativo, ver corrección posterior) ──
// PROHIBIDO llamarla desde cualquier handler de aprobación o creación de
// líneas: no puede decidir a qué ticket pertenece una autorización — si la
// clienta tiene 2 tickets activos el mismo día (ej. dos slots), es ambigua
// y podría atar el extra al ticket equivocado. La identidad correcta del
// ticket viene AHORA del ticket_ref persistido en la propia solicitud de
// autorización (col O de Autorizaciones), propagado desde el frontend
// (sendAuthorizationRequest, nexserv-main-4.js) con el idEspera real del slot.
// Esta función queda únicamente como utilidad de DIAGNÓSTICO manual (ej. para
// investigar solicitudes históricas sin ticket_ref) — nunca como fallback
// automático ni como fuente de identidad en ningún handler.
function _ticketRefActivoPorCodigo_(codigo, staffPreferida) {
  var visita = visitaDelDia(codigo);
  var activas = getLineasDeVisita(visita);
  var refTicket = '';
  for (var i = 0; i < activas.length; i++) {
    var L = activas[i];
    if (L.estado === 'cobrado' || L.estado === 'anulado') continue;
    var r = String(L.promoRef || L.ticketRef || '').trim();
    if (!r) continue;
    if (!refTicket) refTicket = r;
    if (staffPreferida && String(L.staff) === String(staffPreferida)) refTicket = r; // prioridad: misma staff
  }
  return refTicket;
}

// ── BLOQUE 2N-2C.2 Parte A — agregar servicio extra nativo a un ticket LINEAS ──
// A diferencia de lineaAgregarExtra (mirror legacy, dedupe por valor, sin
// validar fuente), esta función exige fuenteDelTicket()===LINEAS explícito,
// identidad exacta de pertenencia al ticket (ticketRef viene YA resuelto por
// el caller desde el ticket_ref persistido de la autorización — nunca por
// código), y dedupe real por authId vía el campo nativo syna_ref
// ('AUTH:'+authId), no por texto embebido en obs. No crea fila en
// TicketsFuente, ServiciosExtras, ServicioNormal ni Atenciones.
function agregarExtraTicketNativoPorRef_(ticketRef, data) {
  try {
    var ref = String(ticketRef || '').trim();
    if (!ref) return { success: false, message: 'ticket_ref requerido', error: 'TICKET_REF_VACIO' };

    var fuenteInfo = fuenteDelTicket(ref);
    if (!fuenteInfo || fuenteInfo.ok !== true) {
      return { success: false, message: 'No se pudo resolver la fuente del ticket',
               error: (fuenteInfo && fuenteInfo.error) || 'TICKET_SOURCE_NOT_FOUND', ticket_ref: ref };
    }
    if (fuenteInfo.fuente !== 'LINEAS') {
      return { success: false, message: 'Ticket no es nativo LINEAS (fuente=' + fuenteInfo.fuente + ')',
               error: 'TICKET_SOURCE_MISMATCH', ticket_ref: ref };
    }

    data = data || {};
    var servicio = String(data.servicio || data.servicioNombre || '').trim();
    var area     = String(data.area     || data.servicioArea    || '').trim();
    var staff    = String(data.staff    || data.staffNombre     || '').trim();
    var monto    = Number(data.monto !== undefined && data.monto !== null && data.monto !== '' ? data.monto : (data.precio || 0));
    var authId   = String(data.authId || '').trim();

    if (!servicio) return { success: false, message: 'servicio requerido', error: 'EXTRA_SERVICIO_REQUIRED', ticket_ref: ref };
    if (!area)     return { success: false, message: 'area requerida',     error: 'EXTRA_AREA_REQUIRED',     ticket_ref: ref };
    if (!staff)    return { success: false, message: 'staff requerida',    error: 'EXTRA_STAFF_REQUIRED',    ticket_ref: ref };
    if (!Number.isFinite(monto) || monto <= 0) {
      return { success: false, message: 'monto inválido', error: 'EXTRA_MONTO_INVALIDO', ticket_ref: ref };
    }

    var ws = _hojaLineas();
    var d  = ws.getDataRange().getValues();

    var lineasDelTicket = [];
    var lineaMismaStaffEnServicio = null;
    for (var i = 1; i < d.length; i++) {
      var trFila = String(d[i][LX.ticketRef] || '').trim();
      var prFila = String(d[i][LX.promoRef]  || '').trim();
      var esDeEsteTicket = (trFila === ref) || (prFila === ref) || (prFila.indexOf(ref + ':') === 0);
      if (!esDeEsteTicket) continue;

      // Regla 8 (idempotencia): la clave es el authId persistido en el campo
      // nativo syna_ref ('AUTH:'+authId) — no un marcador de texto dentro de
      // obs. Si ya existe una línea con este mismo syna_ref, se devuelve tal
      // cual (ya_registrado:true), sin crear otra.
      var _synaRefBuscado = authId ? ('AUTH:' + authId) : '';
      if (_synaRefBuscado && String(d[i][LX.synaRef] || '').trim() === _synaRefBuscado) {
        return { success: true, ya_registrado: true, linea_id: String(d[i][LX.id]), id: String(d[i][LX.id]), ticket_ref: ref };
      }

      var estadoFila = String(d[i][LX.estado] || '');
      if (estadoFila === 'anulado') continue;
      lineasDelTicket.push(i);
      if (estadoFila === 'en_servicio' && String(d[i][LX.staff] || '').trim() === staff) {
        lineaMismaStaffEnServicio = i;
      }
    }

    if (!lineasDelTicket.length) {
      return { success: false, message: 'El ticket no tiene ninguna línea activa', error: 'TICKET_SIN_LINEAS_ACTIVAS', ticket_ref: ref };
    }

    var todasCobradas = lineasDelTicket.every(function (fila) { return String(d[fila][LX.estado]) === 'cobrado'; });
    if (todasCobradas) {
      return { success: false, message: 'El ticket ya está cobrado, no admite servicios extra', error: 'TICKET_YA_COBRADO', ticket_ref: ref };
    }

    var lineaPrincipal = lineasDelTicket[0];
    var codigo      = String(d[lineaPrincipal][LX.codigo]  || '').trim();
    var cliente     = String(d[lineaPrincipal][LX.cliente] || '');
    var idPrincipal = String(d[lineaPrincipal][LX.id]      || '');
    // AM-1R-1 §14 — el extra HEREDA la visita persistida de su línea madre,
    // no la recalcula. Así un ticket histórico (visita V-COD-dia) mantiene su
    // semántica y uno nuevo (visita = ref madre) propaga la suya: nunca se
    // mezclan las dos dentro de un mismo ticket. Sin backfill.
    var visitaMadre = String(d[lineaPrincipal][LX.visita] || '').trim();

    // Estado del extra: si la staff que lo va a hacer ya está en_servicio en este
    // mismo ticket, el extra nace en_servicio también (lo está haciendo ya); si
    // no, nace esperando (aprobado, pendiente de iniciar).
    var estadoExtra = lineaMismaStaffEnServicio !== null ? 'en_servicio' : 'esperando';

    // ── FIX F03 · GAP_EXTRA_NATIVO_SIN_MARCADORES ─────────────────────────
    // Esta función creaba la línea sin marcadores NATIVE, así que el ticket
    // entero quedaba inválido: _finalizarLineaNativaInterno_ valida marcadores
    // ANTES que auth_estado y devolvía TICKET_NATIVE_MARKERS_INVALID.
    // Se usan las MISMAS autoridades que _lnCrearExtraNativoInterno_ — mismos
    // prefijos, mismo fingerprint — para que la línea sea indistinguible de un
    // extra creado por la ruta certificada. No se inventa formato ni se relaja
    // ninguna validación.
    var _lridF03 = String(data.lineRequestId || '').trim();
    if (!_lridF03) {
      // Sin lineRequestId del caller, la identidad estable del extra es su
      // autorización: authId es único por solicitud, así que un reintento de la
      // MISMA aprobación produce el MISMO marcador (idempotencia preservada).
      _lridF03 = 'AUTHEXTRA-' + (String(data.authId || '').trim() || (ref + '-' + idPrincipal));
    }
    var _fpF03 = _lnFingerprintExtra_({
      ticketRef: ref, lineaPadre: idPrincipal, codigo: codigo, cliente: cliente,
      staff: staff, area: area, servicioExtra: servicio, precio: monto,
      source: 'MIKAELA', modo: 'YA_EJECUTADO',
      obsLibre: String(data.observaciones || data.nota || '')
    });
    var _obsLibreF03 = String(data.observaciones || data.nota || '');
    var _obsF03 = _obsLibreF03;
    [LN_LINE_REQUEST_ID_PREFIX + _lridF03 + ']',
     LN_LINE_FINGERPRINT_PREFIX + _fpF03 + ']'].forEach(function (m) {
      _obsF03 = _obsF03 ? (_obsF03 + ' ' + m) : m;
    });

    // ── FIX F03 · GAP_EXTRA_NATIVO_SIN_PUESTO ─────────────────────────────
    // La línea nacía con puesto_trabajo vacío → PUESTO_TRABAJO_VACIO_AL_FINALIZAR.
    // El puesto lo decide la autoridad canónica (_lnAsignarPuestoTrabajoInterno_,
    // NexServ_PuestosTrabajo.gs) con la capacidad resuelta desde Comisiones:
    // nunca un número fijo, nunca inferido del área. Como el extra pertenece a
    // una atención ya existente (mismo ticketRef + misma staff), la autoridad
    // devuelve el puesto HEREDADO — no consume uno nuevo.
    // Solo aplica cuando el extra nace en_servicio: uno 'esperando' todavía no
    // ocupa puesto (lo recibirá al iniciarse, como cualquier otra línea).
    var _puestoF03 = '';
    if (estadoExtra === 'en_servicio') {
      var _comF03;
      try { _comF03 = getSheet('Comisiones').getDataRange().getValues(); }
      catch (eComF03) {
        return { success: false, ticket_ref: ref, error: 'NO_SE_PUDO_LEER_COMISIONES', message: String(eComF03) };
      }
      var _capF03 = _lnResolverCapacidadStaffInterno_(_comF03, staff);
      if (!_capF03.ok) {
        return { success: false, ticket_ref: ref, error: _capF03.error,
                 detalle: _capF03.detalle, fase: 'resolver_capacidad_staff' };
      }
      var _asigF03 = _lnAsignarPuestoTrabajoInterno_(
        ws.getDataRange().getValues(), ref, '', staff, _capF03.capacidad, undefined);
      if (!_asigF03.ok) {
        // Fail-closed ANTES de escribir: no se crea un extra que después no
        // podría finalizarse.
        return { success: false, ticket_ref: ref, error: _asigF03.error,
                 detalle: _asigF03.detalle, fase: 'asignacion_puesto' };
      }
      _puestoF03 = _asigF03.puesto;
    }

    var r = crearLinea({
      visita: visitaMadre || visitaDelDia(codigo),   // AM-1R-1 §14 — herencia
      codigo: codigo, cliente: cliente,
      staff: staff, area: area, servicio: servicio,
      extras: 'servicio extra',
      esPromo: false, promoRef: ref, ticketRef: ref, slot: '',
      monto: monto, montoRegular: monto,
      estado: estadoExtra, origen: 'NEXSERV',
      // FIX F02 AUTH EXTRA 01 (AUTH_ESTADO_NO_PROPAGADO) — esta función se
      // ejecuta ÚNICAMENTE desde handleAprobarAutorizacion, o sea DESPUÉS de
      // que Central aprobó la solicitud. La línea nacía con auth_estado = ''
      // (crearLinea no recibía el campo), así que quedaba desincronizada:
      // Autorizaciones decía 'aprobado' pero LINEAS no tenía autoridad técnica.
      // Al finalizar, LN3_AUTH_OPERATIVOS (['no_requiere','aprobada'])
      // rechazaba el '' con LINE_AUTH_NOT_OPERATIVE y la staff no podía cerrar
      // su parte. Toda línea creada tras una aprobación de Central debe nacer
      // completamente operativa: aprobación visual y autoridad técnica
      // sincronizadas en el mismo acto.
      authEstado: 'aprobada',
      synaRef: _synaRefBuscado,
      lineaPadre: idPrincipal,
      obs: _obsF03                 // FIX F03 — marcadores NATIVE + obs libre
    });

    if (!r.success) {
      return { success: false, message: 'No se pudo crear la línea del extra', error: r.error || r.message, ticket_ref: ref };
    }

    // ── FIX F03 · persistir el puesto ────────────────────────────────────
    // `crearLinea` no acepta puesto_trabajo y `actualizarLinea` lo bloquea a
    // propósito ("AF solo puede ser gestionado por el flujo nativo de
    // puestos"). Por eso se escribe la celda directamente, igual que hace
    // _iniciarLineaNativaInterno_ — el valor ya lo decidió la autoridad
    // canónica arriba, acá solo se persiste.
    if (_puestoF03 !== '') {
      try {
        var _dPost = ws.getDataRange().getValues();
        for (var _pi = 1; _pi < _dPost.length; _pi++) {
          if (String(_dPost[_pi][LX.id] || '').trim() === String(r.id).trim()) {
            ws.getRange(_pi + 1, LX.puestoTrabajo + 1).setValue(_puestoF03);
            break;
          }
        }
      } catch (ePF03) {
        // La línea ya existe y es válida salvo por el AF: se reporta en vez de
        // dejar un extra que después no podría finalizarse.
        return { success: false, ticket_ref: ref, linea_id: r.id,
                 error: 'PUESTO_NO_PERSISTIDO', message: String(ePF03) };
      }
    }

    Logger.log('[agregarExtraTicketNativoPorRef_] ' + ref + ' → línea extra ' + r.id + ' (' + servicio + ', $' + monto + ', ' + estadoExtra + ')');
    return { success: true, ya_registrado: false, linea_id: r.id, id: r.id, ticket_ref: ref, estado: estadoExtra };
  } catch (e) {
    Logger.log('[agregarExtraTicketNativoPorRef_] ⛔ ' + e);
    return { success: false, message: String(e), error: 'EXCEPTION', ticket_ref: String(ticketRef || '') };
  }
}

// ── BLOQUE 2N-2C.2 Parte C — anular UN componente de un ticket nativo ──────
// Identidad exacta por linea_id (nunca por nombre/precio). No borra filas:
// estado='anulado' + motivo_anulacion + timestamp, preserva todo lo demás.
// Si era el último componente vivo del ticket, refleja 'anulado' en
// TicketsFuente vía la variante INTERNA (ya estamos dentro del ScriptLock de
// doPost — la pública _tfAcquireLock() de nuevo daría LOCK_TIMEOUT).
function anularComponenteTicketNativo_(ticketRef, lineaId, motivo, actor) {
  try {
    var ref = String(ticketRef || '').trim();
    var id  = String(lineaId  || '').trim();
    if (!ref) return { success: false, message: 'ticket_ref requerido', error: 'TICKET_REF_VACIO' };
    if (!id)  return { success: false, message: 'linea_id requerido',   error: 'LINEA_ID_VACIO' };

    var fuenteInfo = fuenteDelTicket(ref);
    if (!fuenteInfo || fuenteInfo.ok !== true) {
      return { success: false, message: 'No se pudo resolver la fuente del ticket',
               error: (fuenteInfo && fuenteInfo.error) || 'TICKET_SOURCE_NOT_FOUND', ticket_ref: ref };
    }
    if (fuenteInfo.fuente !== 'LINEAS') {
      return { success: false, message: 'Ticket no es nativo LINEAS (fuente=' + fuenteInfo.fuente + ')',
               error: 'TICKET_SOURCE_MISMATCH', ticket_ref: ref };
    }

    var hit = getLineaPorId(id);
    if (!hit) return { success: false, message: 'Línea no encontrada: ' + id, error: 'LINEA_NO_ENCONTRADA', ticket_ref: ref, linea_id: id };

    var tr = String(hit.linea.ticketRef || '').trim();
    var pr = String(hit.linea.promoRef  || '').trim();
    var esDeEsteTicket = (tr === ref) || (pr === ref) || (pr.indexOf(ref + ':') === 0);
    if (!esDeEsteTicket) {
      return { success: false, message: 'La línea no pertenece a este ticket', error: 'LINEA_NO_PERTENECE_AL_TICKET', ticket_ref: ref, linea_id: id };
    }

    if (hit.linea.estado === 'anulado') {
      return { success: true, ya_anulado: true, ticket_ref: ref, linea_id: id };
    }
    if (hit.linea.estado === 'cobrado') {
      return { success: false, message: 'La línea ya está cobrada, no se puede anular', error: 'LINEA_YA_COBRADA', ticket_ref: ref, linea_id: id };
    }

    var motivoTxt = String(motivo || 'sin motivo') + (actor ? ' · por ' + String(actor) : '');
    var r = actualizarLinea(id, { estado: 'anulado', motivoAnulacion: motivoTxt });
    if (!r || !r.success) {
      return { success: false, message: 'No se pudo anular la línea', error: (r && r.message) || 'ANULACION_FALLO', ticket_ref: ref, linea_id: id };
    }

    // Si no queda ningún componente vivo del ticket, reflejar 'anulado' en TicketsFuente.
    var ws = _hojaLineas(); var d = ws.getDataRange().getValues();
    var quedaAlgunaActiva = false;
    for (var i = 1; i < d.length; i++) {
      var trFila = String(d[i][LX.ticketRef] || '').trim();
      var prFila = String(d[i][LX.promoRef]  || '').trim();
      var esDeEsteTicket2 = (trFila === ref) || (prFila === ref) || (prFila.indexOf(ref + ':') === 0);
      if (!esDeEsteTicket2) continue;
      var e2 = String(d[i][LX.estado] || '');
      if (e2 !== 'anulado' && e2 !== 'cobrado') { quedaAlgunaActiva = true; break; }
    }
    if (!quedaAlgunaActiva) {
      try {
        var tfWs = _tfHoja(); var tfData = tfWs.getDataRange().getValues();
        _tfActualizarEstadoInterno(ref, 'anulado', tfWs, tfData);
      } catch (eTf) { Logger.log('[anularComponenteTicketNativo_] no se pudo actualizar TicketsFuente: ' + eTf); }
    }

    Logger.log('[anularComponenteTicketNativo_] ' + ref + ' · línea ' + id + ' → anulado (' + motivoTxt + ')');
    return { success: true, ya_anulado: false, ticket_ref: ref, linea_id: id };
  } catch (e) {
    Logger.log('[anularComponenteTicketNativo_] ⛔ ' + e);
    return { success: false, message: String(e), error: 'EXCEPTION', ticket_ref: String(ticketRef || '') };
  }
}

// ── BLOQUE 2N-2C.2 Parte D — anular TODO un ticket nativo ──────────────────
// Anula solo las líneas activas (esperando/en_servicio/por_verificar/completado).
// Nunca reescribe cobrado/anulado. Idempotente: si no queda nada vivo, éxito
// sin escrituras. No toca hojas legacy.
function anularTicketNativoPorRef_(ticketRef, motivo, actor) {
  try {
    var ref = String(ticketRef || '').trim();
    if (!ref) return { success: false, message: 'ticket_ref requerido', error: 'TICKET_REF_VACIO' };

    var fuenteInfo = fuenteDelTicket(ref);
    if (!fuenteInfo || fuenteInfo.ok !== true) {
      return { success: false, message: 'No se pudo resolver la fuente del ticket',
               error: (fuenteInfo && fuenteInfo.error) || 'TICKET_SOURCE_NOT_FOUND', ticket_ref: ref };
    }
    if (fuenteInfo.fuente !== 'LINEAS') {
      return { success: false, message: 'Ticket no es nativo LINEAS (fuente=' + fuenteInfo.fuente + ')',
               error: 'TICKET_SOURCE_MISMATCH', ticket_ref: ref };
    }

    var ws = _hojaLineas(); var d = ws.getDataRange().getValues();
    var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');
    var motivoTxt = String(motivo || 'sin motivo') + (actor ? ' · por ' + String(actor) : '');

    var filasAAnular = [], huboAlgunaFilaDelTicket = false;
    for (var i = 1; i < d.length; i++) {
      var trFila = String(d[i][LX.ticketRef] || '').trim();
      var prFila = String(d[i][LX.promoRef]  || '').trim();
      var esDeEsteTicket = (trFila === ref) || (prFila === ref) || (prFila.indexOf(ref + ':') === 0);
      if (!esDeEsteTicket) continue;
      huboAlgunaFilaDelTicket = true;
      var estadoFila = String(d[i][LX.estado] || '');
      if (estadoFila === 'cobrado' || estadoFila === 'anulado') continue;
      filasAAnular.push(i);
    }

    if (!huboAlgunaFilaDelTicket) {
      return { success: false, ticket_ref: ref, message: 'No se encontró ninguna línea de este ticket', error: 'TICKET_NO_ENCONTRADO' };
    }

    if (!filasAAnular.length) {
      // Idempotencia: no queda nada vivo para anular (ya estaba todo cobrado/anulado).
      return { success: true, ticket_ref: ref, ya_anulado: true, anuladas: 0 };
    }

    var idsAnulados = [];
    filasAAnular.forEach(function (fila) {
      ws.getRange(fila + 1, LX.estado + 1).setValue('anulado');
      ws.getRange(fila + 1, LX.motivoAnulacion + 1).setValue(motivoTxt);
      ws.getRange(fila + 1, LX.actualizada + 1).setValue(stamp);
      idsAnulados.push(String(d[fila][LX.id]));
      // No se toca: monto, montoRegular, staff, servicio, area, promoRef, ticketRef, origen.
    });

    try {
      var tfWs = _tfHoja(); var tfData = tfWs.getDataRange().getValues();
      _tfActualizarEstadoInterno(ref, 'anulado', tfWs, tfData);
    } catch (eTf) { Logger.log('[anularTicketNativoPorRef_] no se pudo actualizar TicketsFuente: ' + eTf); }

    Logger.log('[anularTicketNativoPorRef_] ' + ref + ' → anuladas=' + idsAnulados.length + ' · motivo=' + motivoTxt);
    return { success: true, ticket_ref: ref, ya_anulado: false, anuladas: idsAnulados.length, lineas: idsAnulados };
  } catch (e) {
    Logger.log('[anularTicketNativoPorRef_] ⛔ ' + e);
    return { success: false, message: String(e), error: 'EXCEPTION', ticket_ref: String(ticketRef || '') };
  }
}


// ═══════════════════════════════════════════════════════════════════════════
// SINCRONIZACIÓN legacy → LINEAS para mandarACobro
//
// NOTA DE ESTADO — leer antes de tocar:
//   LINEAS_ESTADOS = ['esperando','en_servicio','completado','cobrado','anulado'].
//   NO existe 'por_cobrar'. getTableroLineas() clasifica 'completado' dentro del
//   balde que handleGetListaCompleta expone como "por cobrar", y actualizarLinea()
//   descarta cualquier estado fuera de la lista blanca.
//   → En LINEAS, "por cobrar" ES 'completado'. La transición real es:
//        en_servicio → completado   (visible como "por cobrar")
//   Por eso este wrapper existe: da el nombre semántico correcto sin inventar
//   un estado nuevo que romperia getTableroLineas y el motor de cobro.
//
// Por qué NO se reutiliza marcarLineaCompletadaPorCodigo() acá:
//   ese helper marca UNA línea y luego dispara un barrido que cierra otras líneas
//   de la misma staff+código. mandarACobro cierra UN TICKET completo, no "lo de una
//   staff": en un TM multi-staff hay que cerrar todos los slots, y en cambio NO hay
//   que tocar otro ticket distinto de la misma clienta. El barrido haría ambas cosas
//   al revés. Acá el alcance se define por la referencia del ticket, nada más.
// ═══════════════════════════════════════════════════════════════════════════

// Devuelve los índices (0-based sobre `d`) de las líneas de HOY que pertenecen a
// un ticket. Estrategia en cascada — nunca depende solo de promo_ref (CASO E):
//   1. promo_ref === ticketId            → SN-/SP-
//   2. promo_ref empieza con ticketId+':'→ slots de un TM (TM-0378:1, :2 …)
//   3. ticket_ref === ticketId           → líneas de cola ya asignadas
//   4. (solo si 1-3 no dieron nada y hay codigo) líneas activas de esa clienta
//      SIN ninguna referencia → la cola sin asignar. Se registra que fue respaldo.
function _filasDeTicketLineas(d, ticketId, codigo) {
  var tid = String(ticketId || '').trim();
  var filas = [], modo = '';
  if (tid) {
    for (var i = 1; i < d.length; i++) {
      if (!_esHoy(d[i][LX.fecha])) continue;
      var pr = String(d[i][LX.promoRef]  || '').trim();
      var tr = String(d[i][LX.ticketRef] || '').trim();
      if (pr === tid || pr.indexOf(tid + ':') === 0 || tr === tid) filas.push(i);
    }
    if (filas.length) return { filas: filas, modo: 'ref' };
  }
  var cod = String(codigo || '').trim();
  if (!cod) return { filas: [], modo: 'sin_match' };
  for (var j = 1; j < d.length; j++) {
    if (!_esHoy(d[j][LX.fecha])) continue;
    if (String(d[j][LX.codigo]) !== cod) continue;
    var est = String(d[j][LX.estado]);
    if (est !== 'esperando' && est !== 'en_servicio') continue;
    if (String(d[j][LX.promoRef] || '').trim() || String(d[j][LX.ticketRef] || '').trim()) continue;
    filas.push(j);
  }
  return { filas: filas, modo: filas.length ? 'respaldo_codigo' : 'sin_match' };
}

// mandarACobro → todas las líneas ACTIVAS del ticket pasan a 'completado'.
// Idempotente: repetirla no crea nada, no retrocede estados y no toca cobrado/anulado.
// Devuelve éxito SOLO si encontró al menos una línea del ticket.
//
// opts.dryRun = true → NO escribe. Solo informa qué haría. Sirve para verificar
// LINEAS ANTES de mutar el legacy: si no hay línea sincronizable, el handler
// aborta sin haber tocado nada y el ticket queda consistente.
function marcarLineasPorCobrarPorTicket(ticketId, codigo, opts) {
  try {
    opts = opts || {};
    var dry = opts.dryRun === true;
    var ws = _hojaLineas();
    var d  = ws.getDataRange().getValues();
    var loc = _filasDeTicketLineas(d, ticketId, codigo);

    if (!loc.filas.length) {
      Logger.log('[marcarLineasPorCobrarPorTicket]' + (dry ? ' (dryRun)' : '')
        + ' ⛔ sin línea para ticket=' + ticketId + ' codigo=' + codigo);
      return { ok: false, motivo: 'sin_linea', ticketId: ticketId, codigo: codigo, encontradas: 0, dryRun: dry };
    }

    var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');
    var marcadas = 0, yaEstaban = 0, ignoradas = 0, detalle = [];

    for (var k = 0; k < loc.filas.length; k++) {
      var f = loc.filas[k];
      var antes = String(d[f][LX.estado]);
      var id    = String(d[f][LX.id]);

      if (antes === 'cobrado' || antes === 'anulado') { ignoradas++; detalle.push({ id: id, antes: antes, despues: antes, accion: 'ignorada' }); continue; }
      if (antes === 'completado')                     { yaEstaban++; detalle.push({ id: id, antes: antes, despues: antes, accion: 'ya_estaba' }); continue; }

      if (!dry) {
        ws.getRange(f + 1, LX.estado + 1).setValue('completado');
        if (!String(d[f][LX.horaDevuelta] || '').trim()) ws.getRange(f + 1, LX.horaDevuelta + 1).setValue(stamp);
        ws.getRange(f + 1, LX.actualizada + 1).setValue(stamp);
      }
      marcadas++;
      detalle.push({ id: id, antes: antes, despues: 'completado', accion: dry ? 'marcaria' : 'marcada' });
    }

    Logger.log('[marcarLineasPorCobrarPorTicket] ticket=' + ticketId + ' codigo=' + codigo
      + ' modo=' + loc.modo + ' encontradas=' + loc.filas.length
      + ' marcadas=' + marcadas + ' yaEstaban=' + yaEstaban + ' ignoradas=' + ignoradas
      + ' detalle=' + JSON.stringify(detalle));

    // ── INVARIANTE ──────────────────────────────────────────────────────────
    // Es INVÁLIDO devolver éxito con marcadas=0 Y yaEstaban=0: significaría que
    // el legacy cambió a "Por cobrar" pero ninguna línea quedó en 'completado'.
    // Pasa cuando el localizador encontró filas pero todas estaban cobrado/anulado
    // (ticket ya liquidado, o referencia reciclada). No es un éxito: es una señal.
    if (marcadas + yaEstaban === 0) {
      Logger.log('[marcarLineasPorCobrarPorTicket] ⛔ INVARIANTE ROTA · ticket=' + ticketId
        + ' codigo=' + codigo + ' · encontradas=' + loc.filas.length
        + ' pero ninguna quedó en completado (ignoradas=' + ignoradas + ')');
      return {
        ok: false, motivo: 'sin_linea_sincronizable',
        ticketId: ticketId, codigo: codigo, modo: loc.modo,
        encontradas: loc.filas.length, marcadas: 0, yaEstaban: 0,
        ignoradas: ignoradas, detalle: detalle
      };
    }

    return {
      ok: true, ticketId: ticketId, codigo: codigo, modo: loc.modo,
      encontradas: loc.filas.length, marcadas: marcadas,
      yaEstaban: yaEstaban, ignoradas: ignoradas, detalle: detalle
    };
  } catch (e) {
    Logger.log('[marcarLineasPorCobrarPorTicket] ⛔ ' + e);
    return { ok: false, motivo: String(e), ticketId: ticketId, codigo: codigo };
  }
}

// asignarPromo → reescribe servicio y montos de la línea activa de la clienta.
// Mapa de campos explícito: SOLO los que asignarPromo cambia de verdad en legacy.
// NUNCA toca promo_ref/ticket_ref (se conservan) ni una línea cobrada/anulada.
// opts.dryRun = true → solo verifica que exista una línea editable. No escribe.
function actualizarLineaPromoAsignada(ticketId, codigo, cambios, opts) {
  try {
    opts = opts || {};
    var dry = opts.dryRun === true;
    var ws = _hojaLineas();
    var d  = ws.getDataRange().getValues();
    var loc = _filasDeTicketLineas(d, ticketId, codigo);

    // Solo líneas todavía editables
    var editables = loc.filas.filter(function (f) {
      var e = String(d[f][LX.estado]);
      return e === 'esperando' || e === 'en_servicio';
    });
    if (!editables.length) {
      Logger.log('[actualizarLineaPromoAsignada]' + (dry ? ' (dryRun)' : '')
        + ' ⛔ sin línea editable · ticket=' + ticketId + ' codigo=' + codigo
        + ' (encontradas=' + loc.filas.length + ')');
      return { ok: false, motivo: loc.filas.length ? 'sin_linea_editable' : 'sin_linea',
               ticketId: ticketId, codigo: codigo, encontradas: loc.filas.length, dryRun: dry };
    }
    if (dry) return { ok: true, dryRun: true, id: String(d[editables[0]][LX.id]), modo: loc.modo, encontradas: editables.length };
    // asignarPromo actúa sobre el ticket principal de la clienta: una sola línea.
    if (editables.length > 1) {
      Logger.log('[actualizarLineaPromoAsignada] ⚠ ' + editables.length + ' líneas activas para codigo=' + codigo
        + ' · se actualiza la primera (id=' + d[editables[0]][LX.id] + ')');
    }

    var fila = editables[0];
    var id   = String(d[fila][LX.id]);
    var antes = {
      servicio: String(d[fila][LX.servicio] || ''),
      monto: Number(d[fila][LX.monto] || 0),
      montoRegular: Number(d[fila][LX.montoRegular] || 0),
      esPromo: String(d[fila][LX.esPromo] || ''),
      staff: String(d[fila][LX.staff] || ''),
      promoRef: String(d[fila][LX.promoRef] || '')
    };

    // actualizarLinea() ya rechaza líneas cobradas y filtra campos no editables.
    // NO se pasa promoRef → se conserva (y con él ticket_ref y slot).
    var r = actualizarLinea(id, cambios);
    if (!r || r.success !== true) {
      Logger.log('[actualizarLineaPromoAsignada] ⛔ actualizarLinea falló: ' + JSON.stringify(r));
      return { ok: false, motivo: (r && r.message) || 'actualizarLinea_fallo', id: id };
    }

    // Verificación de estado final: releer la fila, no confiar en el retorno.
    var d2 = ws.getDataRange().getValues();
    var despues = {
      servicio: String(d2[fila][LX.servicio] || ''),
      monto: Number(d2[fila][LX.monto] || 0),
      montoRegular: Number(d2[fila][LX.montoRegular] || 0),
      esPromo: String(d2[fila][LX.esPromo] || ''),
      staff: String(d2[fila][LX.staff] || ''),
      promoRef: String(d2[fila][LX.promoRef] || '')
    };
    if (despues.promoRef !== antes.promoRef) {
      Logger.log('[actualizarLineaPromoAsignada] ⛔ promo_ref cambió (' + antes.promoRef + ' → ' + despues.promoRef + ')');
      return { ok: false, motivo: 'promoRef_perdido', id: id, antes: antes, despues: despues };
    }
    if (cambios.servicio !== undefined && despues.servicio !== String(cambios.servicio)) {
      return { ok: false, motivo: 'servicio_no_aplicado', id: id, antes: antes, despues: despues };
    }
    if (cambios.monto !== undefined && despues.monto !== Number(cambios.monto)) {
      return { ok: false, motivo: 'monto_no_aplicado', id: id, antes: antes, despues: despues };
    }

    Logger.log('[actualizarLineaPromoAsignada] ✅ id=' + id + ' modo=' + loc.modo
      + ' antes=' + JSON.stringify(antes) + ' despues=' + JSON.stringify(despues));
    return { ok: true, id: id, modo: loc.modo, antes: antes, despues: despues };
  } catch (e) {
    Logger.log('[actualizarLineaPromoAsignada] ⛔ ' + e);
    return { ok: false, motivo: String(e), ticketId: ticketId, codigo: codigo };
  }
}

// LIMPIEZA (correr una vez): cierra las líneas 'en_servicio' que quedaron pegadas
// aunque el servicio YA terminó — es decir, que tienen un gemelo (mismo código +
// mismo servicio) HOY en estado 'completado' o 'cobrado'. Destraba a las clientas
// que hoy siguen apareciendo en "Atendiendo ahora". Seguro: solo toca duplicados
// de servicios ya finalizados.
function cerrarDuplicadasEnServicio() {
  var ws = _hojaLineas();
  var d = ws.getDataRange().getValues();
  var terminados = {};
  for (var i = 1; i < d.length; i++) {
    if (!_esHoy(d[i][LX.fecha])) continue;
    var e = String(d[i][LX.estado]);
    if (e === 'completado' || e === 'cobrado') terminados[String(d[i][LX.codigo]) + '|' + String(d[i][LX.servicio])] = true;
  }
  var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');
  var cerradas = [];
  for (var j = 1; j < d.length; j++) {
    if (!_esHoy(d[j][LX.fecha])) continue;
    if (String(d[j][LX.estado]) !== 'en_servicio') continue;
    if (String(d[j][LX.promoRef] || '').trim()) continue;   // solo huérfanos (sin ref propia)
    var key = String(d[j][LX.codigo]) + '|' + String(d[j][LX.servicio]);
    if (!terminados[key]) continue;
    ws.getRange(j + 1, LX.estado + 1).setValue('completado');
    if (!String(d[j][LX.horaDevuelta] || '').trim()) ws.getRange(j + 1, LX.horaDevuelta + 1).setValue(stamp);
    ws.getRange(j + 1, LX.obs + 1).setValue(String(d[j][LX.obs] || '') + ' · [dup cerrado - limpieza]');
    ws.getRange(j + 1, LX.actualizada + 1).setValue(stamp);
    cerradas.push(String(d[j][LX.id]) + ' · ' + String(d[j][LX.codigo]) + ' · ' + String(d[j][LX.servicio]));
  }
  Logger.log('[cerrarDuplicadasEnServicio] cerradas: ' + cerradas.length);
  cerradas.forEach(function (c) { Logger.log('  ✅ ' + c); });
  return { cerradas: cerradas };
}

// ── ESPEJO DEL TICKETMULTI → N líneas (paso 2b: combos como ticket único en Lineas) ──
// El TM es 1 fila con hasta 4 slots; acá creamos 1 línea por slot, todas con la misma
// visita (código de la clienta), y cada una con promoRef = "TM-XXXX:slot" para
// identificar el subticket exacto en tomar/completar/cobrar. obs '[paralelo TM]'.
function lineasDesdeTicketMulti(data, id, areas) {
  try {
    if (!Array.isArray(areas) || areas.length === 0) return { ok: false, motivo: 'sin areas' };
    // AM-1R-1 — `visita` = TM MADRE (id), no "clienta + día". Dos TM de la
    // misma clienta el mismo día compartían visita; ahora cada uno tiene
    // identidad propia. Se usa la MADRE (TM-XXXX), nunca el componente
    // promoRef (TM-XXXX:slot).
    var visita = String(id || '').trim() || visitaDelDia(data.codigo);
    var creadas = 0;
    for (var i = 0; i < areas.length; i++) {
      var a = areas[i];
      var _slotNum = i + 1;  // base 1: slot 1, 2, 3, 4
      var _refTM = String(id) + ':' + _slotNum;
      // dedup: si ya hay línea activa de este slot del TM, no duplicar
      if (_lineaActivaPorRef(_refTM, data.codigo)) continue;
      var esPromo = (a.tipo === 'promo');
      // FIX SLOT-STAFF: la staff asignada al crear va a TODOS los slots de SU área
      // (lista calculada en handleCrearTicketMulti), no solo al primero. Sin esto,
      // los slots extra de su área quedaban sin staff y no los veía en su panel.
      var _slotsAsig = Array.isArray(data._slotsAsignada) ? data._slotsAsignada
                     : (typeof data._slotAsignada === 'number' ? [data._slotAsignada] : [0]);
      var staff = (_slotsAsig.indexOf(i) !== -1 && data.asignadaA) ? String(data.asignadaA).trim() : '';
      crearLinea({
        visita:       visita,
        codigo:       data.codigo || '',
        cliente:      data.nombre || '',
        staff:        staff,
        area:         a.area || '',
        servicio:     a.tentativo || '',
        esPromo:      esPromo,
        promoRef:     _refTM,          // ref de ORIGEN por slot del TM (base 1)
        ticketRef:    String(id),      // TICKET MADRE explícito: NO se deriva de promo_ref.
                                       // Garantiza que todas las líneas (normal, promo,
                                       // subservicios) compartan el mismo ticket madre
                                       // aunque su promo_ref difiera.
        slot:         _slotNum,        // secuencia dentro del ticket (crearLinea lee data.slot)
        monto:        Number(a.precio || 0),
        montoRegular: Number(a.precioNormal || a.precio || 0),
        // MODELO "Espera por staff" (gateado por ESPERA_POR_STAFF): asignar NO es
        // empezar. Con el interruptor ON nace 'esperando' (= "Espera por staff") y
        // pasa a 'en_servicio' cuando la staff confirma. Con OFF, comportamiento
        // anterior (asignar = en_servicio de una).
        estado:       ESPERA_POR_STAFF ? 'esperando' : (staff ? 'en_servicio' : 'esperando'),
        obs:          '[paralelo TM] ' + (data.observaciones || '')
      });
      creadas++;
    }
    return { ok: true, creadas: creadas, visita: visita };
  } catch (e) {
    return { ok: false, motivo: String(e) };
  }
}

// Cobro del TM → cierra TODAS las líneas del ticket (promoRef "TM-XXXX:*") como 'cobrado'.
// liquidacion (OPCIONAL, INC-MIXTO-COMISION): objeto { [idLinea]: comisionYaCalculadaPorBilling }.
// Si no se entrega, o si una línea concreta no tiene entrada en el mapa, se conserva
// EXACTAMENTE el comportamiento legacy (_comisionLinea()) — sin regresión, sin cambio
// de fórmula. La llamada histórica marcarLineasPorTicketMulti(idTM, metodoPago) sigue
// funcionando idéntica: liquidacion queda undefined → todas las líneas usan legacy.
function marcarLineasPorTicketMulti(idTM, metodoPago, liquidacion) {
  try {
    if (!idTM) return { ok: false, motivo: 'sin idTM' };
    var ws = _hojaLineas();
    var d = ws.getDataRange().getValues();
    var activos = ['esperando', 'en_servicio', 'completado'];
    var prefijo = String(idTM) + ':';   // match por promoRef (TM-XXXX:N)
    var stamp = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy HH:mm:ss');
    var marcadas = 0;
    var usoBillingCount = 0;
    for (var i = 1; i < d.length; i++) {
      // Match 1: promoRef empieza con "TM-XXXX:" (líneas creadas vía lineasDesdeTicketMulti)
      // Match 2: ticket_ref === idTM (líneas de cola asignadas que heredaron el ticket_ref del TM)
      var porPromoRef  = String(d[i][LX.promoRef]  || '').indexOf(prefijo) === 0;
      var porTicketRef = String(d[i][LX.ticketRef] || '') === String(idTM);
      if (!porPromoRef && !porTicketRef) continue;
      if (activos.indexOf(String(d[i][LX.estado])) === -1) continue;

      // Comisión: si Billing ya la calculó para ESTA línea (match por id, nunca por
      // nombre/orden), usar ese valor tal cual — NO recalcular. Si no hay liquidación,
      // o esta línea puntual no aparece en ella, fallback a _comisionLinea() (legacy).
      var _idLinea = String(d[i][LX.id] || '');
      var _comisionFinal;
      if (liquidacion && Object.prototype.hasOwnProperty.call(liquidacion, _idLinea)
          && typeof liquidacion[_idLinea] === 'number') {
        _comisionFinal = liquidacion[_idLinea];
        usoBillingCount++;
      } else {
        _comisionFinal = _comisionLinea(d[i][LX.area], d[i][LX.monto], d[i][LX.montoRegular], metodoPago);
      }

      ws.getRange(i + 1, LX.estado     + 1).setValue('cobrado');
      ws.getRange(i + 1, LX.metodoPago + 1).setValue(metodoPago || '');
      ws.getRange(i + 1, LX.comision   + 1).setValue(_comisionFinal);
      ws.getRange(i + 1, LX.actualizada + 1).setValue(stamp);
      marcadas++;
    }
    return { ok: true, marcadas: marcadas, usoBilling: usoBillingCount };
  } catch (e) {
    return { ok: false, motivo: String(e) };
  }
}

// ── MIGRACIÓN FECHA — correr UNA vez para corregir filas con fecha como objeto Date ──
// Convierte todas las celdas de la columna fecha que sean Date a string 'dd/MM/yyyy'
function migrarFechasLineas() {
  var ws = _hojaLineas();
  var nFilas = ws.getLastRow();
  if (nFilas < 2) return { ok: true, corregidas: 0 };

  // Forzar formato texto en toda la columna fecha (col LX.fecha + 1)
  var colFecha = LX.fecha + 1;
  var rango = ws.getRange(2, colFecha, nFilas - 1, 1);
  var vals = rango.getValues();
  var corregidas = 0;

  for (var i = 0; i < vals.length; i++) {
    var v = vals[i][0];
    if (v instanceof Date) {
      vals[i][0] = Utilities.formatDate(v, LINEAS_TZ, 'dd/MM/yyyy');
      corregidas++;
    }
  }

  rango.setNumberFormat('@STRING@');
  rango.setValues(vals);

  // También forzar formato texto en filas futuras (toda la columna)
  ws.getRange(1, colFecha, ws.getMaxRows(), 1).setNumberFormat('@STRING@');

  Logger.log('migrarFechasLineas: ' + corregidas + ' fechas corregidas de ' + (nFilas - 1) + ' filas');
  return { ok: true, corregidas: corregidas, totalFilas: nFilas - 1 };
}

// ── DIAGNÓSTICO — correr desde el editor para ver por qué los espejos fallan ──
function diagnosticarLineas() {
  var resultado = { pasos: [] };

  // 1. ¿Existe la hoja Lineas?
  try {
    var ws = _hojaLineas();
    var nFilas = ws.getLastRow();
    resultado.pasos.push('✅ Hoja Lineas existe. Filas: ' + nFilas);
    
    // 2. ¿Qué hay en ella?
    if (nFilas > 1) {
      var primeras = ws.getRange(2, 1, Math.min(3, nFilas - 1), LINEAS_HEADERS.length).getValues();
      primeras.forEach(function(r, i) {
        resultado.pasos.push('Fila ' + (i+2) + ': id=' + r[LX.id] + ' fecha=' + r[LX.fecha] + ' estado=' + r[LX.estado] + ' cliente=' + r[LX.cliente]);
      });
    } else {
      resultado.pasos.push('⚠️ La hoja está vacía — los espejos no están escribiendo');
    }

    // 3. Intentar escribir una línea de prueba
    try {
      var test = crearLinea({
        visita: 'V-TEST-' + new Date().getTime(),
        codigo: 'C-TEST',
        cliente: 'TEST DIAGNÓSTICO',
        staff: 'Test',
        area: 'cejas',
        servicio: 'Test diagnóstico',
        esPromo: false,
        monto: 1,
        montoRegular: 1,
        estado: 'esperando',
        obs: 'TEST — eliminar'
      });
      resultado.pasos.push('✅ crearLinea funcionó: ' + JSON.stringify(test));
    } catch(eC) {
      resultado.pasos.push('❌ crearLinea FALLÓ: ' + String(eC));
    }

    // 4. ¿lineaDesdeAsignacion puede leer ListaEspera?
    try {
      var wsLE = getSheet('ListaEspera');
      var dLE = wsLE.getDataRange().getValues();
      var primeraReal = null;
      for (var i = 3; i < dLE.length; i++) {
        if (String(dLE[i][0]).indexOf('LE-') === 0) { primeraReal = dLE[i]; break; }
      }
      if (primeraReal) {
        resultado.pasos.push('✅ ListaEspera tiene datos. Primera fila real: código=' + primeraReal[3] + ' cliente=' + primeraReal[4] + ' staff=' + primeraReal[9]);
        // Intentar espejo con esa fila
        try {
          var rEsp = lineaDesdeAsignacion(primeraReal, 'DIAG');
          resultado.pasos.push('✅ lineaDesdeAsignacion OK: ' + JSON.stringify(rEsp));
        } catch(eA) {
          resultado.pasos.push('❌ lineaDesdeAsignacion FALLÓ: ' + String(eA));
        }
      } else {
        resultado.pasos.push('⚠️ ListaEspera no tiene filas LE-');
      }
    } catch(eLE) {
      resultado.pasos.push('❌ No pude leer ListaEspera: ' + String(eLE));
    }

  } catch(eH) {
    resultado.pasos.push('❌ _hojaLineas() FALLÓ: ' + String(eH));
  }

  Logger.log('DIAGNÓSTICO LINEAS:\n' + resultado.pasos.join('\n'));
  return resultado;
}

// ── DIAGNÓSTICO HOY — muestra qué líneas existen para la fecha de hoy ──
function diagnosticarLineasHoy() {
  var ws = _hojaLineas();
  var d = ws.getDataRange().getValues();
  var hoy = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy');
  var resumen = { hoy: hoy, totalFilas: d.length - 1, lineasHoy: [], estadosCounts: {} };

  for (var i = 1; i < d.length; i++) {
    var fechaVal = d[i][LX.fecha];
    var fechaStr = fechaVal instanceof Date
      ? Utilities.formatDate(fechaVal, LINEAS_TZ, 'dd/MM/yyyy')
      : String(fechaVal || '').trim();

    if (fechaStr !== hoy) continue;

    var estado = String(d[i][LX.estado] || '');
    resumen.estadosCounts[estado] = (resumen.estadosCounts[estado] || 0) + 1;
    resumen.lineasHoy.push({
      id: d[i][LX.id],
      cliente: d[i][LX.cliente],
      servicio: d[i][LX.servicio],
      estado: estado,
      staff: d[i][LX.staff],
      monto: d[i][LX.monto],
      ticketRef: d[i][LX.ticketRef],
      promoRef: d[i][LX.promoRef]
    });
  }

  Logger.log('DIAGNÓSTICO HOY (' + hoy + '): ' + JSON.stringify(resumen, null, 2));
  return resumen;
}

// ── LIMPIEZA — correr UNA vez para eliminar líneas de TEST ──
function limpiarLineasTest() {
  var ws = _hojaLineas();
  var d = ws.getDataRange().getValues();
  var eliminadas = 0;
  for (var i = d.length - 1; i >= 1; i--) {
    var cliente = String(d[i][LX.cliente] || '').toUpperCase();
    var obs = String(d[i][LX.obs] || '').toUpperCase();
    if (cliente.indexOf('TEST') >= 0 || obs.indexOf('TEST — ELIMINAR') >= 0) {
      ws.deleteRow(i + 1);
      eliminadas++;
    }
  }
  Logger.log('limpiarLineasTest: ' + eliminadas + ' filas eliminadas');
  return { ok: true, eliminadas: eliminadas };
}

// ── DIAGNÓSTICO DETALLADO — per el documento de auditoría ──────────────────
function diagnosticarAuditoria() {
  var log = [];
  var hoy = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy');
  log.push('=== fechaBuscada: ' + hoy + ' ===');

  // 1. Leer HistorialOwner
  var totalHO = 0, hoHoy = [];
  try {
    var wsHO = getSheet('HistorialOwner');
    var dHO  = wsHO.getDataRange().getValues();
    totalHO  = dHO.length - 1;
    log.push('totalFilasHistorialOwner: ' + totalHO);
    for (var h = 1; h < dHO.length; h++) {
      var fHO = dHO[h][0];
      var fechaHO = fHO instanceof Date
        ? Utilities.formatDate(fHO, LINEAS_TZ, 'dd/MM/yyyy')
        : String(fHO || '').trim();
      if (fechaHO === hoy) hoHoy.push({ fecha: fechaHO, codigo: dHO[h][2], cliente: dHO[h][3] });
    }
    log.push('registrosHistorialOwnerHoy: ' + hoHoy.length);
    if (hoHoy.length > 0) log.push('primerRegistroHO: ' + JSON.stringify(hoHoy[0]));
  } catch(e) { log.push('ERROR HistorialOwner: ' + e); }

  // 2. Leer Lineas
  var wsL, dL, totalL = 0;
  try {
    wsL  = _hojaLineas();
    dL   = wsL.getDataRange().getValues();
    totalL = dL.length - 1;
    log.push('\ntotalFilasLineas: ' + totalL);
    log.push('columnasDetectadasLineas (header fila1): ' + JSON.stringify(dL[0]));
  } catch(e) { log.push('ERROR _hojaLineas: ' + e); return Logger.log(log.join('|')); }

  // 3. Primeras 3 filas de datos con valor raw de fecha
  log.push('\n--- primeras 3 filas de Lineas (raw) ---');
  for (var p = 1; p <= Math.min(3, dL.length - 1); p++) {
    var fechaRaw = dL[p][LX.fecha];
    log.push('Fila ' + (p+1) + ': id=' + dL[p][LX.id]
      + ' | fechaRAW=' + JSON.stringify(fechaRaw)
      + ' | tipo=' + typeof fechaRaw
      + ' | esDate=' + (fechaRaw instanceof Date)
      + ' | _esHoy=' + _esHoy(fechaRaw)
      + ' | estado=' + dL[p][LX.estado]
      + ' | cliente=' + dL[p][LX.cliente]);
  }

  // 4. Recorrer TODAS las filas y reportar por qué se descarta cada una
  log.push('\n--- motivoPorElQueCadaFilaFueDescartada (primeras 20 descartes) ---');
  var filtradas = [], descartes = 0;
  for (var i = 1; i < dL.length; i++) {
    var estado  = String(dL[i][LX.estado] || '');
    var fechaV  = dL[i][LX.fecha];
    var esHoyV  = _esHoy(fechaV);
    var cobAnul = (estado === 'cobrado' || estado === 'anulado');

    var motivo = null;
    if (cobAnul)  motivo = 'estado=' + estado + ' (excluido)';
    else if (!esHoyV) motivo = 'fecha ' + JSON.stringify(fechaV) + ' != hoy';

    if (motivo) {
      if (descartes < 20) log.push('  Fila ' + (i+1) + ' [' + dL[i][LX.id] + '] ' + dL[i][LX.cliente] + ': ' + motivo);
      descartes++;
    } else {
      filtradas.push({
        id: dL[i][LX.id], cliente: dL[i][LX.cliente],
        estado: estado, codigo: dL[i][LX.codigo]
      });
    }
  }
  log.push('registrosLineasFiltradosPorFecha (pasan el filtro): ' + filtradas.length);
  log.push('registrosDescartados: ' + descartes);
  filtradas.forEach(function(f){ log.push('  PASA: ' + JSON.stringify(f)); });

  // 5. getPorCobrar legacy — qué clave usa para el código
  log.push('\n--- handleGetPorCobrar (legacy) ---');
  try {
    var legRes = handleGetPorCobrar();
    log.push('porCobrar legacy count: ' + (legRes.porCobrar || []).length);
    (legRes.porCobrar || []).slice(0, 3).forEach(function(x){
      log.push('  legacy item: codigo=' + x.codigo + ' nombre=' + x.nombre + ' total=' + x.total + ' estado=' + x.estado);
    });
  } catch(e) { log.push('ERROR handleGetPorCobrar: ' + e); }

  // 6. getPorCobrarDesdeLineas — resultado
  log.push('\n--- getPorCobrarDesdeLineas ---');
  try {
    var lRes = getPorCobrarDesdeLineas({ soloHoy: true });
    log.push('porCobrar Lineas count: ' + lRes.total);
    (lRes.porCobrar || []).slice(0, 3).forEach(function(x){
      log.push('  lineas item: codigo=' + x.codigo + ' nombre=' + x.nombre + ' total=' + x.total);
    });
  } catch(e) { log.push('ERROR getPorCobrarDesdeLineas: ' + e); }

  Logger.log(log.join('\\n'));
  return { log: log };
}

// ── DIAGNÓSTICO LEGACY — ver qué exactamente devuelve handleGetPorCobrar ──
function diagnosticarLegacy() {
  var actual = (typeof handleGetPorCobrar === 'function') ? handleGetPorCobrar() : { porCobrar: [] };
  var hoy = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy');
  var log = ['handleGetPorCobrar count: ' + (actual.porCobrar || []).length];
  
  (actual.porCobrar || []).forEach(function(x, i) {
    log.push('Item ' + i + ': codigo=' + x.codigo 
      + ' | nombre=' + x.nombre 
      + ' | idEspera=' + x.idEspera
      + ' | total=' + x.total
      + ' | servicio=' + x.servicio
      + ' | tomadaPor=' + x.tomadaPor);
  });

  // También ver las 7 claves del aMap
  function idxPorCodigo(lista) {
    var m = {};
    (lista || []).forEach(function(it) {
      var c = String(it.codigo || '').trim(); if (!c) return;
      if (!m[c]) m[c] = { codigo: c, nombre: it.nombre || '', total: 0 };
      m[c].total += Number(it.total || 0);
    });
    return m;
  }
  var aMap = idxPorCodigo(actual.porCobrar);
  log.push('\nClaves codigo en legacy: ' + JSON.stringify(Object.keys(aMap)));

  var lineas = getPorCobrarDesdeLineas({ soloHoy: true });
  var lMap = idxPorCodigo(lineas.porCobrar);
  log.push('Claves codigo en Lineas: ' + JSON.stringify(Object.keys(lMap)));

  Logger.log(log.join('\\n'));
  return { log: log };
}

// ── VERIFICACIÓN PASO 4 — correr después de cobros para confirmar fuente ──
function verificarCobrosDesdLineas() {
  var hoy = Utilities.formatDate(new Date(), LINEAS_TZ, 'dd/MM/yyyy');
  var ws  = _hojaLineas();
  var d   = ws.getDataRange().getValues();
  var log = ['VERIFICACION COBROS HOY (' + hoy + ')'];

  var porTicket = {};
  for (var i = 1; i < d.length; i++) {
    if (!_esHoy(d[i][LX.fecha])) continue;
    if (String(d[i][LX.estado]) !== 'cobrado') continue;
    var ref  = String(d[i][LX.ticketRef] || d[i][LX.promoRef] || '').trim();
    var tmId = ref.split(':')[0];
    if (!tmId) continue;
    if (!porTicket[tmId]) porTicket[tmId] = [];
    porTicket[tmId].push({
      id: d[i][LX.id], cliente: d[i][LX.cliente], staff: d[i][LX.staff],
      area: d[i][LX.area], servicio: d[i][LX.servicio],
      monto: d[i][LX.monto], montoRegular: d[i][LX.montoRegular],
      comision: d[i][LX.comision], metodoPago: d[i][LX.metodoPago]
    });
  }

  var tickets = Object.keys(porTicket);
  log.push('Tickets cobrados hoy en Lineas: ' + tickets.length);

  tickets.forEach(function(tmId) {
    var lineas = porTicket[tmId];
    var totalMonto    = lineas.reduce(function(s,l){ return s + Number(l.monto||0); }, 0);
    var totalComision = lineas.reduce(function(s,l){ return s + Number(l.comision||0); }, 0);
    log.push(tmId + ' - ' + lineas[0].cliente + ' - total:' + totalMonto + ' comision:' + totalComision);
    lineas.forEach(function(l) {
      var alerta = (Number(l.comision) <= 0 ? ' SIN_COMISION' : '') + (Number(l.montoRegular) <= 0 ? ' SIN_REGULAR' : '');
      log.push('  ' + l.staff + ' area:' + l.area + ' monto:' + l.monto + ' regular:' + l.montoRegular + ' comision:' + l.comision + ' pago:' + l.metodoPago + (alerta || ' OK'));
    });
  });

  if (tickets.length === 0) {
    log.push('AVISO: cero cobros en Lineas hoy. Los cobros usaron fuente=legacy.');
    log.push('Revisa Ejecuciones en Apps Script y busca [CobroTM] fuente=...');
  }

  Logger.log(log.join(' | '));
  return { tickets: tickets.length, detalle: porTicket };
}

// ── MIGRACIÓN SLOTS BASE 0 → BASE 1 — correr UNA vez ──────────────────────
// Lee el número del promoRef (TM-xxx:N) y actualiza:
//   promoRef TM-xxx:0 → TM-xxx:1, slot: 1
//   promoRef TM-xxx:1 → TM-xxx:2, slot: 2
//   etc.
// Idempotente: si el promoRef ya tiene base >= 1 y el slot ya está bien, no toca nada.
function migrarSlotsBase1() {
  var ws = _hojaLineas();
  var d  = ws.getDataRange().getValues();
  var migradas = 0, yaCorrectas = 0;

  for (var i = 1; i < d.length; i++) {
    var pRef = String(d[i][LX.promoRef] || '').trim();
    var m = pRef.match(/^(TM-[^:]+):(\d+)$/);
    if (!m) continue;  // no es TM con slot

    var slotEnRef  = Number(m[2]);
    var slotActual = Number(d[i][LX.slot] || 0);

    // Si el promoRef ya dice :1 o :2 Y el slot ya coincide → ya está correcto
    if (slotEnRef >= 1 && slotActual === slotEnRef) { yaCorrectas++; continue; }

    // Si el promoRef dice :0, :1, etc. → convertir a base 1
    var nuevoSlot = slotEnRef + 1;
    var nuevoRef  = m[1] + ':' + nuevoSlot;

    ws.getRange(i + 1, LX.promoRef + 1).setValue(nuevoRef);
    ws.getRange(i + 1, LX.slot     + 1).setValue(nuevoSlot);
    migradas++;
  }

  var msg = 'migrarSlotsBase1: migradas=' + migradas + ' ya_correctas=' + yaCorrectas;
  Logger.log(msg);
  return { ok: true, migradas: migradas, yaCorrectas: yaCorrectas };
}

// ── DIAGNÓSTICO SLOTS — ver estado actual ──────────────────────────────────
function diagnosticarSlots() {
  var ws = _hojaLineas();
  var d  = ws.getDataRange().getValues();
  var log = [];
  for (var i = 1; i < d.length; i++) {
    var pRef = String(d[i][LX.promoRef] || '').trim();
    if (!pRef.match(/^TM-/)) continue;
    log.push('Fila ' + (i+1) + ': promoRef=' + pRef + ' slot=' + d[i][LX.slot] + ' estado=' + d[i][LX.estado] + ' staff=' + d[i][LX.staff]);
  }
  Logger.log(log.slice(0, 30).join('\n'));
  return log.length;
}

// ── CORRECCIÓN FINAL SLOTS — limpia #NUM! y sincroniza slot con promoRef ────
function corregirSlotsDesdePromoRef() {
  var ws = _hojaLineas();
  var lastRow = ws.getLastRow();
  if (lastRow < 2) return { ok: true, corregidas: 0 };

  // Leer promoRef (col L = LX.promoRef+1) y slot (col X = LX.slot+1) de todas las filas
  var colPromo = ws.getRange(2, LX.promoRef + 1, lastRow - 1, 1).getValues();
  var colSlot  = ws.getRange(2, LX.slot     + 1, lastRow - 1, 1);
  var vSlot    = colSlot.getValues();

  var corregidas = 0, yaOk = 0, sinTM = 0;

  for (var i = 0; i < colPromo.length; i++) {
    var pRef = String(colPromo[i][0] || '').trim();
    var m = pRef.match(/^TM-[^:]+:(\d+)$/);
    if (!m) { sinTM++; continue; }

    var slotCorrecto = parseInt(m[1], 10);  // parseInt es más robusto que Number()
    var slotActual   = vSlot[i][0];

    // Corregir si: es #NUM!, vacío, NaN, o no coincide con promoRef
    var necesitaCorreccion = (
      typeof slotActual !== 'number' ||
      isNaN(slotActual) ||
      slotActual !== slotCorrecto
    );

    if (necesitaCorreccion) {
      vSlot[i][0] = slotCorrecto;
      corregidas++;
    } else {
      yaOk++;
    }
  }

  // Escribir de golpe (1 sola llamada al API)
  colSlot.setValues(vSlot);
  colSlot.setNumberFormat('0');  // forzar formato número entero

  var msg = 'corregirSlotsDesdePromoRef: corregidas=' + corregidas + ' ya_ok=' + yaOk + ' sin_TM=' + sinTM;
  Logger.log(msg);
  return { ok: true, corregidas: corregidas, yaOk: yaOk };
}

// ── VER PROMOREF RAW de filas TM recientes ────────────────────────────────
function verPromoRefRaw() {
  var ws = _hojaLineas();
  var lastRow = ws.getLastRow();
  // Leer las últimas 30 filas
  var desde = Math.max(2, lastRow - 30);
  var datos = ws.getRange(desde, LX.promoRef + 1, lastRow - desde + 1, 2).getValues();
  var log = [];
  for (var i = 0; i < datos.length; i++) {
    var pRef = datos[i][0];
    var slot = datos[i][1];
    if (String(pRef).indexOf('TM-') !== 0) continue;
    log.push('fila ' + (desde + i) + ': promoRef=[' + pRef + '] typeof=' + typeof pRef + ' slot=[' + slot + '] typeof=' + typeof slot);
  }
  Logger.log(log.join('\n'));
}

// ── RESET SLOT LIMPIO — escribe slot=N directamente desde promoRef=TM-xxx:N ──
function resetSlotDesdePromoRef() {
  var ws = _hojaLineas();
  var lastRow = ws.getLastRow();
  if (lastRow < 2) return;

  var rPromo = ws.getRange(2, LX.promoRef + 1, lastRow - 1, 1).getValues();
  var rSlot  = ws.getRange(2, LX.slot     + 1, lastRow - 1, 1);
  var vSlot  = rSlot.getValues();
  var fixes  = 0;

  for (var i = 0; i < rPromo.length; i++) {
    var pRef = String(rPromo[i][0] || '').trim();
    var m    = pRef.match(/^TM-[^:]+:(\d+)$/);
    if (m) {
      vSlot[i][0] = parseInt(m[1], 10);
      fixes++;
    } else {
      // No es TM — limpiar si tiene valor basura (número que parece monto)
      var v = vSlot[i][0];
      if (typeof v === 'number' && (v > 10 || v !== Math.floor(v))) {
        vSlot[i][0] = '';
      }
    }
  }

  rSlot.setNumberFormat('@STRING@');  // texto primero para evitar conversiones
  rSlot.setValues(vSlot);
  rSlot.setNumberFormat('0');         // luego número entero

  Logger.log('resetSlotDesdePromoRef: ' + fixes + ' filas TM actualizadas');
  return { ok: true, fixes: fixes };
}

// ── CORREGIR montoRegular de líneas con precio regular incorrecto ─────────
// Usar cuando un combo tenía regular mal configurado en Paquetes.
// Parámetros: tmId (ej: 'TM-0305'), montoRegularCorrecto por área [{area, montoRegular}]
// O usar sin parámetros para corregir el Combo 18 lifting de hoy.
function corregirMontoRegularLineas() {
  var ws = _hojaLineas();
  var d  = ws.getDataRange().getValues();
  var corregidas = 0;

  // Correcciones conocidas: { promoRef: montoRegular }
  // Combo 18 lifting: pestañas $23 promo → $30.19 regular, depilación $9 promo → $11.81 regular
  var CORRECCIONES = {
    // area: depilacion con monto promo ~9.14 → regular 11.81
    // area: pestañas con monto promo ~22.86 → regular 30.19
  };

  // Corrección genérica: para todas las líneas con servicio "Combo 18 lifting"
  // que tengan montoRegular === monto (es decir, sin precio regular diferente)
  for (var i = 1; i < d.length; i++) {
    var servicio = String(d[i][LX.servicio] || '');
    if (servicio !== 'Combo 18 lifting') continue;

    var monto        = Number(d[i][LX.monto]        || 0);
    var montoRegular = Number(d[i][LX.montoRegular] || 0);
    if (montoRegular !== monto) continue;  // ya tiene regular diferente, saltar

    // Calcular regular proporcional: total promo=32, total regular=42
    var totalPromo   = 32;
    var totalRegular = 42;
    var nuevoRegular = Math.round((monto / totalPromo) * totalRegular * 100) / 100;

    ws.getRange(i + 1, LX.montoRegular + 1).setValue(nuevoRegular);
    Logger.log('Corregido fila ' + (i+1) + ': ' + servicio + ' area=' + d[i][LX.area] + ' monto=' + monto + ' montoRegular=' + montoRegular + ' → ' + nuevoRegular);
    corregidas++;
  }

  Logger.log('corregirMontoRegularLineas: ' + corregidas + ' líneas corregidas');
  return { ok: true, corregidas: corregidas };
}

// ── Diagnóstico: listar líneas exactas de una clienta ────────────────────────
// Uso: diagnosticarLineasClienta('C-0024')
function diagnosticarLineasClienta(codigo) {
  var ws = _hojaLineas();
  var data = ws.getDataRange().getValues();
  var encontradas = 0;
  for (var i = 1; i < data.length; i++) {
    var cod    = String(data[i][LX.codigo]   || '').trim();
    var visita = String(data[i][LX.visita]   || '').trim();
    var svc    = String(data[i][LX.servicio] || '').trim();
    var estado = String(data[i][LX.estado]   || '').trim();
    var fecha  = String(data[i][LX.fecha]    || '').trim();
    var monto  = data[i][LX.monto];
    if (cod === codigo) {
      Logger.log('F' + (i+1) + ' | visita:[' + visita + '] | fecha:' + fecha + 
                 ' | estado:' + estado + ' | $' + monto + ' | svc:[' + svc + ']');
      encontradas++;
    }
  }
  Logger.log('Total líneas de ' + codigo + ': ' + encontradas);
}


// ── Anular línea huérfana manualmente ────────────────────────────────────────
// Uso: anularLineaPorVisitaYServicio('V-C-0024-20260707', 'Depilación de rostro completo con gillette')
function anularLineaPorVisitaYServicio(visitaId, servicio) {
  var ws = _hojaLineas();
  var data = ws.getDataRange().getValues();
  var anuladas = 0;
  for (var i = 1; i < data.length; i++) {
    var visita  = String(data[i][LX.visita]  || '').trim();
    var svc     = String(data[i][LX.servicio] || '').trim();
    var estado  = String(data[i][LX.estado]  || '').trim();
    if (visita === visitaId && svc === servicio && estado !== 'cobrado' && estado !== 'anulado') {
      ws.getRange(i + 1, LX.estado + 1).setValue('anulado');
      Logger.log('Anulada fila ' + (i+1) + ': ' + visita + ' | ' + svc);
      anuladas++;
    }
  }
  Logger.log('Total anuladas: ' + anuladas);
  return anuladas;
}

