    _chk('G. cierre no bloqueado', rG2.ticket_cierre_bloqueado===false);

    // ── H: reintento de finalización idempotente ─────────────────────────
    Logger.log('  ── H ──');
    var hdA=String(_lin(l2).horaDevuelta||'');
    var rH=_finalizarLineaNativaInterno_({ticketRef:refC,lineaId:l2,staff:'Laura'},wsLineas,wsTF,{});
    _chk('H. ok+idempotente', rH.ok&&rH.yaEstaba&&rH.idempotente&&rH.escritura===false,'e='+rH.error);
    _chk('H. hora_devuelta sin duplicar', String(_lin(l2).horaDevuelta||'')===hdA);
    _chk('H. TF estable', _estadoTF(refC)==='esperando_decision_mikaela');

    // ── I: nueva línea sobre ticket cerrado por decisión ─────────────────
    Logger.log('  ── I ──');
    var rI0=_crearLineaNativaInterno_({
      ticketRef:refC, codigo:'C-TEST', cliente:'Test 2N3', lineRequestId:RQID+'-C3',
      primeraLinea:{area:'pestanas',servicio:'Lifting',monto:35,montoRegular:35}
    },wsLineas,wsTF,_lnTfData_(wsTF),{});
