      _chk('M. resumen total_regular=20', rM.resumen.total_regular === 20, 't=' + rM.resumen.total_regular);
      _chk('M. resumen ahorro=6',         rM.resumen.ahorro === 6,         'a=' + rM.resumen.ahorro);
      _chk('M. estado_ticket reportado', rM.estado_ticket === 'en_atencion');
