function _tfTest2n5bParte2Interno_() {
  var H = _tfArnes2n5bInterno_('PARTE 2');
  var _chk=H.chk, _lin=H.lin, _estadoTF=H.estadoTF, _nFilas=H.nFilas, _reg=H.reg,
      _crearTicketDosLineas=H.crearTicketDosLineas;
  var wsLineas=H.wsLineas, wsTF=H.wsTF, REF=H.REF, RQID=H.RQID;
  var resultado = null;

  var refK = _reg(REF + '-K');
  var refL = _reg(REF + '-L');

  try {
    if (!H.listo) throw new Error('ARNES_NO_LISTO');

    // ── K: DESPUES_EJECUCION, un padre, herencia de horas ────────────────
    Logger.log('  ── K (DESPUES_EJECUCION, herencia de hora_toma/hora_devuelta) ──');
    var tK = _crearTicketDosLineas(refK, RQID + '-K', 'C-2N5B-K', 'Clienta K');
    _chk('K. ticket base creado', tK.ok === true, 'e=' + tK.error);
    if (tK.ok) {
      _iniciarLineaNativaInterno_({ ticketRef:refK, lineaId:tK.l1, staff:'Maria' }, wsLineas, wsTF, _lnOptsPuestosTest_());
      var finK1 = _finalizarLineaNativaInterno_({ ticketRef:refK, lineaId:tK.l1, staff:'Maria' },
                                                wsLineas, wsTF, _lnOptsPuestosTest_());
      _chk('K. l1 finalizada', finK1.ok === true, 'e=' + finK1.error);
      var finK2 = _finalizarLineaNativaInterno_({ ticketRef:refK, lineaId:tK.l2, staff:tK.staffL2 },
                                                wsLineas, wsTF, _lnOptsPuestosTest_());
      _chk('K. l2 finalizada', finK2.ok === true, 'e=' + finK2.error);
      _chk('K. TF esperando_decision_mikaela',
           _estadoTF(refK) === 'esperando_decision_mikaela', 'tf=' + _estadoTF(refK));

      var padreK1_antes = _lin(tK.l1);
      var solK = { ticketRef:refK, requestId:RQID + '-K1', promoCatalogoId:'PROMO-K',
                   momentoAplicacion:'DESPUES_EJECUCION',
                   componentes:[{ componenteId:'C1', lineaObjetivoId:tK.l1, area:'cejas',
                                  servicio:'CompK', staff:'Maria', precioPromo:12, precioRegular:20 }] };
      var rK = _aplicarPromoNativaInterno_(solK, wsLineas, wsTF, {});
      _chk('K. ok', rK.ok === true, 'e=' + rK.error + ' ' + JSON.stringify(rK.detalle_original || ''));
      if (rK.ok) {
        var compK = _lin(rK.lineas_creadas[0]);
        _chk('K. estado completado', compK.estado === 'completado', 'e=' + compK.estado);
        _chk('K. hora_toma heredada', H.cIg(compK.horaToma, padreK1_antes.horaToma),
             'c=' + compK.horaToma + ' p=' + padreK1_antes.horaToma);
        _chk('K. hora_devuelta heredada', H.cIg(compK.horaDevuelta, padreK1_antes.horaDevuelta),
             'c=' + compK.horaDevuelta + ' p=' + padreK1_antes.horaDevuelta);
        _chk('K. precio_aplicado vacío', String(compK.precioAplicado || '') === '');
        _chk('K. marcadores exactos',
             _ln5bVerificarMarcadoresComponenteInterno_(compK.obs).length === 0,
             JSON.stringify(_ln5bVerificarMarcadoresComponenteInterno_(compK.obs)));
        _chk('K. TF permanece esperando_decision_mikaela',
             _estadoTF(refK) === 'esperando_decision_mikaela', 'tf=' + _estadoTF(refK));
        _chk('K. tickets_fuente_intacto', rK.tickets_fuente_intacto === true);
        _chk('K. padre anulado con motivo correcto',
             _lin(tK.l1).estado === 'anulado' &&
             _lin(tK.l1).motivoAnulacion === 'PROMO_APLICADA:' + rK.grupo_promo_id);
        _chk('K. l2 (no objetivo) intacta', _lin(tK.l2).estado === 'completado');
      }
    }

    // ── L: dos padres distintos en el mismo plan (DESPUES_EJECUCION) ────
    Logger.log('  ── L (dos padres, DESPUES_EJECUCION) ──');
    var tL = _crearTicketDosLineas(refL, RQID + '-L', 'C-2N5B-L', 'Clienta L');
    _chk('L. ticket base creado', tL.ok === true, 'e=' + tL.error);
    if (tL.ok) {
      _iniciarLineaNativaInterno_({ ticketRef:refL, lineaId:tL.l1, staff:'Maria' }, wsLineas, wsTF, _lnOptsPuestosTest_());
      _finalizarLineaNativaInterno_({ ticketRef:refL, lineaId:tL.l1, staff:'Maria' }, wsLineas, wsTF, _lnOptsPuestosTest_());
      _finalizarLineaNativaInterno_({ ticketRef:refL, lineaId:tL.l2, staff:tL.staffL2 }, wsLineas, wsTF, _lnOptsPuestosTest_());
      _chk('L. TF esperando_decision_mikaela', _estadoTF(refL) === 'esperando_decision_mikaela');

      var solL = { ticketRef:refL, requestId:RQID + '-L1', promoCatalogoId:'PROMO-L',
                   momentoAplicacion:'DESPUES_EJECUCION',
                   componentes:[
                     { componenteId:'C1', lineaObjetivoId:tL.l1, area:'cejas',  servicio:'CompL1',
                       staff:'Maria', precioPromo:10, precioRegular:20 },
                     { componenteId:'C2', lineaObjetivoId:tL.l2, area:'facial', servicio:'CompL2',
                       staff:'Laura', precioPromo:6,  precioRegular:10 }
                   ] };
      var rL = _aplicarPromoNativaInterno_(solL, wsLineas, wsTF, {});
      _chk('L. ok', rL.ok === true, 'e=' + rL.error);
      if (rL.ok) {
        _chk('L. dos componentes creados', rL.lineas_creadas.length === 2);
        _chk('L. dos padres anulados', rL.lineas_anuladas.length === 2,
             'n=' + rL.lineas_anuladas.length);
        _chk('L. ambos padres realmente anulados',
             _lin(tL.l1).estado === 'anulado' && _lin(tL.l2).estado === 'anulado');
        _chk('L. resumen padres_unicos=2', rL.resumen.padres_unicos === 2);
        _chk('L. resumen total_promo=16', rL.resumen.total_promo === 16, 't=' + rL.resumen.total_promo);
        _chk('L. resumen ahorro=14', rL.resumen.ahorro === 14, 'a=' + rL.resumen.ahorro);
        _chk('L. TF permanece esperando_decision_mikaela', _estadoTF(refL) === 'esperando_decision_mikaela');
        _chk('L. tickets_fuente_intacto', rL.tickets_fuente_intacto === true);
      }
    }

  } catch (eMain) {
    Logger.log('  ❌ EXCEPCIÓN EN EL CUERPO: ' + eMain);
    H.errores.push('EXCEPCION_CUERPO: ' + eMain);
  } finally {
    resultado = H.cerrarParte();
  }
  return resultado;
}


