  try { return _tfTest2n5bParte3bInterno_(); }
  catch (e) { Logger.log('  ❌ EXCEPCIÓN: ' + e); return { ok:false, errores:['EXCEPCION: ' + e] }; }
  finally { lock.releaseLock(); }
