function _tfTest2n5bParte3cInterno_() {
  var H = _tfArnes2n5bInterno_('PARTE 3C');
  var _chk=H.chk, _lin=H.lin, _estadoTF=H.estadoTF, _nFilas=H.nFilas, _reg=H.reg,
      _crearTicketDosLineas=H.crearTicketDosLineas, _snap=H.snap;
  var wsLineas=H.wsLineas, wsTF=H.wsTF, REF=H.REF, RQID=H.RQID;
  var resultado = null;

  var refK1=_reg(REF+'-K1'), refK2=_reg(REF+'-K2');
  var refM1=_reg(REF+'-M1'), refM2=_reg(REF+'-M2'), refM3=_reg(REF+'-M3'),
      refM4=_reg(REF+'-M4'), refM5=_reg(REF+'-M5');

  // Comparación de atomicidad exacta: un snapshot tomado justo antes de UNA
  // operación concreta debe ser byte a byte idéntico al estado inmediatamente
  // después de que esa operación falle y se compense.
  function _chkAtomico(etiqueta, snapAntes) {
    var snapDespues = _snap();
    _chk(etiqueta + ' · mismo número de filas', snapDespues.filas === snapAntes.filas,
         'antes=' + snapAntes.filas + ' despues=' + snapDespues.filas);
    _chk(etiqueta + ' · LINEAS A–AE byte a byte idéntico', snapDespues.ln === snapAntes.ln);
    _chk(etiqueta + ' · TicketsFuente A–H byte a byte idéntico', snapDespues.tf === snapAntes.tf);
  }

  try {
    if (!H.listo) throw new Error('ARNES_NO_LISTO');

    // ── K1: excepción ambigua post-append (FIX 1) — la fila SÍ se creó ────
    Logger.log('  ── K1 (excepción ambigua post-append: resuelta por marcadores) ──');
    var tK1 = _crearTicketDosLineas(refK1, RQID + '-K1', 'C-2N5B-K1', 'Clienta K1');
    _chk('K1. ticket base creado', tK1.ok === true, 'e=' + tK1.error);
    if (tK1.ok) {
      var solK1 = { ticketRef:refK1, requestId:RQID + '-K1a', promoCatalogoId:'PROMO-K1',
                    momentoAplicacion:'ANTES_EJECUCION',
                    componentes:[{ componenteId:'CA', lineaObjetivoId:tK1.l1, area:'cejas',
                                   servicio:'A', staff:'Maria', precioPromo:5, precioRegular:20 }] };
      var snapK1 = _snap();
      var rK1 = _aplicarPromoNativaInterno_(solK1, wsLineas, wsTF,
                  { modoTest:true, hookExcepcionAmbiguaPostAppend:true });
      _chk('K1. → PROMO_COMPONENT_CREATE_EXCEPTION (resuelta, no asumida)',
           rK1.error === 'PROMO_COMPONENT_CREATE_EXCEPTION', 'e=' + rK1.error);
      _chk('K1. compensacion_componentes_ok', rK1.compensacion_componentes_ok === true);
      _chk('K1. compensacion_padres_ok',      rK1.compensacion_padres_ok === true);
      _chkAtomico('K1', snapK1);
      _chk('K1. padre sigue esperando', _lin(tK1.l1).estado === 'esperando');
      // Reintentar limpio: debe poder aplicarse normalmente después de la
      // compensación (nada quedó a medias que bloquee un intento nuevo).
      var rK1b = _aplicarPromoNativaInterno_(solK1, wsLineas, wsTF, {});
      _chk('K1. reintento limpio tras la compensación → ok', rK1b.ok === true, 'e=' + rK1b.error);
    }

    // ── K2: staff vacío en ANTES_EJECUCION, sin sustitución silenciosa ────
    Logger.log('  ── K2 (staff vacío, sin caer al staff del padre) ──');
    var tK2 = _crearTicketDosLineas(refK2, RQID + '-K2', 'C-2N5B-K2', 'Clienta K2');
    _chk('K2. ticket base creado', tK2.ok === true, 'e=' + tK2.error);
    if (tK2.ok) {
      var solK2 = { ticketRef:refK2, requestId:RQID + '-K2a', promoCatalogoId:'PROMO-K2',
                    momentoAplicacion:'ANTES_EJECUCION',
                    componentes:[{ componenteId:'CA', lineaObjetivoId:tK2.l1, area:'cejas',
                                   servicio:'A', staff:'', precioPromo:5, precioRegular:20 }] };
      var rK2 = _aplicarPromoNativaInterno_(solK2, wsLineas, wsTF, {});
      _chk('K2. ok', rK2.ok === true, 'e=' + rK2.error);
      if (rK2.ok) {
        var compK2 = _lin(rK2.lineas_creadas[0]);
        _chk('K2. staff del componente vacío (sin heredar del padre)',
             String(compK2.staff || '') === '', 's=' + compK2.staff);
      }
      var nAntesK2 = _nFilas();
      var rK2b = _aplicarPromoNativaInterno_(solK2, wsLineas, wsTF, {});
      _chk('K2. reintento exacto idempotente', rK2b.ok === true && rK2b.idempotente === true, 'e=' + rK2b.error);
      _chk('K2. cero filas nuevas en el reintento', _nFilas() === nAntesK2);
    }

    // ── M1–M5: alteración directa de cada marcador, uno por uno (FIX 3) ──
    Logger.log('  ── M1–M5 (valor de marcador alterado, uno por uno) ──');
    function _casoMarcadorAlterado(etiqueta, refTk, prefix, errorEsperado) {
      var t = _crearTicketDosLineas(refTk, RQID + '-' + etiqueta, 'C-2N5B-' + etiqueta, 'Clienta ' + etiqueta);
      _chk(etiqueta + '. ticket base creado', t.ok === true, 'e=' + t.error);
      if (!t.ok) return;
      var sol = { ticketRef:refTk, requestId:RQID + '-' + etiqueta + 'a', promoCatalogoId:'PROMO-' + etiqueta,
                  momentoAplicacion:'ANTES_EJECUCION',
                  componentes:[{ componenteId:'CA', lineaObjetivoId:t.l1, area:'cejas',
                                 servicio:'A', staff:'Maria', precioPromo:5, precioRegular:20 }] };
      var r1 = _aplicarPromoNativaInterno_(sol, wsLineas, wsTF, {});
      _chk(etiqueta + '. aplicación inicial ok', r1.ok === true, 'e=' + r1.error);
      if (!r1.ok) return;
      var hit = getLineaPorId(r1.lineas_creadas[0]);
      var obsOriginal = hit.linea.obs;
      var valorFalso = prefix === LN_LINE_FINGERPRINT_PREFIX || prefix === LN_PROMO_COMPONENT_FP_PREFIX ||
                        prefix === LN_PROMO_REQUEST_FP_PREFIX
                        ? 'fp-alterado-0000000000000000000000000000'
                        : (prefix === LN_LINE_REQUEST_ID_PREFIX ? 'PRM-alterado000000000000000000000000000000' : 'OTRO-VALOR');
      var obsAlterado = _lnEliminarMarcador_(obsOriginal, prefix) + ' ' + prefix + valorFalso + ']';
      wsLineas.getRange(hit.fila, LX.obs + 1).setValue(obsAlterado);

      // CORRECCIÓN 3: la fotografía se toma DESPUÉS de la alteración
      // intencional y ANTES del reintento — es contra ESE estado (ya
      // corrompido a propósito) que el reintento debe demostrar cero
      // escritura, no contra el estado previo a la corrupción.
      var snapTrasAlterar = _snap();

      var r2 = _aplicarPromoNativaInterno_(sol, wsLineas, wsTF, {});
      // M1, M2, M3 y M5 → PROMO_APPLICATION_INCOMPLETE. M4 (fingerprint de
      // solicitud) → REQUEST_ID_CONFLICT. Códigos exactos, sin OR entre ambos.
      _chk(etiqueta + '. error exacto ' + errorEsperado, r2.error === errorEsperado, 'e=' + r2.error);

      var snapDespuesReintento = _snap();
      _chk(etiqueta + '. cero escritura: mismo número de filas',
           snapDespuesReintento.filas === snapTrasAlterar.filas,
           'antes=' + snapTrasAlterar.filas + ' despues=' + snapDespuesReintento.filas);
      _chk(etiqueta + '. cero escritura: LINEAS A–AE idéntico al estado alterado',
           snapDespuesReintento.ln === snapTrasAlterar.ln);
      _chk(etiqueta + '. cero escritura: TicketsFuente A–H idéntico al estado alterado',
           snapDespuesReintento.tf === snapTrasAlterar.tf);

      wsLineas.getRange(hit.fila, LX.obs + 1).setValue(obsOriginal);   // restaurar para el cierre limpio
    }
    _casoMarcadorAlterado('M1', refM1, LN_LINE_REQUEST_ID_PREFIX,    'PROMO_APPLICATION_INCOMPLETE');
    _casoMarcadorAlterado('M2', refM2, LN_LINE_FINGERPRINT_PREFIX,  'PROMO_APPLICATION_INCOMPLETE');
    _casoMarcadorAlterado('M3', refM3, LN_PROMO_REQUEST_ID_PREFIX,  'PROMO_APPLICATION_INCOMPLETE');
    _casoMarcadorAlterado('M4', refM4, LN_PROMO_REQUEST_FP_PREFIX,  'REQUEST_ID_CONFLICT');
    _casoMarcadorAlterado('M5', refM5, LN_PROMO_COMPONENT_FP_PREFIX,'PROMO_APPLICATION_INCOMPLETE');

  } catch (eMain) {
    Logger.log('  ❌ EXCEPCIÓN EN EL CUERPO: ' + eMain);
    H.errores.push('EXCEPCION_CUERPO: ' + eMain);
  } finally {
    resultado = H.cerrarParte();
  }
  return resultado;
}

