// ════════════════════════════════════════════════════════════════════════════
// BLOQUE 8A-BACKEND — SUSTITUCIÓN NATIVA Y ATÓMICA DE SERVICIO POR PROMOCIÓN
// ════════════════════════════════════════════════════════════════════════════
//
// Objetivo exclusivo de este bloque: reemplazar la línea origen de un ticket
// (un servicio ya asignado/tomado por una staff) por TODOS los componentes de
// una promoción del catálogo (Paquetes), como UNA sola operación atómica:
//
//   anular línea origen  +  crear componentes de la promo  +  reconciliar TF
//
// Todo ocurre o nada ocurre. NO conecta router ni frontend. NO toca
// handleAplicarPromoStaff (legacy), que permanece intacto y sigue siendo lo
// que el botón "Aplicar promo" invoca hasta que se decida cortar el cable.
//
// Se diferencia del núcleo de PROMO EXTRA (_lnCrearPromoExtraNativoInterno_,
// más arriba en este archivo) en un punto estructural: aquella familia de
// funciones tiene prohibido tocar la línea padre ("NUNCA se anula ni se toca
// la línea padre — solo se crean líneas nuevas"). Esta familia hace
// exactamente lo contrario en su núcleo: SIEMPRE anula la línea origen como
// parte de la misma transacción. Por eso no se extiende el núcleo de extra —
// se construye un núcleo hermano, con su propia idempotencia y su propio
// namespace de marcadores, reutilizando solo los helpers verdaderamente
// genéricos: _lnValidarTicketParaExtraInterno_, _lnBuscarLineaExactaInterno_,
// _lnResolverDivisionPromoExtraEstricto_, _lnDerivarIdentidadTicketInterno_,
// _lnValidarStaffDestinoInterno_, _lnValidarLineRequestId_, _lnBuscarMarcador_,
// _lnExtraerMarcador_, _lnCompensarAnularLinea_, _lnRestaurarFilaLineaInterno_,
// _lnGrupoPromoIdDesdeFingerprint_, _lnSha256_, _ln5Redondear2_, _famAreaLineas_,
// LN3_ESTADOS_PENDIENTES, LN3_AUTH_OPERATIVOS, anularLinea, crearLinea.
//
// Marcadores de línea reutilizados TAL CUAL (contrato de _lnClasificarMarcadoresFila_
// no cambia): LN_LINE_REQUEST_ID_PREFIX, LN_LINE_FINGERPRINT_PREFIX. Marcadores
// de grupo NUEVOS y propios de este bloque (namespace separado del de promo
// extra, para que un mismo requestId nunca colisione entre ambos flujos):

var LN_SUST_REQUEST_ID_PREFIX   = '[NATIVE_SUST_REQUEST_ID:';
var LN_SUST_REQUEST_FP_PREFIX   = '[NATIVE_SUST_REQUEST_FP:';
var LN_SUST_COMPONENT_FP_PREFIX = '[NATIVE_SUST_COMPONENT_FP:';

// Whitelist CONTRACTUAL completa (los 4 estados que la orden define como
// sustituibles en general) vs. whitelist HABILITADA en este bloque (solo los
// 2 que ya tienen una regla de estado-destino definida y cubierta por arnés).
// 'completado' y 'por_verificar' quedan reconocidos por el contrato pero
// bloqueados con un error propio (LINEA_ORIGEN_ESTADO_NO_HABILITADO) hasta
// que exista una regla explícita de qué componentes nacen ejecutados y
// cuáles pendientes — la orden prohíbe expresamente adivinar esto.
var LN_SUST_ESTADOS_ORIGEN_CONTRATO    = ['esperando', 'en_servicio', 'por_verificar', 'completado'];
var LN_SUST_ESTADOS_ORIGEN_HABILITADOS = ['esperando', 'en_servicio'];

/**
 * _lnNormTextoSust_(s)
 * Normalizador puro para comparar nombres de servicio: minúsculas, sin
 * acentos, espacios colapsados. Mismo criterio de despojo de acentos que
 * _famAreaLineas_ (arriba en este archivo), para no introducir un segundo
 * comportamiento de normalización en el módulo.
 */
function _lnNormTextoSust_(s) {
  var x = String(s || '').trim().toLowerCase();
  try { x = x.normalize('NFD').replace(/[\u0300-\u036f]/g, ''); } catch (eNorm) {}
  var partes = x.split(' '), limpio = [];
  for (var i = 0; i < partes.length; i++) if (partes[i] !== '') limpio.push(partes[i]);
  return limpio.join(' ');
}

/**
 * _lnPromoContieneServicioOrigenInterno_(servicioOrigen, areaOrigen, division)
 *
 * Regla de compatibilidad (sección 5 de la orden): la promoción debe
 * CONTENER el servicio de la línea origen. Comparación por servicio
 * normalizado (nombre exacto tras normalizar), cruzada con familia de área
 * (_famAreaLineas_) como verificación de sanidad — no basta con que el
 * nombre coincida si el área resuelta por catálogo pertenece a otra familia
 * (dato corrupto o promo mal configurada en Paquetes).
 *
 * No hay identificador de catálogo estable disponible en este proyecto para
 * comparar además by-ID (ver limitación documentada en
 * _lnResolverDivisionPromoExtraEstricto_: promoCatalogoId es en realidad un
 * nombre resuelto contra Paquetes, no un ID numérico) — se deja constancia
 * de esta limitación en vez de fingir una comparación que no existe.
 *
 * @returns {{ ok:boolean, indiceComponenteOrigen?:number, error?:string, motivo?:string }}
 */
function _lnPromoContieneServicioOrigenInterno_(servicioOrigen, areaOrigen, division) {
  var servN = _lnNormTextoSust_(servicioOrigen);
  if (!servN) return { ok:false, error:'LINEA_ORIGEN_SERVICIO_VACIO' };
  var famOrigen = _famAreaLineas_(areaOrigen);
  var div = division || [];
  for (var i = 0; i < div.length; i++) {
    if (_lnNormTextoSust_(div[i].servicio) === servN) {
      if (_famAreaLineas_(div[i].area) !== famOrigen) {
        return { ok:false, error:'PROMO_SUSTITUCION_NO_COMPATIBLE',
                 motivo:'el servicio coincide por nombre pero el área del componente no pertenece a la misma familia que el área origen',
                 indice:i };
      }
      return { ok:true, indiceComponenteOrigen:i };
    }
  }
  return { ok:false, error:'PROMO_SUSTITUCION_NO_COMPATIBLE',
           motivo:'ningún componente de la promoción coincide con el servicio de la línea origen' };
}

// ── WRAPPER PÚBLICO ──────────────────────────────────────────────────────────
// Patrón idéntico a solicitarPromoExtraStaffNativa / agregarExtraMikaelaNativo:
// ScriptLock propio, waitLock(20000), delega TODO a la variante interna sin
// lock, captura LOCK_TIMEOUT y cualquier excepción, libera el lock en finally.
function sustituirServicioPorPromoStaffNativa(data) {
  var lock = LockService.getScriptLock();
  try { lock.waitLock(20000); }
  catch (eLock) { return { ok:false, error:'LOCK_TIMEOUT', message:String(eLock) }; }
  try {
    return _lnSustituirServicioPorPromoStaffNativaInterno_(data, _hojaLineas(), _tfHoja(), {});
  } catch (e) {
    return { ok:false, error:'EXCEPCION', message:String(e) };
  } finally { lock.releaseLock(); }
}

/**
 * _lnSustituirServicioPorPromoStaffNativaInterno_(data, wsLineas, wsTF, opts)
 *
 * data: {
 *   ticketRef, lineaOrigenId, promoCatalogoId, requestId,
 *   staffSolicitante,                          // NUEVO — ver A.2b más abajo
 *   componentes: [ { staff, lineaPadre } ],   // mismo orden que la división resuelta
 *   obs
 * }
 *
 * NO acepta como autoridad del cliente: precio, monto, montoRegular, servicio,
 * area, slot, partes, division, promoNombre, clienteCodigo, clienteNombre,
 * estado. Todo dato de catálogo sale EXCLUSIVAMENTE de Paquetes vía
 * _lnResolverDivisionPromoExtraEstricto_.
 *
 * componentes[i].staff: obligatoria SOLO para el componente que sustituye a
 * la línea origen. Los componentes ADICIONALES (otra área de la promo)
 * pueden traer staff vacía — nace 'esperando' sin dueña, en la cola de
 * Mikaela (misma convención ya documentada en crearLinea). Si sí traen
 * staff, se valida igual que siempre contra Usuarios.
 *
 * staffSolicitante identifica a QUIÉN EJECUTA la operación — un concepto
 * distinto de componentes[i].staff (la staff DESTINO de cada componente
 * nuevo). El router la inyecta desde la sesión firmada (nunca del payload
 * libre del cliente); si la línea origen ya tiene staff asignada, debe
 * coincidir (A.2b) tanto si la línea está 'esperando' como 'en_servicio' —
 * antes esta autorización solo se verificaba para 'en_servicio', y de forma
 * indirecta (comparando la staff DESTINO del componente, no la del
 * solicitante). Si la línea origen todavía no tiene staff asignada, no hay
 * identidad contra la cual comparar y se deja pasar.
 *
 * Protocolo (secciones 9 de la orden):
 *   FASE A — validar todo (ticket, línea origen, autorización del
 *            solicitante, catálogo, compatibilidad, staff destino, padres,
 *            distribución, idempotencia) sin escribir nada.
 *   FASE B — crear TODOS los componentes nuevos, atómico con rollback.
 *            La línea origen permanece intacta mientras tanto.
 *   FASE C — anular la línea origen (snapshot + escritura verificada). Si
 *            falla, compensar (anular) todos los componentes recién creados.
 *   FASE D — reconciliar TicketsFuente (idempotente: el ticket ya está
 *            en_atencion, así que es un no-op verificado, nunca una
 *            transición real). Si falla, restaurar la línea origen Y
 *            compensar todos los componentes.
 *
 * Nunca escribe nada hasta que la Fase A completa sin errores.
 */
function _lnSustituirServicioPorPromoStaffNativaInterno_(data, wsLineas, wsTF, opts) {
  opts = opts || {};
  data = data || {};

  var ticketRef      = String(data.ticketRef      || '').trim();
  var lineaOrigenId   = String(data.lineaOrigenId   || '').trim();
  var promoCatalogoId = String(data.promoCatalogoId || '').trim();

  if (!ticketRef)       return { ok:false, error:'TICKET_REF_REQUERIDO' };
  if (!lineaOrigenId)   return { ok:false, error:'LINEA_ORIGEN_ID_REQUERIDO', ticket_ref:ticketRef };
  if (!promoCatalogoId) return { ok:false, error:'PROMO_CATALOGO_ID_REQUERIDO', ticket_ref:ticketRef };

  var lridVal = _lnValidarLineRequestId_(data.requestId);
  if (!lridVal.ok) return { ok:false, error:lridVal.error, ticket_ref:ticketRef };
  var requestId = lridVal.lrid;

  // ══════════════════════════ FASE A — VALIDAR TODO ═══════════════════════

  // A.1 — Ticket madre: fuente LINEAS, activo, origen nativo, EXACTAMENTE
  // en_atencion (mismo validador certificado que usa el camino de extras
  // regulares y el de promo extra; actor STAFF no usa el parámetro modo).
  var valTk = _lnValidarTicketParaExtraInterno_(wsTF, ticketRef, 'STAFF', '');
  if (!valTk.ok) return valTk;

  // A.2 — Línea origen: SOLO estructural. Localizar exacta (por ticketRef +
  // lineaId, nunca por código de clienta, staff, nombre de servicio, monto ni
  // "primera línea coincidente"), validar existencia única y pertenencia al
  // ticket, y capturar snapshot + campos. La compuerta de ESTADO (cobrado/
  // anulado/whitelist/auth/marcador-de-componente) se aplica más abajo, en
  // A.5/A.6 — DESPUÉS de resolver idempotencia (A.4). Motivo: una sustitución
  // exitosa anula la línea origen; si la compuerta corriera acá, un reintento
  // con el mismo requestId (replay legítimo o conflicto real, casos V/W/X/Y)
  // chocaría contra "línea ya anulada" en vez de resolverse por huella — la
  // idempotencia debe poder reconocer su propio resultado anterior sin que
  // el efecto de ese resultado se lo impida.
  var busqOrigen = _lnBuscarLineaExactaInterno_(wsLineas, ticketRef, lineaOrigenId);
  if (!busqOrigen.ok) return busqOrigen; // LINE_NOT_FOUND / LINE_NOT_IN_TICKET / LINE_ID_DUPLICATED

  var filaOrigenSnapshot     = busqOrigen.fila;       // snapshot COMPLETO, previo a cualquier escritura
  var rowIndexOrigen         = busqOrigen.rowIndex;
  var estadoOrigen           = String(filaOrigenSnapshot[LX.estado]      || '').trim();
  var authOrigen             = String(filaOrigenSnapshot[LX.authEstado]  || '').trim();
  var staffOrigen            = String(filaOrigenSnapshot[LX.staff]       || '').trim();
  var areaOrigen              = String(filaOrigenSnapshot[LX.area]        || '').trim();
  var servicioOrigen         = String(filaOrigenSnapshot[LX.servicio]    || '').trim();
  var lineaPadreOrigenPropia = String(filaOrigenSnapshot[LX.lineaPadre]  || '').trim();
  var slotOrigen             = filaOrigenSnapshot[LX.slot];
  var obsOrigen               = String(filaOrigenSnapshot[LX.obs]         || '');

  // A.2b — Autorización del SOLICITANTE (quién ejecuta), independiente de la
  // staff DESTINO de cada componente (esa es harina de otro costal, validada
  // más abajo en A.10 contra Usuarios). staffSolicitante identifica a quien
  // llama la operación — el router la inyecta desde la sesión firmada, nunca
  // el payload libre. Si la línea origen ya tiene staff asignada, DEBE
  // coincidir; si la línea origen no tiene staff asignada todavía (posible
  // en 'esperando' sin tomar), no hay identidad contra la cual comparar y se
  // deja pasar. Se verifica ACÁ, ANTES de catálogo/idempotencia (A.3/A.4) a
  // propósito: staff es un campo que anularLinea() NUNCA toca (solo modifica
  // estado/obs/motivo_anulacion/auth_estado/actualizada) — es estable incluso
  // después de que la línea origen quede anulada por una sustitución previa,
  // así que chequearlo temprano no interfiere con el replay/conflicto de A.4
  // (a diferencia de estadoOrigen, que sí cambia como efecto colateral).
  // Fallar rápido acá también evita filtrar información de idempotencia
  // (si ya existe un grupo o no) a un llamador no autorizado para esta línea.
  var staffSolicitante = String(data.staffSolicitante || '').trim();
  if (staffOrigen && staffSolicitante.toLowerCase() !== staffOrigen.toLowerCase())
    return { ok:false, error:'STAFF_SOLICITANTE_NO_COINCIDE',
             staff_linea_origen:staffOrigen, staff_solicitante:staffSolicitante,
             ticket_ref:ticketRef, linea_origen:lineaOrigenId };

  // A.3 — Resolución ESTRICTA del catálogo (Paquetes). Pura consulta de solo
  // lectura contra Paquetes — no depende del estado dinámico del ticket (a
  // diferencia de la resolución de padre/candidatas, que si depende, y que
  // por eso se movió mucho más abajo, después de confirmar idempotencia).
  // Se resuelve ACÁ, temprano, porque tanto la huella de comparación (A.4)
  // como la creación real (más abajo) la necesitan, y solo cuesta una
  // consulta — no una escritura.
  var divRes = _lnResolverDivisionPromoExtraEstricto_(promoCatalogoId, areaOrigen, '');
  if (!divRes.ok) return { ok:false, error:divRes.error, message:divRes.message, ticket_ref:ticketRef };
  var division = divRes.division;
  if (!division.length)
    return { ok:false, error:'PROMO_SUSTITUCION_GRUPO_INCOMPLETO', motivo:'división vacía', ticket_ref:ticketRef };
  for (var vi = 0; vi < division.length; vi++) {
    var mVal = division[vi].monto;
    if (mVal === undefined || !isFinite(mVal) || mVal < 0)
      return { ok:false, error:'PROMO_SUSTITUCION_MONTO_INVALIDO', componente:vi,
               servicio:division[vi].servicio, ticket_ref:ticketRef };
  }

  // A.4 — Huella de COMPARACIÓN + resolución de replay/conflicto. Se
  // construye EXCLUSIVAMENTE con lo explícito del payload (staff, lineaPadre
  // TAL CUAL el caller los mandó, sin inferencia de ambigüedad ni consulta a
  // candidatasTicket) + el catálogo ya resuelto en A.3 (servicio/area/monto).
  // Nunca se re-infiere padre desde el estado actual de LINEAS acá — esa
  // inferencia (con sus reglas de ambigüedad/TM) queda para A.10, y solo se
  // ejecuta si esto resulta ser una solicitud genuinamente nueva. Así una
  // sustitución exitosa previa (que deja más líneas "pendientes" en el
  // ticket — los propios componentes recién creados) nunca puede hacer que
  // un replay o un conflicto legítimo choquen contra LINEA_PADRE_REQUERIDA_*
  // en vez de resolverse por huella.
  var componentesEntrada = Array.isArray(data.componentes) ? data.componentes : [];
  var componentesCrudos = componentesEntrada.map(function (entrada, idx) {
    var d = division[idx] || {};
    return {
      servicio: d.servicio || '', area: d.area || '',
      staff: String((entrada && entrada.staff) || '').trim(),
      lineaPadre: String((entrada && entrada.lineaPadre) || '').trim(),
      monto: Number(d.monto || 0),
      montoRegular: (d.regular !== undefined && d.regular !== null) ? Number(d.regular) : Number(d.monto || 0)
    };
  });

  var fp = _lnSha256_(JSON.stringify([
    'SUSTITUCION_PROMO', ticketRef, lineaOrigenId, promoCatalogoId,
    componentesCrudos.map(function (c) {
      return [
        c.servicio, c.area, c.staff, c.lineaPadre,
        String(_ln5Redondear2_(c.monto)), String(_ln5Redondear2_(c.montoRegular))
      ];
    })
  ]));
  var grupoSustitucionId = _lnGrupoPromoIdDesdeFingerprint_(fp);

  var rqidMarcador     = LN_SUST_REQUEST_ID_PREFIX + requestId + ']';
  var fpMarcador       = LN_SUST_REQUEST_FP_PREFIX + fp + ']';
  var lineRqidMarcador = LN_LINE_REQUEST_ID_PREFIX  + requestId + ']';
  var lineFpMarcador   = LN_LINE_FINGERPRINT_PREFIX + fp        + ']';

  var candsGrupo = _lnBuscarMarcador_(wsLineas, rqidMarcador).filter(function (c) {
    return String(c.data[LX.ticketRef] || '').trim() === ticketRef;
  });
  if (candsGrupo.length > 0) {
    var fpExistente = _lnExtraerMarcador_(String(candsGrupo[0].data[LX.obs] || ''), LN_SUST_REQUEST_FP_PREFIX);
    if (fpExistente !== fp)
      return { ok:false, error:'PROMO_SUSTITUCION_REQUEST_CONFLICT', requestId:requestId,
               fp_existente:fpExistente, fp_solicitado:fp, ticket_ref:ticketRef };
    var idsExistentes = candsGrupo.map(function (c) { return String(c.data[LX.id] || ''); });
    return { ok:true, yaExistia:true, idempotente:true, escritura:false,
             ticket_ref:ticketRef, grupo_promo_id:grupoSustitucionId,
             linea_origen_id:lineaOrigenId, componentes_ids:idsExistentes };
  }
  // NOTA DE DISEÑO (limitación conocida, sin caso de arnés que la cubra):
  // el "estado" de la línea origen al momento de la primera creación
  // (esperando vs en_servicio, que determina qué componente nace en_servicio
  // — sección 10) NO se incluye en esta huella. Incluir el estadoOrigen
  // LEÍDO EN VIVO invalidaría cualquier replay legítimo, porque ese mismo
  // estado cambia a 'anulado' como efecto colateral de la propia primera
  // ejecución exitosa — comparar contra un valor que la operación anterior
  // ya modificó rompería la idempotencia en vez de protegerla. Un conflicto
  // motivado exclusivamente por "misma huella pero el origen estaba en otro
  // estado la primera vez" no se detecta con este diseño; no hay caso V/W/
  // X/Y que lo ejercite.

  // ── A PARTIR DE ACÁ: SOLICITUD GENUINAMENTE NUEVA ───────────────────────
  // A.9 ya descartó que sea el replay/conflicto de una ya resuelta.

  // A.5 — Compuertas TERMINALES de la línea origen. Antes que cualquier otra
  // validación de negocio (compatibilidad, distribución, padres) — así una
  // línea cobrada o anulada nunca se enmascara detrás de un error de
  // compatibilidad, aunque la promo enviada también fuera incompatible.
  if (estadoOrigen === 'cobrado')
    return { ok:false, error:'LINEA_ORIGEN_COBRADA', ticket_ref:ticketRef, linea_origen:lineaOrigenId };
  if (estadoOrigen === 'anulado')
    return { ok:false, error:'LINEA_ORIGEN_ANULADA', ticket_ref:ticketRef, linea_origen:lineaOrigenId };

  // A.6 — Resto de compuertas de estado de la línea origen.
  if (LN_SUST_ESTADOS_ORIGEN_CONTRATO.indexOf(estadoOrigen) < 0)
    return { ok:false, error:'LINEA_ORIGEN_ESTADO_INVALIDO', estado_origen:estadoOrigen,
             ticket_ref:ticketRef, linea_origen:lineaOrigenId };
  if (LN_SUST_ESTADOS_ORIGEN_HABILITADOS.indexOf(estadoOrigen) < 0)
    return { ok:false, error:'LINEA_ORIGEN_ESTADO_NO_HABILITADO', estado_origen:estadoOrigen,
             motivo:'completado/por_verificar requieren una política de estados aún no definida (ver orden Bloque 8A, sección 13)',
             ticket_ref:ticketRef, linea_origen:lineaOrigenId };
  if (LN3_AUTH_OPERATIVOS.indexOf(authOrigen) < 0)
    return { ok:false, error:'LINEA_ORIGEN_AUTH_NO_OPERATIVA', auth_estado_origen:authOrigen,
             ticket_ref:ticketRef, linea_origen:lineaOrigenId };
  // "no es ya un componente de la misma sustitución": una línea que ya nació
  // como componente de OTRA sustitución nunca puede volver a ser origen.
  if (obsOrigen.indexOf(LN_SUST_COMPONENT_FP_PREFIX) !== -1)
    return { ok:false, error:'LINEA_ORIGEN_YA_ES_COMPONENTE_SUSTITUCION', ticket_ref:ticketRef, linea_origen:lineaOrigenId };

  // A.7 — Compatibilidad: la promo debe CONTENER el servicio origen. Este
  // helper ya devuelve LINEA_ORIGEN_SERVICIO_VACIO si servicioOrigen viene
  // vacío — no se duplica esa validación por separado.
  var compat = _lnPromoContieneServicioOrigenInterno_(servicioOrigen, areaOrigen, division);
  if (!compat.ok) {
    compat.ticket_ref = ticketRef;
    compat.linea_origen = lineaOrigenId;
    return compat;
  }
  var indiceComponenteOrigen = compat.indiceComponenteOrigen;

  // A.8 — Distribución: ni componentes faltantes ni sobrantes.
  if (componentesEntrada.length !== division.length)
    return { ok:false, error:'PROMO_SUSTITUCION_DISTRIBUCION_INVALIDA',
             esperados:division.length, recibidos:componentesEntrada.length, ticket_ref:ticketRef };

  // A.9 — Candidatas del ticket para lineaPadre (mismo criterio ya
  // certificado del núcleo de promo extra), EXCLUYENDO la línea origen. Solo
  // se llega hasta acá para una solicitud ya confirmada como nueva por A.4 —
  // por eso las líneas que un intento previo haya creado ya no pueden
  // provocar una ambigüedad espuria contra un replay o un conflicto.
  var esTM = ticketRef.indexOf('TM-') === 0;
  var datosCand = wsLineas.getDataRange().getValues();
  var candidatasTicket = [];
  for (var ci = 1; ci < datosCand.length; ci++) {
    if (String(datosCand[ci][LX.ticketRef] || '').trim() !== ticketRef) continue;
    var idCand = String(datosCand[ci][LX.id] || '').trim();
    if (idCand === lineaOrigenId) continue;
    var estCand = String(datosCand[ci][LX.estado] || '').trim();
    if (LN3_ESTADOS_PENDIENTES.indexOf(estCand) >= 0) candidatasTicket.push(idCand);
  }

  // A.10 — Por componente: la staff es obligatoria SOLO para el componente
  // que sustituye a la línea origen (esComponenteOrigen) — alguien ya la
  // estaba haciendo o está a punto de hacerla, así que no puede nacer sin
  // dueña. Los componentes ADICIONALES (otra área de la promo, ej. pestañas
  // cuando la staff que aplica es de cejas) pueden nacer SIN staff — crearLinea
  // ya documenta esta convención ("vacío = en cola de Mikaela", línea 322) y
  // el motor agregado (_lnEvaluarEstadoAgregadoTicketInterno_) ya cuenta un
  // componente 'esperando' sin staff como pendiente igual que uno con staff,
  // así que el ticket permanece correctamente en_atencion hasta que Mikaela
  // lo asigne. Si SÍ viene una staff para un componente adicional, se valida
  // igual que siempre contra Usuarios — la novedad es que ahora puede venir
  // vacía, no que se relaje la validación cuando sí viene.
  var componentesConDatos = [];
  for (var pi = 0; pi < division.length; pi++) {
    var entrada = componentesEntrada[pi] || {};
    var esComponenteOrigen = (pi === indiceComponenteOrigen);

    var staffComp = String(entrada.staff || '').trim();
    if (!staffComp && esComponenteOrigen)
      return { ok:false, error:'STAFF_REQUERIDO', componente:pi,
               servicio:division[pi].servicio, ticket_ref:ticketRef };
    if (staffComp) {
      var valStaff = _lnValidarStaffDestinoInterno_(staffComp);
      if (!valStaff.ok)
        return { ok:false, error:valStaff.error, componente:pi, staff:staffComp,
                 servicio:division[pi].servicio, ticket_ref:ticketRef };
    }

    // Invariante propia de este bloque (no exigida literalmente por la orden,
    // pero consistente con PARENT_LINE_STAFF_CONFLICT ya certificado en el
    // flujo de extras): si la línea origen está en_servicio, el componente
    // que la sustituye no puede reasignarse silenciosamente a otra staff.
    if (esComponenteOrigen && estadoOrigen === 'en_servicio' &&
        staffComp.toLowerCase() !== staffOrigen.toLowerCase()) {
      return { ok:false, error:'COMPONENTE_ORIGEN_STAFF_CONFLICTO',
               staff_origen:staffOrigen, staff_recibida:staffComp,
               componente:pi, ticket_ref:ticketRef, linea_origen:lineaOrigenId };
    }

    var padreComp, slotComp;
    if (esComponenteOrigen) {
      // El componente que sustituye al origen hereda el padre OPERATIVO
      // original de la línea origen (no la línea origen en sí, que va a
      // quedar anulada) — conserva la jerarquía del ticket intacta. Se
      // ignora cualquier lineaPadre que el payload mande para este índice:
      // se deriva, nunca se acepta como autoridad del cliente.
      padreComp = lineaPadreOrigenPropia;
      slotComp  = slotOrigen;
    } else {
      var padreEntrada = String(entrada.lineaPadre || '').trim();
      if (!padreEntrada) {
        if (esTM)
          return { ok:false, error:'LINEA_PADRE_REQUERIDA_TM', componente:pi,
                   servicio:division[pi].servicio, ticket_ref:ticketRef };
        if (candidatasTicket.length >= 2)
          return { ok:false, error:'LINEA_PADRE_REQUERIDA_AMBIGUA', componente:pi,
                   servicio:division[pi].servicio, candidatas:candidatasTicket, ticket_ref:ticketRef };
        padreComp = '';
        slotComp  = '';
      } else {
        var busqPadreComp = _lnBuscarLineaExactaInterno_(wsLineas, ticketRef, padreEntrada);
        if (!busqPadreComp.ok) return busqPadreComp; // LINE_NOT_FOUND / LINE_NOT_IN_TICKET
        padreComp = padreEntrada;
        var slotPadreRaw = busqPadreComp.fila[LX.slot];
        slotComp = (slotPadreRaw === undefined || slotPadreRaw === null) ? '' : slotPadreRaw;
      }
    }

    componentesConDatos.push({
      servicio: division[pi].servicio, area: division[pi].area,
      staff: staffComp, lineaPadre: padreComp, slotEfectivo: slotComp,
      monto: Number(division[pi].monto || 0),
      montoRegular: (division[pi].regular !== undefined && division[pi].regular !== null)
        ? Number(division[pi].regular) : Number(division[pi].monto || 0),
      esComponenteOrigen: esComponenteOrigen
    });
  }

  // A.11 — Identidad del ticket (codigo/cliente/origen/synaRef), derivada
  // del propio ticket — nunca del payload.
  var ident = _lnDerivarIdentidadTicketInterno_(wsLineas, wsTF, ticketRef);
  if (!ident.ok) return ident;

  if (opts.modoTest && opts.hookFallarAntesDeCrear && ticketRef.indexOf('T-TEST-') === 0)
    return { ok:false, error:'TEST_HOOK_FALLO_ANTES_DE_CREAR', ticket_ref:ticketRef };

  // ═══════════════════ FASE B — CREAR TODOS LOS COMPONENTES ════════════════
  // Atómico, con rollback. La línea origen NO se toca todavía.
  var creadas = [];
  try {
    for (var idx = 0; idx < componentesConDatos.length; idx++) {
      var comp = componentesConDatos[idx];
      var compFp = _lnSha256_(JSON.stringify(
        ['SUST_COMPONENTE', fp, idx, comp.servicio, comp.area, comp.staff]));
      var obsComp = lineRqidMarcador + ' ' + lineFpMarcador + ' ' +
                    rqidMarcador + ' ' + fpMarcador + ' ' +
                    LN_SUST_COMPONENT_FP_PREFIX + compFp + ']';

      if (opts.modoTest && opts.hookFallarComponenteIndice === idx && ticketRef.indexOf('T-TEST-') === 0)
        throw new Error('TEST_HOOK_FALLO_COMPONENTE_' + idx);

      // Estado inicial del componente (sección 10 de la orden):
      //   · origen 'en_servicio' → SOLO el componente que sustituye al origen
      //     nace en_servicio (la staff ya lo estaba haciendo); todo lo demás
      //     nace esperando, aunque sea de la misma staff.
      //   · origen 'esperando'   → todos los componentes nacen esperando.
      var estadoDestino = (comp.esComponenteOrigen && estadoOrigen === 'en_servicio')
        ? 'en_servicio' : 'esperando';

      var rComp = crearLinea({
        visita: ticketRef, ticketRef: ticketRef, codigo: ident.codigo, cliente: ident.cliente,
        staff: comp.staff, area: comp.area, servicio: comp.servicio, esPromo: true,
        promoRef: promoCatalogoId, monto: comp.monto, montoRegular: comp.montoRegular,
        estado: estadoDestino, origen: ident.origen, synaRef: ident.synaRef,
        authEstado: 'aprobada', lineaPadre: comp.lineaPadre, slot: comp.slotEfectivo,
        grupoPromoId: grupoSustitucionId, motivoAnulacion: '', precioAplicado: '', obs: obsComp
      });
      if (!rComp || !rComp.id) throw new Error('CREACION_COMPONENTE_FALLIDA_' + idx);
      creadas.push(rComp.id);
    }
  } catch (eCrear) {
    var compensadasB = 0, compensacionOkB = true;
    creadas.forEach(function (id) {
      var c = _lnCompensarAnularLinea_(id, 'ROLLBACK_SUSTITUCION_PROMO_PARCIAL', opts);
      if (c && c.ok) compensadasB++; else compensacionOkB = false;
    });
    return { ok:false,
             error: compensacionOkB ? 'PROMO_SUSTITUCION_GRUPO_INCOMPLETO' : 'COMPENSACION_INCOMPLETA',
             error_original:String(eCrear), creadas_antes_del_fallo:creadas.length,
             compensadas:compensadasB, ticket_ref:ticketRef, linea_origen:lineaOrigenId };
  }

  // ═══════════════════ FASE C — ANULAR LA LÍNEA ORIGEN ═════════════════════
  // Solo ahora, con TODOS los componentes ya creados y verificados. Si algo
  // falla en esta fase, se compensan (anulan) los componentes recién creados
  // y la línea origen queda exactamente como estaba.
  if (opts.modoTest && opts.hookFallarAnularOrigen && ticketRef.indexOf('T-TEST-') === 0) {
    var compAAt = 0, okAAt = true;
    creadas.forEach(function (id) {
      var r = _lnCompensarAnularLinea_(id, 'ROLLBACK_SUSTITUCION_ANULAR_ORIGEN_FALLIDA', opts);
      if (r && r.ok) compAAt++; else okAAt = false;
    });
    return { ok:false, error: okAAt ? 'LINEA_ORIGEN_ANULACION_FALLIDA' : 'COMPENSACION_INCOMPLETA',
             compensadas:compAAt, creadas_antes_del_fallo:creadas.length,
             ticket_ref:ticketRef, linea_origen:lineaOrigenId };
  }

  var rAnulOrigen = anularLinea(lineaOrigenId,
    'sustitucion por promocion ' + promoCatalogoId + ' (' + grupoSustitucionId + ')');
  if (!rAnulOrigen || !rAnulOrigen.success) {
    var compAB = 0, okAB = true;
    creadas.forEach(function (id) {
      var r = _lnCompensarAnularLinea_(id, 'ROLLBACK_SUSTITUCION_ANULAR_ORIGEN_FALLIDA', opts);
      if (r && r.ok) compAB++; else okAB = false;
    });
    return { ok:false, error: okAB ? 'LINEA_ORIGEN_ANULACION_FALLIDA' : 'COMPENSACION_INCOMPLETA',
             detalle_origen:rAnulOrigen, compensadas:compAB, creadas_antes_del_fallo:creadas.length,
             ticket_ref:ticketRef, linea_origen:lineaOrigenId };
  }

  // ═══════════════════ FASE D — RECONCILIAR TICKETSFUENTE ══════════════════
  // El ticket ya validó como en_atencion en A.1 y esta operación (staff,
  // dentro del mismo ticket) no cambia su estado — _tfActualizarEstadoInterno
  // ya es idempotente para "mismo estado" (escritura:false, sin transición).
  // Se ejercita igual, verificado, para dejar reconciliación auditable y
  // cubrir el caso real de que el ticket haya cambiado de estado entre la
  // Fase A y este punto (concurrencia): si ya no es en_atencion, esto falla
  // y dispara el rollback completo, tal como pide la orden.
  var tfDataActual = _lnTfData_(wsTF);
  var rTF = _tfActualizarEstadoInterno(ticketRef, 'en_atencion', wsTF, tfDataActual);
  var tfFalloReal = !rTF || rTF.ok !== true;
  if (opts.modoTest && opts.hookFallarTF && ticketRef.indexOf('T-TEST-') === 0) tfFalloReal = true;

  if (tfFalloReal) {
    var restOrigen = _lnRestaurarFilaLineaInterno_(
      wsLineas, rowIndexOrigen, filaOrigenSnapshot, { ticketRef:ticketRef });
    var compAC = 0, okAC = true;
    creadas.forEach(function (id) {
      var r = _lnCompensarAnularLinea_(id, 'ROLLBACK_SUSTITUCION_TF_FALLIDA', opts);
      if (r && r.ok) compAC++; else okAC = false;
    });
    var todoOkAC = restOrigen.ok && okAC;
    return { ok:false,
             error: todoOkAC ? 'TICKETS_FUENTE_RECONCILIACION_FALLIDA' : 'COMPENSACION_INCOMPLETA',
             detalle_tf: rTF, restauracion_origen_ok: restOrigen.ok,
             detalle_restauracion_origen: restOrigen, compensadas:compAC,
             creadas_antes_del_fallo:creadas.length, ticket_ref:ticketRef, linea_origen:lineaOrigenId };
  }

  return { ok:true, escritura:true, ticket_ref:ticketRef,
           grupo_promo_id:grupoSustitucionId, linea_origen_id:lineaOrigenId,
           linea_origen_anulada:true, componentes_ids:creadas,
           componentes: creadas.map(function (id, idx) {
             return { id:id, staff:componentesConDatos[idx].staff,
                      esComponenteOrigen:componentesConDatos[idx].esComponenteOrigen,
                      estado: (componentesConDatos[idx].esComponenteOrigen && estadoOrigen === 'en_servicio') ? 'en_servicio' : 'esperando' };
           }) };
}


// ════════════════════════════════════════════════════════════════════════════
// ARNÉS — _test_sustituirServicioPorPromoStaffNativa()
// ════════════════════════════════════════════════════════════════════════════
//
// AVISO DE ALCANCE: este arnés fue escrito y verificado sintácticamente
// (node --check) pero NO se ejecutó contra una hoja de cálculo real — este
// entorno no tiene acceso a Google Apps Script en vivo. Correr en DEV como
// los bloques anteriores y reportar resultado antes de considerar el bloque
// cerrado. Si se acerca al límite de tiempo de ejecución de Apps Script,
// dividir en partes (mismo patrón ya usado en promoExtraNativoNucleo A/B/C).
//
// Mock de _resolverDivisionPromoNativa_ (mismo mecanismo ya establecido por
// _test_solicitarPromoExtraStaffNativa): reemplaza la función global durante
// el test y la restaura en finally. Mock de _lnValidarStaffDestinoInterno_
// análogo, para no depender del contenido real de la hoja Usuarios.
// ════════════════════════════════════════════════════════════════════════════
// ARNÉS — dividido en 4 partes independientes (Corrección Bloque 8A-BACKOFFICE)
// ════════════════════════════════════════════════════════════════════════════
//
// El arnés monolítico original hizo timeout en Apps Script después de la
// primera sustitución del caso Y, sin completar ni limpiar. Se divide en 4
// funciones independientes, cada una con su propio try/finally y limpieza,
// para que cada ejecución sea completa y la limpieza esté garantizada aunque
// las demás partes no se corran en la misma sesión.
//
// Orden sugerido de ejecución en DEV:
//   _test_sustituirServicioPorPromoStaffNativa_C()   ← primero: contiene
//     V/W/X/Y, la corrección más delicada (idempotencia antes que
//     inferencia de padre por ambigüedad).
//   _test_sustituirServicioPorPromoStaffNativa_A()   — A/EnServicio/J
//   _test_sustituirServicioPorPromoStaffNativa_B()   — K–U
//   _test_sustituirServicioPorPromoStaffNativa_D()   — Z–AG
//
// AVISO DE ALCANCE: las 4 partes fueron escritas y verificadas
// sintácticamente (node --check) pero NO se ejecutaron contra una hoja de
// cálculo real — este entorno no tiene acceso a Google Apps Script en vivo.
// Correr en DEV y reportar el log completo de cada parte.

function _test_sustituirServicioPorPromoStaffNativa_C() {
  var wsLineas = _hojaLineas(), wsTF = _tfHoja();
  var fallos = 0;
  var refs = [];
  var resolverOriginal = _resolverDivisionPromoNativa_;
  var validarStaffOriginal = _lnValidarStaffDestinoInterno_;

  function _chk(nombre, cond, detalle) {
    if (cond) { Logger.log('  ✅ ' + nombre); }
    else { fallos++; Logger.log('  ❌ ' + nombre + (detalle ? ' — ' + detalle : '')); }
  }
  function _mockDivision(division) {
    _resolverDivisionPromoNativa_ = function () { return { ok:true, division:division }; };
  }
  function _mockStaffOk(nombresValidos) {
    _lnValidarStaffDestinoInterno_ = function (nombre) {
      return (nombresValidos.indexOf(nombre) >= 0)
        ? { ok:true } : { ok:false, error:'STAFF_DESTINO_NO_ENCONTRADA' };
    };
  }
  function _mockStaffInactiva(nombreInactivo) {
    _lnValidarStaffDestinoInterno_ = function (nombre) {
      return (nombre === nombreInactivo)
        ? { ok:false, error:'STAFF_DESTINO_INACTIVA' } : { ok:true };
    };
  }
  function _restaurarMocks() {
    _resolverDivisionPromoNativa_ = resolverOriginal;
    _lnValidarStaffDestinoInterno_ = validarStaffOriginal;
  }
  function _lineaPorId(id) {
    var datos = wsLineas.getDataRange().getValues();
    for (var i = 1; i < datos.length; i++) {
      if (String(datos[i][LX.id] || '') === String(id)) return _filaAObjeto(datos[i]);
    }
    return null;
  }
  function _lineasDelGrupo(grupoId) {
    var datos = wsLineas.getDataRange().getValues();
    var out = [];
    for (var i = 1; i < datos.length; i++) {
      if (String(datos[i][LX.grupoPromoId] || '') === String(grupoId)) out.push(_filaAObjeto(datos[i]));
    }
    return out;
  }
  function _setupTicketConLineaOrigen(sufijo, familia, servicioOrigen, areaOrigen, iniciarEnServicio) {
    var ref = 'T-TEST-SUST-' + sufijo + '-' + Date.now() + '-' + Math.floor(Math.random() * 100000);
    var staff = _lnStaffAisladaTest_(ref, familia || 'Cejas');
    // La primera línea del ticket es una línea BASE genérica, sin relación con
    // lo que se está probando. Se inicia de una (igual que
    // _test_solicitarPromoExtraStaffNativa caso B) para que TicketsFuente
    // pase a en_atencion — requisito de _lnValidarTicketParaExtraInterno_
    // para actor STAFF. La línea ORIGEN real bajo prueba se crea aparte,
    // como línea adicional, con el estado exacto que cada caso necesita.
    var rTk = _crearTicketNativoInterno_({
      codigo:'C-TEST', cliente:'Test Sustitucion ' + sufijo, origen:'NEXSERV', requestId:'RQ-' + ref,
      primeraLinea: { area: areaOrigen, servicio: 'Linea base ' + sufijo, monto: 1, montoRegular: 1 }
    }, wsLineas, wsTF, { modoTest:true, ticketRefPrueba: ref });
    if (!rTk.ok) return { ok:false, ref:ref, error:rTk.error };
    var lineaBaseId = rTk.linea_id;

    var rIniBase = _iniciarLineaNativaInterno_({ ticketRef: ref, lineaId: lineaBaseId, staff: staff },
      wsLineas, wsTF, _lnOptsPuestosTest_());
    if (!rIniBase.ok) return { ok:false, ref:ref, error:'setup iniciar línea base falló: ' + rIniBase.error };

    var rOrigen = crearLinea({
      visita: ref, ticketRef: ref, codigo:'C-TEST', cliente:'Test Sustitucion ' + sufijo,
      staff: staff, area: areaOrigen, servicio: servicioOrigen, esPromo:false,
      monto: 10, montoRegular: 10, estado: iniciarEnServicio ? 'en_servicio' : 'esperando',
      authEstado: 'no_requiere', origen:'NEXSERV',
      obs: '[NATIVE_LINE_REQUEST_ID:RQ-ORIGEN-' + ref + '] [NATIVE_LINE_REQUEST_FP:FP-ORIGEN-' + ref + ']'
    });
    if (!rOrigen || !rOrigen.id) return { ok:false, ref:ref, error:'no se pudo crear la línea origen de prueba' };

    return { ok:true, ref:ref, staff:staff, lineaOrigenId:rOrigen.id, lineaBaseId:lineaBaseId };
  }

  try {
    // ── V/W: replay idéntico / conflicto por otra promo — AUTOCONTENIDO ────
    // Ticket propio (no depende del de ningún otro caso), para que esta
    // parte del arnés pueda correrse sola. V y W deben resolverse en A.4
    // (huella + idempotencia), ANTES de que exista cualquier posibilidad de
    // volver a inferir lineaPadre por ambigüedad contra el estado mutado del
    // ticket (esa era la causa real del fallo reportado en DEV).
    var setVW = _setupTicketConLineaOrigen('VW', 'Cejas', 'Depilacion de cejas', 'cejas', false);
    _chk('setup V/W. ticket + línea origen (esperando)', setVW.ok, setVW.error);
    if (setVW.ok) {
      refs.push(setVW.ref);
      _mockDivision([
        { servicio:'Depilacion de cejas', area:'cejas', staff:'', monto:10, regular:15 },
        { servicio:'Depilacion de bigote', area:'cejas', staff:'', monto:5,  regular:8 }
      ]);
      _mockStaffOk([setVW.staff]);
      var rVW1 = _lnSustituirServicioPorPromoStaffNativaInterno_({
        ticketRef: setVW.ref, lineaOrigenId: setVW.lineaOrigenId, staffSolicitante:setVW.staff, promoCatalogoId:'PROMO-TEST-SUST-VW',
        requestId:'RQ-SUST-VW-' + setVW.ref,
        componentes: [ { staff:setVW.staff }, { staff:setVW.staff } ]
      }, wsLineas, wsTF, {});
      _chk('setup V/W. primera sustitución OK', rVW1.ok === true, JSON.stringify(rVW1));

      if (rVW1.ok) {
        // V: mismo requestId, mismo payload → replay idempotente.
        var lineasAntesV = wsLineas.getDataRange().getValues().length;
        var rV = _lnSustituirServicioPorPromoStaffNativaInterno_({
          ticketRef: setVW.ref, lineaOrigenId: setVW.lineaOrigenId, staffSolicitante:setVW.staff, promoCatalogoId:'PROMO-TEST-SUST-VW',
          requestId:'RQ-SUST-VW-' + setVW.ref,
          componentes: [ { staff:setVW.staff }, { staff:setVW.staff } ]
        }, wsLineas, wsTF, {});
        var lineasDespuesV = wsLineas.getDataRange().getValues().length;
        _chk('V. replay idéntico → idempotente, mismo grupo',
             rV.ok === true && rV.idempotente === true && rV.grupo_promo_id === rVW1.grupo_promo_id,
             JSON.stringify(rV));
        _chk('V. NO pasa por LINEA_PADRE_REQUERIDA_AMBIGUA/TM/LINE_NOT_FOUND/LINE_NOT_IN_TICKET',
             ['LINEA_PADRE_REQUERIDA_AMBIGUA','LINEA_PADRE_REQUERIDA_TM','LINE_NOT_FOUND','LINE_NOT_IN_TICKET']
               .indexOf(rV.error) === -1, JSON.stringify(rV));
        _chk('V. no crea líneas nuevas', lineasAntesV === lineasDespuesV);
        var origenV = _lineaPorId(setVW.lineaOrigenId);
        _chk('V. línea origen no se retoca (sigue anulada por la primera ejecución)',
             origenV && origenV.estado === 'anulado', JSON.stringify(origenV));
        var tfFilaV = _tfBuscarFilaInterno(setVW.ref, _lnTfData_(wsTF));
        _chk('V. TicketsFuente sin cambio (en_atencion)',
             tfFilaV && !tfFilaV.duplicado && tfFilaV.fila.estadoTicket === 'en_atencion', JSON.stringify(tfFilaV));

        // W: mismo requestId, otra promo → conflicto.
        var lineasAntesW = wsLineas.getDataRange().getValues().length;
        var rW = _lnSustituirServicioPorPromoStaffNativaInterno_({
          ticketRef: setVW.ref, lineaOrigenId: setVW.lineaOrigenId, staffSolicitante:setVW.staff, promoCatalogoId:'PROMO-TEST-SUST-VW-OTRA',
          requestId:'RQ-SUST-VW-' + setVW.ref,
          componentes: [ { staff:setVW.staff }, { staff:setVW.staff } ]
        }, wsLineas, wsTF, {});
        var lineasDespuesW = wsLineas.getDataRange().getValues().length;
        _chk('W. mismo requestId, otra promo → PROMO_SUSTITUCION_REQUEST_CONFLICT',
             rW.error === 'PROMO_SUSTITUCION_REQUEST_CONFLICT', JSON.stringify(rW));
        _chk('W. NO pasa por LINEA_PADRE_REQUERIDA_AMBIGUA/TM/LINE_NOT_FOUND/LINE_NOT_IN_TICKET',
             ['LINEA_PADRE_REQUERIDA_AMBIGUA','LINEA_PADRE_REQUERIDA_TM','LINE_NOT_FOUND','LINE_NOT_IN_TICKET']
               .indexOf(rW.error) === -1, JSON.stringify(rW));
        _chk('W. no crea líneas nuevas', lineasAntesW === lineasDespuesW);
        var origenW = _lineaPorId(setVW.lineaOrigenId);
        _chk('W. línea origen sin cambio adicional (sigue anulada, misma que V)',
             origenW && origenW.estado === 'anulado', JSON.stringify(origenW));
        var tfFilaW = _tfBuscarFilaInterno(setVW.ref, _lnTfData_(wsTF));
        _chk('W. TicketsFuente sin cambio (en_atencion)',
             tfFilaW && !tfFilaW.duplicado && tfFilaW.fila.estadoTicket === 'en_atencion', JSON.stringify(tfFilaW));
      }
    }

    // ── X: mismo requestId, distinta staff → conflicto ─────────────────────
    var setX = _setupTicketConLineaOrigen('X', 'Cejas', 'Depilacion de cejas', 'cejas', false);
    _chk('setup X. ticket creado', setX.ok, setX.error);
    if (setX.ok) {
      refs.push(setX.ref);
      _mockDivision([{ servicio:'Depilacion de cejas', area:'cejas', staff:'', monto:10, regular:15 }]);
      _mockStaffOk([setX.staff, 'STAFF-ALT-X']);
      var rX1 = _lnSustituirServicioPorPromoStaffNativaInterno_({
        ticketRef: setX.ref, lineaOrigenId: setX.lineaOrigenId, staffSolicitante:setX.staff, promoCatalogoId:'PROMO-TEST-SUST-X',
        requestId:'RQ-SUST-X-' + setX.ref, componentes: [ { staff:setX.staff } ]
      }, wsLineas, wsTF, {});
      _chk('setup X. primera sustitución OK', rX1.ok === true, JSON.stringify(rX1));
      var lineasAntesX = wsLineas.getDataRange().getValues().length;
      var rX2 = _lnSustituirServicioPorPromoStaffNativaInterno_({
        ticketRef: setX.ref, lineaOrigenId: setX.lineaOrigenId, staffSolicitante:setX.staff, promoCatalogoId:'PROMO-TEST-SUST-X',
        requestId:'RQ-SUST-X-' + setX.ref, componentes: [ { staff:'STAFF-ALT-X' } ]
      }, wsLineas, wsTF, {});
      var lineasDespuesX = wsLineas.getDataRange().getValues().length;
      _chk('X. mismo requestId, distinta staff → conflicto', rX2.error === 'PROMO_SUSTITUCION_REQUEST_CONFLICT', JSON.stringify(rX2));
      _chk('X. NO pasa por LINEA_PADRE_REQUERIDA_AMBIGUA/TM/LINE_NOT_FOUND/LINE_NOT_IN_TICKET',
           ['LINEA_PADRE_REQUERIDA_AMBIGUA','LINEA_PADRE_REQUERIDA_TM','LINE_NOT_FOUND','LINE_NOT_IN_TICKET']
             .indexOf(rX2.error) === -1, JSON.stringify(rX2));
      _chk('X. no crea líneas nuevas', lineasAntesX === lineasDespuesX);
    }

    // ── Y: mismo requestId, distinto lineaPadre → conflicto de idempotencia ─
    // Ticket TM con DOS padres válidos y distintos del mismo ticket (padre A
    // y padre B), para que el rechazo sea realmente por fingerprint y no por
    // "padre inválido". El componente que sustituye al origen no usa padre
    // del payload (se deriva); el componente ADICIONAL sí, y es el que
    // alterna entre padre A y padre B entre la primera y la segunda llamada.
    var refY = 'TM-TEST-SUST-Y-' + Date.now();
    refs.push(refY);
    var staffY = _lnStaffAisladaTest_(refY, 'Cejas');
    _tfRegistrarInterno(refY, 'LINEAS', 'NEXSERV', 'en_atencion', wsTF, _lnTfData_(wsTF));
    _tfActivarInterno(refY, wsTF, _lnTfData_(wsTF));
    var rPadreAY = crearLinea({
      visita: refY, ticketRef: refY, codigo:'C-TEST', cliente:'Test Sustitucion Y',
      staff: staffY, area:'cejas', servicio:'Padre A Y', esPromo:false,
      monto:1, montoRegular:1, estado:'en_servicio', authEstado:'no_requiere', origen:'NEXSERV',
      obs: '[NATIVE_REQUEST_ID:RQ-' + refY + '] [NATIVE_REQUEST_FP:FP-' + refY + '] ' +
           '[NATIVE_LINE_REQUEST_ID:RQ-L0-' + refY + '] [NATIVE_LINE_REQUEST_FP:FP-L0-' + refY + ']'
    });
    var rPadreBY = crearLinea({
      visita: refY, ticketRef: refY, codigo:'C-TEST', cliente:'Test Sustitucion Y',
      staff: staffY, area:'cejas', servicio:'Padre B Y', esPromo:false,
      monto:1, montoRegular:1, estado:'esperando', authEstado:'no_requiere', origen:'NEXSERV',
      obs: '[NATIVE_LINE_REQUEST_ID:RQ-PB-' + refY + '] [NATIVE_LINE_REQUEST_FP:FP-PB-' + refY + ']'
    });
    var rOrigenY = crearLinea({
      visita: refY, ticketRef: refY, codigo:'C-TEST', cliente:'Test Sustitucion Y',
      staff: staffY, area:'cejas', servicio:'Depilacion de cejas', esPromo:false,
      monto:10, montoRegular:10, estado:'esperando', authEstado:'no_requiere', origen:'NEXSERV',
      obs: '[NATIVE_LINE_REQUEST_ID:RQ-ORIGEN-' + refY + '] [NATIVE_LINE_REQUEST_FP:FP-ORIGEN-' + refY + ']'
    });
    _chk('setup Y. ticket TM + 2 padres + línea origen creados',
         !!(rPadreAY && rPadreAY.id && rPadreBY && rPadreBY.id && rOrigenY && rOrigenY.id),
         JSON.stringify({ padreA:rPadreAY, padreB:rPadreBY, origen:rOrigenY }));
    if (rPadreAY && rPadreAY.id && rPadreBY && rPadreBY.id && rOrigenY && rOrigenY.id) {
      _mockDivision([
        { servicio:'Depilacion de cejas', area:'cejas', staff:'', monto:10, regular:15 },
        { servicio:'Depilacion de bigote', area:'cejas', staff:'', monto:5,  regular:8 }
      ]);
      _mockStaffOk([staffY]);
      var rY1 = _lnSustituirServicioPorPromoStaffNativaInterno_({
        ticketRef: refY, lineaOrigenId: rOrigenY.id, staffSolicitante: staffY, promoCatalogoId:'PROMO-TEST-SUST-Y',
        requestId:'RQ-SUST-Y-' + refY,
        componentes: [ { staff:staffY }, { staff:staffY, lineaPadre:rPadreAY.id } ]
      }, wsLineas, wsTF, {});
      _chk('setup Y. primera sustitución OK (con padre A)', rY1.ok === true, JSON.stringify(rY1));

      var lineasAntesY = wsLineas.getDataRange().getValues().length;
      var rY2 = _lnSustituirServicioPorPromoStaffNativaInterno_({
        ticketRef: refY, lineaOrigenId: rOrigenY.id, staffSolicitante: staffY, promoCatalogoId:'PROMO-TEST-SUST-Y',
        requestId:'RQ-SUST-Y-' + refY, // MISMO requestId
        componentes: [ { staff:staffY }, { staff:staffY, lineaPadre:rPadreBY.id } ] // padre DISTINTO
      }, wsLineas, wsTF, {});
      var lineasDespuesY = wsLineas.getDataRange().getValues().length;
      _chk('Y. mismo requestId, distinto lineaPadre → conflicto de idempotencia',
           rY2.error === 'PROMO_SUSTITUCION_REQUEST_CONFLICT', JSON.stringify(rY2));
      _chk('Y. NO pasa por LINEA_PADRE_REQUERIDA_AMBIGUA/TM/LINE_NOT_FOUND/LINE_NOT_IN_TICKET',
           ['LINEA_PADRE_REQUERIDA_AMBIGUA','LINEA_PADRE_REQUERIDA_TM','LINE_NOT_FOUND','LINE_NOT_IN_TICKET']
             .indexOf(rY2.error) === -1, JSON.stringify(rY2));
      _chk('Y. no crea líneas nuevas en el reintento conflictivo', lineasAntesY === lineasDespuesY);
      var origenY = _lineaPorId(rOrigenY.id);
      _chk('Y. línea origen no se vuelve a tocar (sigue anulada por la primera ejecución, no por la segunda)',
           origenY && origenY.estado === 'anulado' &&
           String(origenY.motivoAnulacion || '').indexOf('sustitucion por promocion') === 0,
           JSON.stringify(origenY));
      var tfFilaY = _tfBuscarFilaInterno(refY, _lnTfData_(wsTF));
      _chk('Y. TicketsFuente queda intacto (en_atencion, sin nueva escritura por el conflicto)',
           tfFilaY && !tfFilaY.duplicado && tfFilaY.fila.estadoTicket === 'en_atencion', JSON.stringify(tfFilaY));
    }

  } finally {
    _restaurarMocks();
    refs.forEach(function (ref) {
      try {
        var datosLN = wsLineas.getDataRange().getValues();
        var idxRef = datosLN[0].indexOf('ticket_ref');
        var filasLN = [];
        for (var i = 1; i < datosLN.length; i++) {
          if (idxRef !== -1 && String(datosLN[i][idxRef] || '') === ref) filasLN.push(i + 1);
        }
        for (var k = filasLN.length - 1; k >= 0; k--) wsLineas.deleteRow(filasLN[k]);
        Logger.log('limpieza LINEAS (' + ref + '): ' + filasLN.length + ' fila(s) eliminadas');

        var datosTF = wsTF.getDataRange().getValues();
        var filasTF = [];
        for (var j = 1; j < datosTF.length; j++) {
          if (String(datosTF[j][0] || '') === ref) filasTF.push(j + 1);
        }
        for (var m = filasTF.length - 1; m >= 0; m--) wsTF.deleteRow(filasTF[m]);
        Logger.log('limpieza TicketsFuente (' + ref + '): ' + filasTF.length + ' fila(s) eliminadas');
      } catch (eCleanup) {
        Logger.log('⚠ Limpieza falló para ' + ref + ', revisar manualmente: ' + eCleanup);
      }
    });
  }

  Logger.log(fallos === 0
    ? '✅ RESULTADO FINAL PARTE C (V/W/X/Y — la corrección más delicada): OK (0 fallos)'
    : '❌ RESULTADO FINAL PARTE C (V/W/X/Y — la corrección más delicada): ' + fallos + ' fallo(s)');
}

function _test_sustituirServicioPorPromoStaffNativa_A() {
  var wsLineas = _hojaLineas(), wsTF = _tfHoja();
  var fallos = 0;
  var refs = [];
  var resolverOriginal = _resolverDivisionPromoNativa_;
  var validarStaffOriginal = _lnValidarStaffDestinoInterno_;

  function _chk(nombre, cond, detalle) {
    if (cond) { Logger.log('  ✅ ' + nombre); }
    else { fallos++; Logger.log('  ❌ ' + nombre + (detalle ? ' — ' + detalle : '')); }
  }
  function _mockDivision(division) {
    _resolverDivisionPromoNativa_ = function () { return { ok:true, division:division }; };
  }
  function _mockStaffOk(nombresValidos) {
    _lnValidarStaffDestinoInterno_ = function (nombre) {
      return (nombresValidos.indexOf(nombre) >= 0)
        ? { ok:true } : { ok:false, error:'STAFF_DESTINO_NO_ENCONTRADA' };
    };
  }
  function _mockStaffInactiva(nombreInactivo) {
    _lnValidarStaffDestinoInterno_ = function (nombre) {
      return (nombre === nombreInactivo)
        ? { ok:false, error:'STAFF_DESTINO_INACTIVA' } : { ok:true };
    };
  }
  function _restaurarMocks() {
    _resolverDivisionPromoNativa_ = resolverOriginal;
    _lnValidarStaffDestinoInterno_ = validarStaffOriginal;
  }
  function _lineaPorId(id) {
    var datos = wsLineas.getDataRange().getValues();
    for (var i = 1; i < datos.length; i++) {
      if (String(datos[i][LX.id] || '') === String(id)) return _filaAObjeto(datos[i]);
    }
    return null;
  }
  function _lineasDelGrupo(grupoId) {
    var datos = wsLineas.getDataRange().getValues();
    var out = [];
    for (var i = 1; i < datos.length; i++) {
      if (String(datos[i][LX.grupoPromoId] || '') === String(grupoId)) out.push(_filaAObjeto(datos[i]));
    }
    return out;
  }
  function _setupTicketConLineaOrigen(sufijo, familia, servicioOrigen, areaOrigen, iniciarEnServicio) {
    var ref = 'T-TEST-SUST-' + sufijo + '-' + Date.now() + '-' + Math.floor(Math.random() * 100000);
    var staff = _lnStaffAisladaTest_(ref, familia || 'Cejas');
    // La primera línea del ticket es una línea BASE genérica, sin relación con
    // lo que se está probando. Se inicia de una (igual que
    // _test_solicitarPromoExtraStaffNativa caso B) para que TicketsFuente
    // pase a en_atencion — requisito de _lnValidarTicketParaExtraInterno_
    // para actor STAFF. La línea ORIGEN real bajo prueba se crea aparte,
    // como línea adicional, con el estado exacto que cada caso necesita.
    var rTk = _crearTicketNativoInterno_({
      codigo:'C-TEST', cliente:'Test Sustitucion ' + sufijo, origen:'NEXSERV', requestId:'RQ-' + ref,
      primeraLinea: { area: areaOrigen, servicio: 'Linea base ' + sufijo, monto: 1, montoRegular: 1 }
    }, wsLineas, wsTF, { modoTest:true, ticketRefPrueba: ref });
    if (!rTk.ok) return { ok:false, ref:ref, error:rTk.error };
    var lineaBaseId = rTk.linea_id;

    var rIniBase = _iniciarLineaNativaInterno_({ ticketRef: ref, lineaId: lineaBaseId, staff: staff },
      wsLineas, wsTF, _lnOptsPuestosTest_());
    if (!rIniBase.ok) return { ok:false, ref:ref, error:'setup iniciar línea base falló: ' + rIniBase.error };

    var rOrigen = crearLinea({
      visita: ref, ticketRef: ref, codigo:'C-TEST', cliente:'Test Sustitucion ' + sufijo,
      staff: staff, area: areaOrigen, servicio: servicioOrigen, esPromo:false,
      monto: 10, montoRegular: 10, estado: iniciarEnServicio ? 'en_servicio' : 'esperando',
      authEstado: 'no_requiere', origen:'NEXSERV',
      obs: '[NATIVE_LINE_REQUEST_ID:RQ-ORIGEN-' + ref + '] [NATIVE_LINE_REQUEST_FP:FP-ORIGEN-' + ref + ']'
    });
    if (!rOrigen || !rOrigen.id) return { ok:false, ref:ref, error:'no se pudo crear la línea origen de prueba' };

    return { ok:true, ref:ref, staff:staff, lineaOrigenId:rOrigen.id, lineaBaseId:lineaBaseId };
  }

  try {
    var setA = _setupTicketConLineaOrigen('A', 'Cejas', 'Depilacion de cejas', 'cejas', false);
    _chk('setup A. ticket + línea origen (esperando)', setA.ok, setA.error);
    if (setA.ok) {
      refs.push(setA.ref);
      _mockDivision([
        { servicio:'Depilacion de cejas', area:'cejas', staff:'', monto:10, regular:15 },
        { servicio:'Depilacion de bigote', area:'cejas', staff:'', monto:5,  regular:8 }
      ]);
      _mockStaffOk([setA.staff]);
      var rA = _lnSustituirServicioPorPromoStaffNativaInterno_({
        ticketRef: setA.ref, lineaOrigenId: setA.lineaOrigenId, staffSolicitante:setA.staff, promoCatalogoId:'PROMO-TEST-SUST-A',
        requestId:'RQ-SUST-A-' + setA.ref,
        componentes: [ { staff:setA.staff }, { staff:setA.staff } ]
      }, wsLineas, wsTF, {});
      _chk('A. sustitución OK, 2 componentes creados', rA.ok === true && rA.componentes_ids.length === 2, JSON.stringify(rA));

      if (rA.ok) {
        var origenA = _lineaPorId(setA.lineaOrigenId);
        _chk('B. línea origen anulada con motivo de sustitución',
             origenA && origenA.estado === 'anulado' && String(origenA.motivoAnulacion || '').indexOf('sustitucion por promocion') === 0,
             JSON.stringify(origenA));

        var compsA = _lineasDelGrupo(rA.grupo_promo_id);
        _chk('C. exactamente 2 componentes en el grupo', compsA.length === 2, JSON.stringify(compsA));

        var compCejasA = compsA.filter(function (l) { return l.servicio === 'Depilacion de cejas'; })[0];
        var compBigoteA = compsA.filter(function (l) { return l.servicio === 'Depilacion de bigote'; })[0];
        _chk('D. servicio/área/precios vienen del catálogo',
             compCejasA && compCejasA.monto === 10 && compBigoteA && compBigoteA.monto === 5,
             JSON.stringify(compsA));
        _chk('E. componente equivalente hereda el padre operativo del origen',
             compCejasA && String(compCejasA.lineaPadre || '') === lineaPadreOrigenEsperado_A(setA),
             JSON.stringify(compCejasA));
        _chk('F. origen esperando → ambos componentes nacen esperando',
             compCejasA && compCejasA.estado === 'esperando' && compBigoteA && compBigoteA.estado === 'esperando',
             JSON.stringify(compsA));
        _chk('G. cada componente guarda la staff correcta',
             compCejasA && compCejasA.staff === setA.staff && compBigoteA && compBigoteA.staff === setA.staff,
             JSON.stringify(compsA));

        var tfFilaA = _tfBuscarFilaInterno(setA.ref, _lnTfData_(wsTF));
        _chk('I. TicketsFuente permanece en_atencion (reconciliado)',
             tfFilaA && !tfFilaA.duplicado && tfFilaA.fila.estadoTicket === 'en_atencion',
             JSON.stringify(tfFilaA));

      }
    }
    // ── caso adicional exigido por la orden: origen EN_SERVICIO ───────────
    var setEnServ = _setupTicketConLineaOrigen('ENSERV', 'Cejas', 'Depilacion de cejas', 'cejas', true);
    _chk('setup EnServicio. ticket + línea origen en_servicio', setEnServ.ok, setEnServ.error);
    if (setEnServ.ok) {
      refs.push(setEnServ.ref);
      _mockDivision([
        { servicio:'Depilacion de cejas', area:'cejas', staff:'', monto:10, regular:15 },
        { servicio:'Depilacion de bigote', area:'cejas', staff:'', monto:5,  regular:8 }
      ]);
      _mockStaffOk([setEnServ.staff]);
      var rES = _lnSustituirServicioPorPromoStaffNativaInterno_({
        ticketRef: setEnServ.ref, lineaOrigenId: setEnServ.lineaOrigenId, staffSolicitante:setEnServ.staff, promoCatalogoId:'PROMO-TEST-SUST-ENSERV',
        requestId:'RQ-SUST-ENSERV-' + setEnServ.ref,
        componentes: [ { staff:setEnServ.staff }, { staff:setEnServ.staff } ]
      }, wsLineas, wsTF, {});
      _chk('EnServicio. sustitución OK', rES.ok === true, JSON.stringify(rES));
      if (rES.ok) {
        var compsES = _lineasDelGrupo(rES.grupo_promo_id);
        var compCejasES = compsES.filter(function (l) { return l.servicio === 'Depilacion de cejas'; })[0];
        var compBigoteES = compsES.filter(function (l) { return l.servicio === 'Depilacion de bigote'; })[0];
        _chk('EnServicio. componente que sustituye al origen nace en_servicio',
             compCejasES && compCejasES.estado === 'en_servicio', JSON.stringify(compCejasES));
        _chk('EnServicio. componente adicional nace esperando (no ejecutado aún)',
             compBigoteES && compBigoteES.estado === 'esperando', JSON.stringify(compBigoteES));
      }
    }

    // ── EMPTYSTAFF: componente adicional sin staff → nace 'esperando' sin
    // dueña (cola de Mikaela); el componente que sustituye al origen SIGUE
    // exigiendo staff.
    var setES2 = _setupTicketConLineaOrigen('EMPTYSTAFF', 'Cejas', 'Depilacion de cejas', 'cejas', false);
    _chk('setup EMPTYSTAFF. ticket creado', setES2.ok, setES2.error);
    if (setES2.ok) {
      refs.push(setES2.ref);
      _mockDivision([
        { servicio:'Depilacion de cejas', area:'cejas', staff:'', monto:10, regular:15 },
        { servicio:'Depilacion de pestañas', area:'pestanas', staff:'', monto:12, regular:18 }
      ]);
      _mockStaffOk([setES2.staff]);
      var rES2 = _lnSustituirServicioPorPromoStaffNativaInterno_({
        ticketRef: setES2.ref, lineaOrigenId: setES2.lineaOrigenId, staffSolicitante:setES2.staff,
        promoCatalogoId:'PROMO-TEST-SUST-EMPTYSTAFF', requestId:'RQ-SUST-EMPTYSTAFF-' + setES2.ref,
        componentes: [ { staff:setES2.staff }, { staff:'' } ] // adicional SIN staff
      }, wsLineas, wsTF, {});
      _chk('EMPTYSTAFF. sustitución OK con componente adicional sin staff',
           rES2.ok === true, JSON.stringify(rES2));
      if (rES2.ok) {
        var compsES2 = _lineasDelGrupo(rES2.grupo_promo_id);
        var compCejasES2 = compsES2.filter(function (l) { return l.servicio === 'Depilacion de cejas'; })[0];
        var compPestES2 = compsES2.filter(function (l) { return l.servicio === 'Depilacion de pestañas'; })[0];
        _chk('EMPTYSTAFF. componente origen SÍ tiene staff', compCejasES2 && compCejasES2.staff === setES2.staff, JSON.stringify(compCejasES2));
        _chk('EMPTYSTAFF. componente adicional queda sin staff, esperando',
             compPestES2 && String(compPestES2.staff || '') === '' && compPestES2.estado === 'esperando',
             JSON.stringify(compPestES2));
      }
      // El componente que SUSTITUYE al origen sigue exigiendo staff, aunque
      // sea el único componente de la promo.
      var setES3 = _setupTicketConLineaOrigen('EMPTYSTAFF2', 'Cejas', 'Depilacion de cejas', 'cejas', false);
      if (setES3.ok) {
        refs.push(setES3.ref);
        _mockDivision([{ servicio:'Depilacion de cejas', area:'cejas', staff:'', monto:10, regular:15 }]);
        var rES3 = _lnSustituirServicioPorPromoStaffNativaInterno_({
          ticketRef: setES3.ref, lineaOrigenId: setES3.lineaOrigenId, staffSolicitante:setES3.staff,
          promoCatalogoId:'PROMO-TEST-SUST-EMPTYSTAFF2', requestId:'RQ-SUST-EMPTYSTAFF2-' + setES3.ref,
          componentes: [ { staff:'' } ] // el ÚNICO componente ES el origen — no puede venir vacío
        }, wsLineas, wsTF, {});
        _chk('EMPTYSTAFF2. componente-origen sin staff → STAFF_REQUERIDO', rES3.error === 'STAFF_REQUERIDO', JSON.stringify(rES3));
      }
    }

    // ── J: promo incompatible con servicio origen → rechazo sin escritura ──
    var setJ = _setupTicketConLineaOrigen('J', 'Cejas', 'Depilacion de cejas', 'cejas', false);
    _chk('setup J. ticket creado', setJ.ok, setJ.error);
    if (setJ.ok) {
      refs.push(setJ.ref);
      _mockDivision([
        { servicio:'Servicio totalmente distinto', area:'facial', staff:'', monto:20, regular:25 }
      ]);
      var lineasAntesJ = wsLineas.getDataRange().getValues().length;
      var rJ = _lnSustituirServicioPorPromoStaffNativaInterno_({
        ticketRef: setJ.ref, lineaOrigenId: setJ.lineaOrigenId, staffSolicitante:setJ.staff, promoCatalogoId:'PROMO-TEST-SUST-J',
        requestId:'RQ-SUST-J-' + setJ.ref, componentes:[ { staff:setJ.staff } ]
      }, wsLineas, wsTF, {});
      var lineasDespuesJ = wsLineas.getDataRange().getValues().length;
      _chk('J. promo incompatible → PROMO_SUSTITUCION_NO_COMPATIBLE', rJ.error === 'PROMO_SUSTITUCION_NO_COMPATIBLE', JSON.stringify(rJ));
      _chk('J. cero escrituras (línea origen intacta, sin componentes)', lineasAntesJ === lineasDespuesJ);
      var origenJ = _lineaPorId(setJ.lineaOrigenId);
      _chk('J. línea origen sigue esperando (no anulada)', origenJ && origenJ.estado === 'esperando', JSON.stringify(origenJ));
    }

  } finally {
    _restaurarMocks();
    refs.forEach(function (ref) {
      try {
        var datosLN = wsLineas.getDataRange().getValues();
        var idxRef = datosLN[0].indexOf('ticket_ref');
        var filasLN = [];
        for (var i = 1; i < datosLN.length; i++) {
          if (idxRef !== -1 && String(datosLN[i][idxRef] || '') === ref) filasLN.push(i + 1);
        }
        for (var k = filasLN.length - 1; k >= 0; k--) wsLineas.deleteRow(filasLN[k]);
        Logger.log('limpieza LINEAS (' + ref + '): ' + filasLN.length + ' fila(s) eliminadas');

        var datosTF = wsTF.getDataRange().getValues();
        var filasTF = [];
        for (var j = 1; j < datosTF.length; j++) {
          if (String(datosTF[j][0] || '') === ref) filasTF.push(j + 1);
        }
        for (var m = filasTF.length - 1; m >= 0; m--) wsTF.deleteRow(filasTF[m]);
        Logger.log('limpieza TicketsFuente (' + ref + '): ' + filasTF.length + ' fila(s) eliminadas');
      } catch (eCleanup) {
        Logger.log('⚠ Limpieza falló para ' + ref + ', revisar manualmente: ' + eCleanup);
      }
    });
  }

  Logger.log(fallos === 0
    ? '✅ RESULTADO FINAL PARTE A (A/EnServicio/J): OK (0 fallos)'
    : '❌ RESULTADO FINAL PARTE A (A/EnServicio/J): ' + fallos + ' fallo(s)');
}

