function _mkLinea(data, props) {
  var fila = new Array(LINEAS_HEADERS.length).fill('');
  var keys = Object.keys(props || {});
  for (var i = 0; i < keys.length; i++) {
    var k = keys[i];
    if (Object.prototype.hasOwnProperty.call(LX, k)) fila[LX[k]] = props[k];
  }
  data.push(fila);
  return fila;
}
function _tChk(name, cond, detail) {
  return { name: name, ok: !!cond, detail: cond ? '' : ('FAIL ' + name + (detail != null ? (' :: ' + detail) : '')) };
}
function _runAll(t, cond) {
  var fails = [];
  for (var i = 0; i < t.length; i++) { if (!t[i].ok) fails.push(t[i].detail); }
  return { pass: fails.length === 0, total: t.length, fallos: fails };
}
